"use strict";(self.webpackChunkciroh_docuhub=self.webpackChunkciroh_docuhub||[]).push([["29719"],{93004(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"summer-institute-flash-flood","metadata":{"permalink":"/staging/main/blog/summer-institute-flash-flood","source":"@site/blog/2026-08-24-Summer-Institute-Flash-Flood.mdx","title":"NextGen In A Box (NGIAB) and CIROH Cyberinfrastructure Power Flash Flood Research at the 2026 Summer Institute","description":"Ten graduate students in three teams had seven weeks to bring sub-hourly radar rainfall, precipitation uncertainty, and ensemble forecasting methods into the NextGen Water Resources Modeling Framework. Here\'s how NGIAB and CIROH cyberinfrastructure carried the load.","date":"2026-08-24T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Summer Institute","permalink":"/staging/main/blog/tags/summer-institute"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"Flash Flood","permalink":"/staging/main/blog/tags/flash-flood"},{"inline":true,"label":"Jetstream2","permalink":"/staging/main/blog/tags/jetstream-2"},{"inline":true,"label":"NSF Access","permalink":"/staging/main/blog/tags/nsf-access"},{"inline":true,"label":"MRMS","permalink":"/staging/main/blog/tags/mrms"},{"inline":true,"label":"HydroShare","permalink":"/staging/main/blog/tags/hydro-share"},{"inline":true,"label":"Cloud Services","permalink":"/staging/main/blog/tags/cloud-services"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"R2OHC","permalink":"/staging/main/blog/tags/r-2-ohc"},{"inline":true,"label":"CIROH Community Resources","permalink":"/staging/main/blog/tags/ciroh-community-resources"}],"readingTime":7.03,"hasTruncateMarker":false,"authors":[{"name":"Alex Lastner","title":"Graduate Student","title2":"University of Maryland, College Park","url":"https://www.geol.umd.edu/alexanderlastner","imageURL":"/staging/main/img/blog/authors/alex-lastner.jpg","key":"alex-lastner","page":null},{"name":"Danna Villarreal","title":"PhD Student","title2":"University of Arkansas","url":"https://muenichlab.uark.edu/team/","imageURL":"/staging/main/img/blog/authors/danna-villarreal.jpg","key":"danna-villarreal","page":null},{"name":"Bikas Gupta","title":"PhD Student","title2":"University of Texas at Arlington","url":"https://www.linkedin.com/in/bikas-chandra-gupta-48881b153","imageURL":"/staging/main/img/blog/authors/bikas-gupta.jpg","key":"bikas-gupta","page":null},{"name":"Jessica Keiser","title":"Master\'s Student","title2":"San Diego State University","url":"https://geography.sdsu.edu/people/students","imageURL":"/staging/main/img/blog/authors/jessica-keiser.jpg","key":"jessica-keiser","page":null},{"name":"Leo Lonzarich","title":"Graduate Researcher","title2":"Pennsylvania State University","url":"https://www.linkedin.com/in/leoglonz","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U075PFL5NUE-150fbf871a79-512","key":"leo","page":null},{"name":"Azizur Rahman","title":"PhD Student","title2":"University of Texas at Arlington","imageURL":"/staging/main/img/blog/authors/azizur-rahman.jpg","key":"azizur-rahman","page":null},{"name":"Aldo Andres Tapia Araya","title":"PhD Student, Hydrology","title2":"The University of Arizona","url":"https://has.arizona.edu/person/aldo-andres-tapia-araya","imageURL":"/staging/main/img/blog/authors/aldo-tapia-araya.jpg","key":"aldo-tapia-araya","page":null},{"name":"Amirhossein Montazeri","title":"PhD Student, Computing (Data Science emphasis)","title2":"Boise State University","url":"https://www.boisestate.edu/computing/about-us/computingdirectory/current-students-directory/amirhossein-montazeri/","imageURL":"/staging/main/img/blog/authors/amirhossein-montazeri.jpg","key":"amirhossein-montazeri","page":null},{"name":"Niloufar Soheili","title":"PhD Student, Water Resources and Environmental Engineering","title2":"The City College of New York (CUNY)","url":"https://www.ccny.cuny.edu/profiles/niloufar-soheili","imageURL":"/staging/main/img/blog/authors/niloufar-soheili.jpg","key":"niloufar-soheili","page":null},{"name":"Mohammad Mosavat","title":"PhD Student","title2":"The University of Alabama","url":"https://moradkhani.ua.edu/people","imageURL":"/staging/main/img/blog/authors/mohammad-mosavat.jpg","key":"mohammad-mosavat","page":null},{"name":"Mohamed Abdelkader","title":"Assistant Research Scientist","title2":"University of Iowa","url":"https://iihr.uiowa.edu/people/mohamed-abdelkader","imageURL":"/staging/main/img/blog/authors/mohamed-abdelkader.jpg","key":"mohamed-abdelkader","page":null},{"name":"Humberto Vergara","title":"Assistant Professor, University of Iowa","title2":"Associate Director, Iowa Flood Center","url":"https://engineering.uiowa.edu/directory/humberto-vergara","imageURL":"/staging/main/img/blog/authors/humberto-vergara.jpg","key":"humberto-vergara","page":null}],"frontMatter":{"title":"NextGen In A Box (NGIAB) and CIROH Cyberinfrastructure Power Flash Flood Research at the 2026 Summer Institute","description":"Ten graduate students in three teams had seven weeks to bring sub-hourly radar rainfall, precipitation uncertainty, and ensemble forecasting methods into the NextGen Water Resources Modeling Framework. Here\'s how NGIAB and CIROH cyberinfrastructure carried the load.","slug":"summer-institute-flash-flood","authors":["alex-lastner","danna-villarreal","bikas-gupta","jessica-keiser","leo","azizur-rahman","aldo-tapia-araya","amirhossein-montazeri","niloufar-soheili","mohammad-mosavat","mohamed-abdelkader","humberto-vergara"],"tags":["Blog","CIROH","Summer Institute","NextGen","NGIAB","Flash Flood","Jetstream2","NSF Access","MRMS","HydroShare","Cloud Services","National Water Model","R2OHC","CIROH Community Resources"],"hide_table_of_contents":false},"unlisted":false,"nextItem":{"title":"CIROH Flood Inundation Mapping (FIM) Community Ecosystem: A Large-Scale Operational Flood Modeling-to-Evaluation Framework","permalink":"/staging/main/blog/fim-community-ecosystem"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\nOn July 4, 2025, a flash flood on the Guadalupe River caused 119 fatalities in Kerr County, Texas.\\nIt was the deadliest flash flood in the United States since 1976, and a reminder that flash floods\\nremain among the most dangerous weather hazards in the country. Forecasting them means working at\\nthe speed and scale of the storm: small basins, minutes to hours, and rainfall estimates that can\\nmake or break the prediction.\\n\\nThat challenge set the agenda for our theme at the 2026 Water Prediction Innovators Summer Institute:\\n**Advancing the Use of Quantitative Precipitation Inputs into the NextGen Framework**. Ten graduate\\nstudents in three teams (Don\'t Runoff!, FlashCast, and The Post-Processors) had seven weeks to bring\\nsub-hourly radar rainfall, precipitation uncertainty, and ensemble forecasting methods into the\\nNextGen Water Resources Modeling Framework. Seven weeks is not much, and the teams could not spend half\\nof it compiling a modeling framework or downloading terabytes of radar data to laptops. Fortunately, they did\\nnot have to. The CIROH cyberinfrastructure team carried that load.\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   src={useBaseUrl(\'/img/blog/2026-08-summer-institute/dont-runoff-team.png\')}\\n   width=\'100%\'\\n   alt=\\"Team Don\'t Runoff! members Leo Lonzarich, Azizur Rahman, and Jessica Keiser.\\"\\n   />\\n  <figcaption><em>Team Don\'t Runoff! (left to right): Leo Lonzarich, Azizur Rahman, Jessica Keiser.</em></figcaption>\\n</figure>\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   src={useBaseUrl(\'/img/blog/2026-08-summer-institute/flashcast-team.png\')}\\n   width=\'100%\'\\n   alt=\\"Team FlashCast members Alex Lastner, Danna Villarreal, and Bikas Gupta.\\"\\n   />\\n  <figcaption><em>Team FlashCast (left to right): Alex Lastner, Danna Villarreal, Bikas Gupta.</em></figcaption>\\n</figure>\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   src={useBaseUrl(\'/img/blog/2026-08-summer-institute/post-processors-team.png\')}\\n   width=\'100%\'\\n   alt=\\"Team The Post-Processors members Mohammad Mosavat, Niloufar Soheili, Aldo Andres Tapia Araya, and Amirhossein Montazeri.\\"\\n   />\\n  <figcaption><em>Team The Post-Processors (left to right): Mohammad Mosavat, Niloufar Soheili, Aldo Andres Tapia Araya, Amirhossein Montazeri.</em></figcaption>\\n</figure>\\n\\n## The framework fits in the Box\\n\\nNextGen is powerful but challenging to run. NextGen In A Box (NGIAB), CIROH\'s containerized\\ndistribution with more than 41,000 Docker pulls, turns that setup problem into a single pull\\ncommand. This year\'s Summer Institute members were able to hit the ground running after\\njust a single one-hour NGIAB workshop, demonstrating its sheer accessibility.\\n\\nHowever, the teams did more than just run it. NGIAB is also an *open* box, and they took full\\nadvantage by extending it:\\n\\n- **FlashCast** built a modified NGIAB Docker image that runs CFE and T-Route on a 15 minute\\n  timestep and forced it with 15 minute MRMS radar rainfall, expanding the framework\'s standard\\n  hourly configuration to the sub-hourly scales flash floods demand.\\n- **The Post-Processors** modified the NGIAB data preprocess library so NextGen could ingest MRMS\\n  radar estimates and HRRR forecast rainfall in place of the default AORC forcing. They then simulated\\n  8,474 catchments around Ellicott City, Maryland.\\n- **Don\'t Runoff!** built a volume-preserving workflow that maps 2 minute, 1 km MRMS rainfall onto\\n  NextGen Hydrofabric catchments and used it to drive dHBV2-Flash, a new sub-hourly differentiable\\n  model designed for the framework.\\n\\nEvery modification lives in a container or a public repository. Any researcher can pull the same\\nimage, rerun the same experiment, and build on it. That is the point of the box: NGIAB enables \\nmaximal portability and reproducibility to maximize research\'s impact. For the complete set of shared\\nresources, see each team\'s [final report](https://www.hydroshare.org/resource/7b2b22d88a914bb79b3f48e5ea3ecaaf/).\\n\\n## R2OHC Platform: NSF Jetstream2 and NGIAB did the heavy lifting\\n\\nNone of this fits on a laptop. FlashCast alone ran 2,280 simulation scenarios per basin across\\nthree flash flood case studies (Asheville NC, Pittsburgh PA, and Kerrville TX) \u2014 6,840 NextGen runs\\nin total. The Post-Processors pushed 500 synthetic storms through NGIAB to train a neural network\\nsurrogate, on top of storm displacement experiments across thousands of catchments. Don\'t Runoff!\\nprocessed radar rainfall for over 5,000 flash flood events across the country and trained a\\ndifferentiable model on years of 15-minute data.\\n\\nThe computing resources came from CIROH cyberinfrastructure, which provided allocations on\\n[NSF Jetstream2](/docs/services/external-resources/nsf-access/jetstream), Indiana University\'s\\nNSF-funded academic cloud, through CIROH\'s ACCESS allocation (EES240087). JetStream2 hosted virtual machines\\nsized for each team\'s workload, from batch NGIAB runs to model training. The rainfall came from\\nNOAA open data: 2-minute MRMS radar estimates, hourly AORC forcings, and HRRR forecasts, all pulled\\nstraight from public cloud archives. [CUAHSI HydroShare](https://www.hydroshare.org/)\\nclosed the loop as the publication home for datasets and supplementary materials, and the\\n[NWC-CUAHSI-Summer-Institute GitHub organization](https://github.com/nwc-cuahsi-summer-institute)\\nhosts the code.\\n\\n## What the teams built\\n\\n**Team Don\'t Runoff!** delivered [RUNOFF v1.0](https://nwc-cuahsi-summer-institute.github.io/runoff/),\\na CONUS-scale catalog of over 5,000 flash flood\\nevents from the NOAA Storm Events Database, each mapped to hydrofabric catchments and paired with a\\nUSGS gauge and quality-controlled MRMS rainfall. RUNOFF is designed to conduct flash flood modeling\\nexperiments using high-quality precipitation estimates. They also delivered\\n[dHBV2-Flash](https://github.com/NWC-CUAHSI-Summer-Institute/dhbv2-flash), a\\n15-minute differentiable rainfall-runoff model that captured event peaks in the Upper Neuse basin\\nwith a median peak flow bias of 16% across 1,132 events. Supplementary materials are on\\n[HydroShare](https://hydroshare.org/resource/761d02556fbe4100809e17eaef44edd9/).\\n\\n**Team FlashCast** addressed a question at the heart of flash flood prediction: how fine, and how\\naccurate, does the precipitation input need to be? Their\\n[sensitivity pipeline](https://github.com/NWC-CUAHSI-Summer-Institute/nextgen_spatiotemporal_sensitivity)\\nconverts thousands of\\nNGIAB runs into critical uncertainty matrices, the precipitation uncertainty a forecast can tolerate\\nbefore predictions stop being actionable. Early results from the three case studies point to a\\nscale-dependent answer: for these events, resolution finer than about 7 km and 1 hour added little\\non its own, as long as storm volume was preserved. The pipeline is built to put that threshold to\\nthe test across many more basins and storms. Methods and figures are on\\n[HydroShare](https://www.hydroshare.org/resource/96f00a9eaef44b3ba4c00ddb24f70087/).\\n\\n**The Post-Processors** built [NCET](https://github.com/NWC-CUAHSI-Summer-Institute/NCET-data-preprocess),\\nthe Neighboring Catchment Ensemble Technique, which turns a\\nsingle deterministic NextGen simulation into an ensemble streamflow forecast by borrowing\\nhydrographs from neighboring catchments. Applied to the May 2018 Ellicott City flash flood with a\\nreal HRRR forecast, NCET recovered a flood the deterministic forecast missed, with the largest gains\\nin probabilistic skill when the ensemble weights were aimed along the storm\'s displacement. That\\nearly result suggests storm location, more than catchment similarity, should steer the ensemble, and\\nit points to a computationally inexpensive path toward flash flood forecasting within NextGen. The\\nteam also prototyped Replace and Route, a BMI component that lets NextGen borrow discharge from\\nhigh-fidelity external models at hydrofabric nexus points. Evaluation materials are on HydroShare.\\n\\n## From asking research questions to prototyping workflows, in seven weeks\\n\\nEach product is [hydrofabric](/docs/products/ngiab-ecosystem/dependencies/hydrofabric/)-native,\\nopen, and packaged into containers, BMI modules, and reproducible pipelines \u2014 the way that the\\nCommunity NextGen ecosystem expects. This ease of access and reuse is research to operations in miniature,\\nand it is what CIROH cyberinfrastructure is for. NGIAB collapsed setup time from weeks to minutes.\\nNSF\'s Jetstream2 scaled experiments beyond what any student laptop could run. Open data archives fed\\nthe models, and HydroShare and GitHub made every result citable and reusable. The students arrived\\nwith research questions. They left behind open prototypes, datasets, and code for the community to\\nbuild on.\\n\\n---\\n\\n*The 2026 Water Prediction Innovators Summer Institute took place June 8 \u2014 July 22, 2026. 24 graduate\\nstudent fellows from 21 unique U.S. institutions formed research teams under the guidance of seven\\nTheme Leaders, spanning topics from precipitation forecasting to flood risk communication. Research\\noutcomes are summarized in the\\n[2026 WPI SI final report](https://www.hydroshare.org/resource/7b2b22d88a914bb79b3f48e5ea3ecaaf/).*\\n\\n*The teams thank the CIROH Cyberinfrastructure & DevOps team and Hydroinformatics team at the\\nAlabama Water Institute (Arpita Patel, Josh Cunningham, Quinn Lee, Nia Minor, and colleagues) for\\ncloud provisioning and NextGen support throughout the program, Dr. Fred Ogden for guidance on\\ndevelopments with the NextGen framework, and the Summer Institute coordinators, Megan Vardaman and\\nNana Oye Djan. This work used Jetstream2 through allocation EES240087 from the NSF ACCESS program.\\nThis research was supported by the Cooperative Institute for Research to Operations in Hydrology\\n(CIROH) under award NA22NWS4320003 from the NOAA Cooperative Institute Program.*"},{"id":"fim-community-ecosystem","metadata":{"permalink":"/staging/main/blog/fim-community-ecosystem","source":"@site/blog/2026-08-20-FIM-Ecosystem.mdx","title":"CIROH Flood Inundation Mapping (FIM) Community Ecosystem: A Large-Scale Operational Flood Modeling-to-Evaluation Framework","description":"A large-scale, cloud-native, open-source ecosystem for flood inundation modeling, simulation, benchmarking, and evaluation, built at the University of Alabama\'s Surface Dynamics Modeling Lab with support from CIROH.","date":"2026-08-20T00:00:00.000Z","tags":[{"inline":true,"label":"Flooding","permalink":"/staging/main/blog/tags/flooding"},{"inline":true,"label":"Flood Inundation Mapping","permalink":"/staging/main/blog/tags/flood-inundation-mapping"},{"inline":true,"label":"Operational Research","permalink":"/staging/main/blog/tags/operational-research"},{"inline":true,"label":"Large-Scale","permalink":"/staging/main/blog/tags/large-scale"},{"inline":true,"label":"Hydrology","permalink":"/staging/main/blog/tags/hydrology"},{"inline":true,"label":"HAND","permalink":"/staging/main/blog/tags/hand"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"Benchmarking","permalink":"/staging/main/blog/tags/benchmarking"},{"inline":true,"label":"Evaluation","permalink":"/staging/main/blog/tags/evaluation"},{"inline":true,"label":"Remote Sensing","permalink":"/staging/main/blog/tags/remote-sensing"},{"inline":true,"label":"Hydrodynamic Modeling","permalink":"/staging/main/blog/tags/hydrodynamic-modeling"}],"readingTime":25.22,"hasTruncateMarker":false,"authors":[{"name":"Supath Dhital","title":"Geography Researcher II","title2":"The University of Alabama","url":"https://www.linkedin.com/in/supathdh/","imageURL":"/staging/main/img/profiles/Supath_Dhital.jpg","key":"supath-dhital","page":null},{"name":"Dipsikha Devi","title":"Postdoctoral Researcher","title2":"The University of Alabama","url":"https://www.linkedin.com/in/dipsikha-devi-ph-d-83b97781/","imageURL":"/staging/main/img/profiles/Dipsikha_Devi.jpg","key":"dipsikha-devi","page":null},{"name":"Anupal Baruah","title":"Research Scientist","title2":"The University of Alabama","url":"https://www.linkedin.com/in/anupal-baruah-23727176/","imageURL":"/staging/main/img/profiles/Anupal_Baruah.jpg","key":"anupal-baruah","page":null},{"name":"Dinuke Munasinghe","title":"Research Scientist","title2":"The University of Alabama","url":"https://www.linkedin.com/in/dinuke-munasinghe/","imageURL":"/staging/main/img/profiles/Dinuke_Munasinghe.jpg","key":"dinuke-munasinghe","page":null},{"name":"Parvaneh Nikrou","title":"PhD Candidate","title2":"The University of Alabama","url":"https://www.linkedin.com/in/parvaneh-nikrou/","imageURL":"/staging/main/img/profiles/Parvaneh_Nikrou.jpg","key":"parvaneh-nikrou","page":null},{"name":"Dan Tian","title":"Postdoctoral Researcher","title2":"The University of Alabama","url":"https://www.linkedin.com/in/dan-tian-0841862a4/","imageURL":"/staging/main/img/profiles/Dan_Tian.jpg","key":"dan-tian","page":null},{"name":"Yixian Chen","title":"Research Scientist","title2":"The University of Alabama","url":"https://www.linkedin.com/in/yixian-chen-765583166/","imageURL":"/staging/main/img/profiles/Yixian_Chen.jpg","key":"yixian-chen","page":null},{"name":"Sagy Cohen","title":"Professor","title2":"The University of Alabama","url":"https://www.linkedin.com/in/sagy-cohen-975b045a/","imageURL":"/staging/main/img/profiles/Sagy_Cohen.jpg","key":"sagy-cohen","page":null}],"frontMatter":{"title":"CIROH Flood Inundation Mapping (FIM) Community Ecosystem: A Large-Scale Operational Flood Modeling-to-Evaluation Framework","description":"A large-scale, cloud-native, open-source ecosystem for flood inundation modeling, simulation, benchmarking, and evaluation, built at the University of Alabama\'s Surface Dynamics Modeling Lab with support from CIROH.","slug":"fim-community-ecosystem","tags":["Flooding","Flood Inundation Mapping","Operational Research","Large-Scale","Hydrology","HAND","National Water Model","Benchmarking","Evaluation","Remote Sensing","Hydrodynamic Modeling"],"authors":["supath-dhital","dipsikha-devi","anupal-baruah","dinuke-munasinghe","parvaneh-nikrou","dan-tian","yixian-chen","sagy-cohen"],"image":"/img/blog/2026-08-fim-ecosystem/ecosystem-overview.png"},"unlisted":false,"prevItem":{"title":"NextGen In A Box (NGIAB) and CIROH Cyberinfrastructure Power Flash Flood Research at the 2026 Summer Institute","permalink":"/staging/main/blog/summer-institute-flash-flood"},"nextItem":{"title":"Powering CIROH DevCon 2026: How CIROH and 2i2c Ran Cloud Computing at Scale","permalink":"/staging/main/blog/devcon26-infra"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\nimport ProfileCards from \'/src/components/ProfileCards\';\\n\\nexport const fimProfiles = [\\n  {\\n    name: \'Supath Dhital\',\\n    title: \'Geography Researcher II\',\\n    organization: \'The University of Alabama\',\\n    imagePath: \'/img/profiles/Supath_Dhital.jpg\',\\n  },\\n  {\\n    name: \'Dipsikha Devi\',\\n    title: \'Postdoctoral Researcher\',\\n    organization: \'The University of Alabama\',\\n    imagePath: \'/img/profiles/Dipsikha_Devi.jpg\',\\n  },\\n  {\\n    name: \'Anupal Baruah\',\\n    title: \'Research Scientist\',\\n    organization: \'The University of Alabama\',\\n    imagePath: \'/img/profiles/Anupal_Baruah.jpg\',\\n  },\\n  {\\n    name: \'Dinuke Munasinghe\',\\n    title: \'Research Scientist\',\\n    organization: \'The University of Alabama\',\\n    imagePath: \'/img/profiles/Dinuke_Munasinghe.jpg\',\\n  },\\n  {\\n    name: \'Parvaneh Nikrou\',\\n    title: \'PhD Candidate\',\\n    organization: \'The University of Alabama\',\\n    imagePath: \'/img/profiles/Parvaneh_Nikrou.jpg\',\\n  },\\n  {\\n    name: \'Dan Tian\',\\n    title: \'Postdoctoral Researcher\',\\n    organization: \'The University of Alabama\',\\n    imagePath: \'/img/profiles/Dan_Tian.jpg\',\\n  },\\n  {\\n    name: \'Yixian Chen\',\\n    title: \'Research Scientist\',\\n    organization: \'The University of Alabama\',\\n    imagePath: \'/img/profiles/Yixian_Chen.jpg\',\\n  },\\n  {\\n    name: \'Sagy Cohen (PI)\',\\n    title: \'Professor\',\\n    organization: \'The University of Alabama\',\\n    imagePath: \'/img/profiles/Sagy_Cohen.jpg\',\\n  },\\n]\\n\\nFlood Inundation Mapping (FIM) is the spatially explicit delineation of flood extent, turning hydrological forecasts and observations into actionable geospatial information. As the frequency and severity of flooding increase globally, accurate and scalable FIM has become essential to disaster preparedness, emergency response, infrastructure planning, and climate risk assessment. Operationally, flood maps are commonly generated from streamflow forecasts, such as those produced by NOAA\'s National Water Model in the United States. FIM, however, is only one part of the workflow. Before FIM can reliably inform decisions, it needs to be rigorously checked against high-quality observations of real flood events.\\n\\nAt the University of Alabama\'s Surface Dynamics Modeling Lab (SDML), with support from CIROH in partnership with NOAA, we have been building the CIROH FIM Community Ecosystem, an interconnected, open-source, Python-based suite of toolsets for large-scale flood inundation modeling, simulation, benchmarking, and evaluation. Below we describe what each component of the Ecosystem does, how they work together, and how to get started.\\n\\n## The problem: fragmented capabilities without a unified FIM framework\\n\\nThis effort starts with a simple question: can flood inundation modeling, benchmarking, and evaluation be brought together into a seamless, unified, and, most importantly, scalable system that serves both operational forecasters and the research community? What exists today are small-scale studies and individual tools: models predict floods, methods that evaluate accuracy, observations that record real events, each built for a specific task and demanding its own painstaking setup. What does not exist is a unified framework spanning modeling to evaluation at scale, for one study area or a thousand, so that methodologies are consistent and ready to calibrate models and test hypotheses. For operational forecasters, the missing piece is scale: mapping a single basin is a tractable problem, but operational forecasting requires generating and trusting a modeling approach across numerous river reaches in real time.\\n\\nEvaluation raises the bar further. A model\'s true potential and limitations emerge only when it is tested at scale across many events, diverse floodplains, topographic settings, and hydrologic regimes. Large-scale evaluation is what turns a case study into a defensible conclusion about where a model works, where it fails, and why. Yet such evaluation depends on an \\"answer key\\": high-quality records of flood inundation for real flooding events. Those benchmark data have historically been scarce, scattered, and inconsistent, and where benchmarks are unavailable or of poor quality, evaluations lose credibility, and even skillful models are met with mistrust. The result: research groups rebuild the same pipelines from scratch, evaluations cannot be compared across regions or scales, and promising models take longer to reach the people who need them.\\n\\n## Our effort: the CIROH FIM Ecosystem\\n\\nOur answer is an interconnected, interoperable system of open-source components designed to work together through simple programmatic interfaces. Most components are deployed as standalone Python packages: install only what you need, or chain them into a complete workflow.\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   class=\\"dark-mode-white-bg\\"\\n   src={useBaseUrl(\'/img/blog/2026-08-fim-ecosystem/ecosystem-overview.png\')}\\n   width=\'100%\'\\n   alt=\\"The CIROH FIM ecosystem at a glance: FIMserv and FIMsim for generation and simulation, FIMbench for benchmarking, FIMeval for evaluation, FIMbox as a sandbox, and FIMsens for observation, all sharing one CIROH cloud backbone.\\"\\n   />\\n  <figcaption><em>The CIROH FIM ecosystem at a glance: FIMserv (generation) and FIMsim (simulations); FIMbench (benchmark database); FIMeval (evaluation); FIMbox (sandbox); FIMsens (observation). Each is a standalone tool, all sharing one CIROH cloud backbone.</em></figcaption>\\n</figure>\\n\\n{/* place truncation here when ready */}\\n\\n### (a) FIMserv: FIM generation tool using the NOAA OWP HAND-FIM operational framework\\n\\nThe Office of Water Prediction\'s Height Above Nearest Drainage (OWP HAND) framework, the operational FIM system of the United States, is a deliberately simple terrain-based model run over Hydrologic Unit Code 8 (HUC8) watersheds ([more about HUCs](https://nas.er.usgs.gov/hucs.aspx)) using National Water Model streamflow predictions across 2.7 million river reaches nationwide. Configuring it, however, is not straightforward: setting up the full pipeline from watershed data to streamflow and reproducing it across computing systems have been persistent obstacles to applying, improving, or studying an otherwise scalable model. [FIMserv](https://github.com/sdmlua/FIMserv), the modeling component of the CIROH FIM Ecosystem, removes that barrier. Given a watershed of interest and an event, it automatically configures the entire modeling setup, retrieving the OWP-precalculated watershed data from CIROH\'s AWS S3 cloud storage (which mirrors the NOAA OWP-precalculated HUC8 datasets for the HAND FIM run) and the NWM streamflow for the chosen event (a past event, also called retrospective data; a live National Water Model forecast; USGS gauge records; or global hydrological products such as GeoGLOWS). It then leverages the [OWP inundation mapping framework](https://github.com/NOAA-OWP/inundation-mapping) to produce a flood extent map within minutes (Baruah et al., 2025). It covers NOAA\'s full forecast range, from hourly short-range runs to 30-day outlooks, and supports simulation of many watersheds and flood events. It can also evaluate the NWM streamflow against USGS gauge observations, providing a measure of confidence in a map\'s inputs. Users can also modify key configuration inputs, such as river slope, calibration coefficients, and river bathymetry, supporting experimentation well beyond the default modeling setup. It is wrapped as a Python package that runs just as well on a laptop as on cloud infrastructure, so what once took a long time now takes a single installation command.\\n\\n### (b) FIMeval: FIM predictions evaluation framework\\n\\nA flood map is only as useful as the confidence placed in it, and that confidence comes from evaluation: comparing a model-predicted extent against a benchmark flood map from an actual or synthetic event. The traditional methods of evaluation, however, are manual, time-intensive, and error-prone; preparing maps in GIS platforms and/or doing it programmatically, and standardizing models and benchmarks (such as removing permanent water bodies and aligning projections) is so laborious that testing a model across many events becomes impractical. [FIMeval](https://github.com/sdmlua/fimeval) automates, standardizes, and scales that step, evaluating any flood maps against benchmarks in a consistent, reproducible manner (Devi et al., 2026). It is deliberately model- and benchmark-agnostic: the map can come from any terrain-based, hydraulic, or data-driven model, and the benchmark from any trusted source. It computes several standard accuracy metrics, with built-in checks for how data imbalance between flooded and dry areas skews those scores. It then goes further, answering the impact-based question communities actually ask: which buildings does the model predict will be inundated, and was that prediction correct? It fits into any Python-based workflow: bring a flood map, whether produced by FIMserv or any other model, together with a benchmark you supply, and FIMeval scores the pair. What makes it especially powerful, though, is that users do not need to supply a benchmark at all: FIMeval connects seamlessly to the FIMbench database, so a single automated query pulls the right quality-controlled benchmark for your area and event and scores against it, provided the event date falls within our available benchmark coverage. FIMbench itself is our rigorously quality-controlled, multi-source benchmark database, described in detail in section (c) below. For FIMserv users, the evaluation can run embedded within FIMserv, generating and evaluating a map in a single pass. Demonstrations span major observed events and design floods alike across continental to global watersheds.\\n\\n### (c) FIMbench: an extensive FIM benchmarking database\\n\\nTrusting a model-predicted flood extent requires real-world evidence, precisely the benchmark data that has been hardest to obtain. [FIMbench](https://github.com/sdmlua/fimbench) fills that gap with a rigorously quality-controlled library of multi-source, multi-sensor benchmark flood maps. Its current release includes 190+ maps (it will continuously keep growing with time) across the United States (Devi et al., in preparation), derived from aerial imagery acquired via NOAA\'s National Geodetic Survey (NGS), PlanetScope satellite imagery, Sentinel-1 radar, FEMA Base Level Engineering (BLE) 100- and 500-year return-period flow-based FIM products, and FIMs derived from USGS-surveyed high-water marks. Every map undergoes standardized processing and quality screening and is cataloged into quality- and product-based tiers; the guiding philosophy is \\"quality over quantity.\\" FIMbench utilities then package each approved map into a database-compatible format and publish it to the CIROH AWS S3 database. Contributing to the database is currently limited to the SDML team, though we are exploring ways for the community to add data in the future; every published dataset, however, is openly available to everyone. Access follows two routes: the interactive [FIMbench WebApp](https://tethys.ciroh.org/apps/fimbench-gui/), developed with our partners at Aquaveo, supports visualizing, filtering, and downloading flood events; and the FIMbench Python API retrieves selected benchmarks programmatically from the [cloud-hosted CIROH AWS S3 database](https://sdmlab.ciroh.org/#FIM_Database/). A cataloged, quality-assured, multi-sensor benchmark collection at this national scale has not, to our knowledge, been openly published before; paired with FIMeval, it makes testing a flood model against hundreds of real events practical rather than prohibitively laborious.\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   class=\\"dark-mode-white-bg\\"\\n   src={useBaseUrl(\'/img/blog/2026-08-fim-ecosystem/fimbench-webapp.png\')}\\n   width=\'100%\'\\n   alt=\\"Homepage snapshot of the extensive Flood Inundation Mapping Benchmark data web portal.\\"\\n   />\\n  <figcaption><em>Homepage snapshot of the extensive Flood Inundation Mapping Benchmark data web portal (Web portal: <a href=\\"https://tethys.ciroh.org/apps/fimbench-gui/\\">https://tethys.ciroh.org/apps/fimbench-gui/</a>)</em></figcaption>\\n</figure>\\n\\n### (d) FIMsens: flood extent and depth from satellite observations\\n\\nFIMsens, an upcoming Ecosystem component, adds an observation mode to the ecosystem: an end-to-end toolset that turns satellite imagery into error-corrected flood extent and depth products. Given a user-defined area of interest and event period, FIMsens discovers and previews suitable SAR or optical scenes, then processes them through linked modules for initial flood detection, reliability assessment, omission reconstruction, and depth estimation, beginning with Seeded Local Adaptive Thresholding (SLAT) (Wang et al., under review), which extracts the inundation directly observable in the imagery. The detections then pass to the Flood Object Reliability Filter (FOR-Filter) (Tian et al., in preparation), which uses image, geometric, terrain, and hydrologic evidence to remove or flag likely false positives before they propagate downstream. Finally, RS-FloodXDepth (Tian et al., 2026) combines retained flood evidence with surrounding topography to reconstruct hydrologically plausible inundation that would otherwise be missed due to vegetation, urban structures, clouds, or weak water signals, and to estimate depth from the inferred water surface and DEM elevation. A single pass delivers raw, filtered, and corrected extent layers together with a DEM-guided depth map.\\n\\nWithin the broader ecosystem, FIMsens complements rather than replaces the curated FIMbench reference databases. The same algorithm underpins FIMbench\'s Tier 2 and Tier 3 benchmarks, where its output is conservatively confirmed through qualitative assessment. Where the rigorously quality-controlled FIMbench database has a match, that curated map stays the trusted reference. Where no suitable benchmark exists, FIMsens can be used to generate event-specific, observation-derived flood extent and depth products from available satellite imagery, providing additional spatial and temporal coverage for FIMeval and related analyses. Because these event-specific products depend on the quality of the selected observations and processing conditions, they should still be reviewed through the toolset\'s QA outputs and, where appropriate, qualitative inspection before being used as reference information.\\n\\n### (e) FIMsim: cloud-based multi-model flood simulation\\n\\nFIMsim expands the ecosystem\'s flood-simulation engine, which models flooding using either terrain-based or hydraulic approaches: it runs the terrain-based [NOAA OWP HAND-FIM](https://github.com/NOAA-OWP/inundation-mapping) through FIMserv, the [ARC-Curve2Flood model](https://github.com/MikeFHS/curve2flood), and extends the workflow to 2D hydraulic simulation using models with varying levels of physical complexity. Because no single flood model performs best everywhere, comparing alternatives has meant rebuilding a pipeline for each one; [FIMsim](https://github.com/sdmlua/FIMsim) removes that burden. In practice, the workflow is simple: the user defines a study area, and FIMsim acquires the inputs, builds the model configuration, and runs the hydrodynamic models of their choice, such as [LISFLOOD-FP](https://zenodo.org/records/6912932) and [TRITON](https://triton.ornl.gov/). These hydrodynamic models provide GPU-enabled implementations that can substantially reduce execution time for computationally demanding simulations. Through the planned web application, users will be able to run the models remotely in a GPU-enabled Linux environment and download the results without installing the software locally. Different models can be run across catchments, or several models over a single catchment for agreement and ensemble analysis; integrating FIMeval and FIMbench provides evaluation for every output. Since FIMsim can be set up and run for every reach, a hypothesis can be tested across models rather than trusted to just one model. Simulation is not its only use. FIMsim can also serve purely as a preprocessor for hydraulic modeling, generating each input required for a 2D model separately. It can produce a mosaicked, clipped, reprojected, and resampled DEM at different spatial resolutions; generate Manning\'s n roughness grids from land-cover datasets of different sources, years, and resolutions; provide flowline data; and obtain inflow hydrographs from NWM, a USGS gauge, or an uploaded CSV file. The processed inputs can be exported in several commonly used formats, allowing modelers to use the ready-to-run files directly in their preferred hydraulic modeling engine. Today, FIMsim is available as a Python framework and a desktop application for macOS and Windows; a pip-installable Python library and a web application are also under development.\\n\\n### (f) FIMbox: a sandbox for large-scale, multi-model FIM development and analysis\\n\\n[FIMbox](https://github.com/sdmlua/fimbox) is an open-source Python sandbox that treats flood inundation mapping as a controlled experiment: models, inputs, and parameters become variables that a researcher deliberately sets, holds fixed, or sweeps across in a single, reproducible run. A run begins with a boundary polygon for any area of interest rather than a precalculated HUC8, and a shared initialization step stages the common resources every model needs into one working directory: the DEM, NHD and NWM hydrography, FEMA NFHL flood hazard layers, NLD levees, OSM bridges and roads, and USGS gauge records. A configuration wrapper then exposes each subsequent stage, so a user-defined topography, hydrography, or roughness field is applied where it matters. The experiment setup determines which models to run, the terrain-based HAND workflow, a hydrodynamic model, or both. Each model triggers its own preprocessor, which builds only the datasets it needs and pulls inflows from the National Water Model or NextGen, or through the crosswalk module from global sources such as GEOGloWS.\\n\\nWhere FIMserv runs only the operational OWP HAND framework over precalculated HUC8 data, FIMbox opens the pipeline itself. Its HAND FIM modeling breaks the OWP HAND-FIM pre- and post-processing chain (from a DEM to a mapped extent) into small composable pieces: staging inputs, hydroconditioning the terrain, segmenting the stream network, generating HAND and its synthetic rating curves, calibrating them, generating the FIM, and evaluating it. Every stage exposes its parameters and writes intermediate products the user can inspect, replace, or feed back in, so a dataset or a coefficient can be substituted at one step and its consequences traced through to the mapped extent and depth. Because each dataset and parameter is a variable under the user\'s control, questions that are ordinarily laborious become routine: how much the resolution or the source of the river network, catchments, or DEM changes the predicted extent; how sensitive the result is to Manning\'s n roughness; and whether a better synthetic rating curve, a different stream segmentation, or an improved slope treatment sharpens extent and depth. Dask parallelization runs across the whole HAND pipeline, so the same workflow scales from a single basin to continental domains without rewriting a line of code, and the package runs the same way on a local workstation or on cloud computing resources.\\n\\nWhat sets FIMbox apart is that a single experiment carries seamlessly from modeling through evaluation to benchmarking. Within one run it can drive a terrain-based HAND solution and, through the integrated FIMsim framework, a hydrodynamic model such as TRITON or LISFLOOD-FP, without altering their native configurations, then score each predicted extent with FIMeval against the best-matching FIMbench benchmark, selected by event date, geographic domain, spatial overlap, quality tier, or any combination of these; where no benchmark exists, FIMsens can attempt to derive one from satellite imagery. Because the whole chain, from fetching flows to scoring the result, is scriptable from a notebook or a scheduled job, FIMbox makes FIM research genuinely iterative: a hypothesis can be posed, tested, and scored at any scale, one basin or a thousand, with no manual handoffs between tools. That same design makes multi-model analysis natural, and work is now underway to extend the sandbox beyond a single model toward ensemble, multi-model FIM extents, repurposing results from a range of hydrologic models through the same workflow. Looking ahead, integrating NOAA\'s Next Generation Water Resources Modeling Framework (NextGen) will close the loop from meteorological forcing through hydrologic and inundation modeling to flood-extent assessment and evaluation, an end-to-end ecosystem simulation.\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   class=\\"dark-mode-white-bg\\"\\n   src={useBaseUrl(\'/img/blog/2026-08-fim-ecosystem/fimbox-workflow.jpg\')}\\n   width=\'100%\'\\n   alt=\\"The FIMbox modular workflow: shared inputs feed swappable stages, from model initialization and preprocessing to FIM generation and evaluation.\\"\\n   />\\n  <figcaption><em>The FIMbox modular workflow: shared inputs feed swappable stages, from model initialization and preprocessing to FIM generation and evaluation, so terrain-based (e.g., HAND) or hydrodynamic models can be configured, run, and compared in one framework, with FIMsim, FIMeval, and FIMbench plugged in for simulation, evaluation, and benchmarks.</em></figcaption>\\n</figure>\\n\\n## When should you use the FIM ecosystem?\\n\\nEach component can be used on its own; you do not need to adopt the entire ecosystem to benefit from a single component. However, integrating the components opens up research questions that no single component can answer alone. A few common starting points:\\n\\n- *\\"I need flood maps for a forecast or a past event or a synthetic scenario anywhere in the US; however, I need them fast and running on any local or cloud system.\\"* FIMserv can do that.\\n- *\\"I built a flood inundation model, hydraulic, data-driven, or otherwise, and I have my own benchmark; I want to know how accurate the model is.\\"* FIMeval can do that.\\n- *\\"I built a flood inundation model intended for regional, continental, or global application, and I want to investigate its potential and limitations across different hydroclimates and topographic settings.\\"* FIMeval, leveraging the FIMbench database, can do that.\\n- *\\"I just need reliable benchmark flood maps for my study area.\\"* FIMbench, via the GUI or the Python API, can provide that.\\n- *\\"I want to prepare the inputs for a 2D hydrodynamic model such as LISFLOOD-FP or TRITON, or run the model itself, wherever I need and without the usual setup hassle.\\"* FIMsim can do that, in a desktop app or Python framework, either handing you ready-to-run inputs and configuration to run on your own or running the simulation for you.\\n- *\\"I want to run several flood models over the same watershed for ensemble and agreement analysis or assign a different model to each catchment according to what performs best there.\\"* FIMbox can do that, orchestrating the models through FIMsim and passing every result on to FIMeval and FIMbench for evaluation.\\n- *\\"I want to experiment with the HAND workflow itself, swapping terrain, roughness, calibration, or model engines, feeding it custom or repurposed streamflow, and scaling from a single basin to continental domains.\\"* FIMbox can do that, breaking the workflow into flexible, Dask-parallel pieces that run straight through to evaluation.\\n- *\\"I want to test a hypothesis on the terrain-based NOAA OWP HAND model, evaluating it across dozens or hundreds of events to judge whether the approach can be implemented across the US.\\"* The integrated ecosystem can enable that: FIMserv handles the modeling, and FIMeval, drawing benchmarks from FIMbench, handles the evaluation; the entire process is automated, programmatically and seamlessly.\\n- *\\"I have no benchmark for my event and need to derive a flood extent and depth directly from satellite imagery.\\"* FIMsens can do that (once integrated), turning SAR or optical scenes into error-corrected extent and depth products.\\n\\n## Under the hood: technical dissemination\\n\\nTechnically, the ecosystem is a modular, cloud-native suite of open-source Python packages and frameworks. What holds it together is a shared CIROH cloud backbone: every component reads and writes the same cloud-hosted data, so one tool\'s output is directly consumable by the next. FIMserv streams its inputs on demand: precalculated HAND hydrofabrics from the CIROH AWS S3 buckets, retrospective National Water Model (NWM) streamflow from NOAA\'s public S3 archive, and forecast NetCDF files from Google Cloud Storage, with the TEEHR framework\'s PySpark engine handling massive streamflow extractions. FIMeval builds on the standard geospatial Python stack (Rasterio, PyProj, GeoPandas, Shapely) for raster reprojection, map algebra, and dynamic bounding geometries based on different evaluation methods. The heavy layers it needs on the fly, such as permanent water bodies and Microsoft building footprints for impact-based assessment, are hosted on ArcGIS Online and other cloud services and fetched through REST endpoints for the evaluation domain only, so nothing oversized ever lands on the user\'s machine. FIMbench\'s dissemination rests on a decoupled web architecture: a Tethys Platform backend acts as a tile proxy, streaming compressed vector tiles of benchmark FIM extent straight from the CIROH AWS S3 storage to a React front end that renders interactive maps with MapLibre GL. The same S3 store serves the stateless FIMbench Python API, so the database remains a single, consistent source of truth, regardless of how it is accessed. FIMbox adds a parallel execution layer: it decomposes the HAND workflow into independent per-branch computations (hydroconditioning, branching, relative elevation, and synthetic rating curves) and uses Dask to distribute those branches across local cores or cloud workers. FIMsim moves computation to the cloud, provisioning the hydrodynamic engines on managed resources and assembling their inputs from public sources: USGS 3DEP terrain, land-cover-derived roughness, and NWM, USGS, or user-supplied hydrographs. Hardware is the one practical dividing line across the ecosystem: FIMbox\'s terrain-based HAND workflows run on ordinary local systems without a GPU, while the full FIMbox and FIMsim capability, terrain-based modeling coupled with 2D hydrodynamic simulation, is currently GPU-backed for accelerating the computation and Linux-based. FIMsens will add the observation path, query SAR and optical image catalogs, align downloaded scenes to a common DEM, and then hand them to the correction routine described above.\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   class=\\"dark-mode-white-bg\\"\\n   src={useBaseUrl(\'/img/blog/2026-08-fim-ecosystem/technical-architecture.jpg\')}\\n   width=\'100%\'\\n   alt=\\"Technical architecture components of the ecosystem: FIMserv assembles HAND-based flood maps from cloud-hosted terrain and streamflow data sources; FIMeval retrieves benchmarks and evaluation layers from cloud-hosted endpoints; and FIMbench disseminates its curated database via the web portal and the Python API.\\"\\n   />\\n  <figcaption><em>Technical architecture components of the ecosystem: FIMserv assembles HAND-based flood maps from cloud-hosted terrain and streamflow data sources; FIMeval retrieves benchmarks and evaluation layers from cloud-hosted endpoints; and FIMbench disseminates its curated database via the web portal and the Python API, drawing from a single AWS S3 source of truth.</em></figcaption>\\n</figure>\\n\\n## Who is it for? Try it today\\n\\nThe CIROH FIM Community Ecosystem is completely open source and already in active use across the community: as of mid-2026, PyPI records put FIMserv past 45,000 downloads and FIMeval past 20,000, with the FIMbench API and the FIMbox testbed more recently released. How you start depends on the component: four of them are installed as Python packages with a single command (Astral uv makes it faster still), FIMsim ships as a desktop application, and FIMsens will join once released.\\n\\n```bash\\nuv/pip install fimserve   # flood map generation\\n\\nuv/pip install fimeval    # flood map evaluation\\n\\nuv/pip install fimbench   # benchmark database access\\n\\nuv/pip install fimbox     # FIM testbed access\\n```\\n\\nEach framework is provided with step-by-step documentation and example notebooks on its GitHub repository: [FIMserv](https://github.com/sdmlua/FIMserv/tree/main/docs), [FIMeval](https://github.com/sdmlua/fimeval/tree/main/docs), [FIMbench](https://github.com/sdmlua/fimbench/docs), [FIMbox](https://github.com/sdmlua/fimbox#module-documentation) and so on, so any user can go from installation to a first flood map and its evaluation without leaving the documentation. Run them wherever you work, from a laptop to Google Colab or CIROH\'s 2i2c JupyterHub. Prefer a point-and-click route? The [FIMbench web portal](https://tethys.ciroh.org/apps/fimbench-gui/) lets you browse the benchmark database, and FIMsim runs today as a desktop application.\\n\\nWho benefits from the FIM ecosystem? Broadly, anyone who works with flood hazard modeling. From researchers testing new models to forecasters, planners, engineers, and students, each takes something different from it: a place to experiment, options they can defend in operations, and flood information that has been checked before it is trusted. Our goal is simple: anyone, whatever their background, can make a flood map, check it against reality, and trust what it tells them.\\n\\n## Get involved\\n\\nThe FIM ecosystem is a living effort, and feedback will improve it. We will appreciate your feedback and suggestions about technical problems, proposed utilities, and additional components. We are committed to incorporating that input into each release, and collaboration is what we need most. The ecosystem is still very much in motion: not every framework yet has its own graphical interface, and some are not yet packaged for PyPI, but many avenues and dimensions are advancing in parallel. Keep an eye out for new releases, and email us about collaborations, ideas, or anything you would like to build with us. All the FIM components code lives in the [SDML GitHub repository](https://github.com/sdmlua), and each repository has its own contribution guidelines: open an issue with a new idea or a bug, submit a contribution, or simply reach out to the [SDML team](https://sdml.ua.edu). We would genuinely love to hear from you; it is how this ecosystem will keep evolving. And this is only a start: the CIROH FIM Community Ecosystem is not limited to the components described here. We want it to grow beyond SDML, with colleagues across CIROH institutions and the broader community contributing new components, datasets, and ideas that strengthen it as a shared, community-owned capability.\\n\\n## Acknowledgments\\n\\nThis work is supported by the National Oceanic and Atmospheric Administration (NOAA) through the Cooperative Institute for Research to Operations in Hydrology (CIROH) under the NOAA Cooperative Agreement with The University of Alabama (NA22NWS4320003). We thank the Aquaveo team for collaborating on the development of the Graphical User Interfaces for these tools.\\n\\n**CIROH cyberinfrastructure used:** [CIROH AWS S3 cloud storage](https://ciroh-owp-hand-fim.ciroh.org/index.html) hosts the OWP-precalculated HUC8 HAND hydrofabric datasets streamed on demand by FIMserv, and hosts the [FIMbench benchmark database](https://sdmlab.ciroh.org/#FIM_Database/); the CIROH Tethys Platform / CIROH Portal hosts the [FIMbench WebApp](https://tethys.ciroh.org/apps/fimbench-gui/), developed with our partners at Aquaveo (we are also thinking of hosting a curated virtual environment/image on 2i2c services soon). This cyberinfrastructure is the backbone that makes the ecosystem scalable and interoperable: because every component reads from and writes to the same CIROH cloud-hosted data, one tool\'s output is directly consumable by the next, and users never need to download oversized national datasets. CIROH\'s Tethys hosting and 2i2c JupyterHub lower the barrier further, providing point-and-click and zero-install routes into the tools, while CIROH compute resources make evaluation across hundreds of events and continental-scale runs practical rather than prohibitive.\\n\\n### Additional Links\\n\\n- Understand the CIROH FIM ecosystem visually: https://sdml.ua.edu/fim-ecosystem/\\n- Explore the CIROH FIM ecosystem more interactively with our [NotebookLM Mind Map](https://notebooklm.google.com/notebook/0cbf3ebc-9ebd-41c9-ba56-24922c934be7/artifact/66c95aa6-5532-4a64-b3db-3dde7c000b70?utm_source=nlm_web_share&utm_medium=google_oo&utm_campaign=art_share_1&utm_content=&utm_smc=nlm_web_share_google_oo_art_share_1_)\\n\\n## Publications\\n\\n1. Baruah, A., Dhital, S., Cohen, S., Tran, T.N.D., Elhaddad, H., Watts, C.L., Devi, D., Chen, Y., & Pruitt, C. (2025). FIMserv v.1.0: A tool for streamlining Flood Inundation Mapping (FIM) using the United States operational hydrological forecasting framework. *Environmental Modelling & Software*, 192, 106581. https://doi.org/10.1016/j.envsoft.2025.106581\\n2. Devi, D., Dhital, S., Munasinghe, D., Cohen, S., Baruah, A., Chen, Y., Tian, D., & Pruitt, C. (2026). A framework for the evaluation of flood inundation predictions over extensive benchmark databases. *Environmental Modelling & Software*, 196, 106786. https://doi.org/10.1016/j.envsoft.2025.106786\\n3. Devi, D., Munasinghe, D., Tian, D., Dhital, S., Cohen, S., Raghavan, R., Swain, N., Nikrou, P., Baruah, A., & Chen, Y. (in preparation). FIMbench: A benchmark database of multi-tier flood inundation maps for large-scale evaluation.\\n4. Tian, D., Liu, H., Wang, L., Cohen, S., & Mandal, T. (2026). RS-FloodXDepth: Enhancing remote sensing-derived flood extent and estimating flood depth using a hydrologically guided region-growing method and high-resolution DEMs. *Water Resources Research*, 62, e2025WR042384. https://doi.org/10.1029/2025WR042384\\n5. Tian, D., Liu, H., Cohen, S., & Wang, L. (in preparation). Commission error analysis and correction in remote sensing flood maps using an object-oriented, hydrologically informed approach.\\n6. Wang, L., Liu, H., Tian, D., & Cohen, S. (2025, under review). Rapid automated flood mapping using SAR imagery and locally adaptive thresholds derived from multivariate gamma probability distributions. *International Journal of Applied Earth Observation and Geoinformation*.\\n\\n## Our Team\\n\\n<ProfileCards profiles={fimProfiles} />"},{"id":"devcon26-infra","metadata":{"permalink":"/staging/main/blog/devcon26-infra","source":"@site/blog/2026-06-29-DevCon26-Infra.mdx","title":"Powering CIROH DevCon 2026: How CIROH and 2i2c Ran Cloud Computing at Scale","description":"Our Research Cyberinfrastructure team provisioned cloud resources for 15 hands-on workshops across three days in close collaboration with our partners at 2i2c. Here\'s what we ran, and how.","date":"2026-06-29T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"},{"inline":true,"label":"CIROH DevCon","permalink":"/staging/main/blog/tags/ciroh-dev-con"},{"inline":true,"label":"Services","permalink":"/staging/main/blog/tags/services"},{"inline":true,"label":"NSF","permalink":"/staging/main/blog/tags/nsf"},{"inline":true,"label":"NSF Access","permalink":"/staging/main/blog/tags/nsf-access"},{"inline":true,"label":"2i2c","permalink":"/staging/main/blog/tags/2-i-2-c"},{"inline":true,"label":"JetStream2","permalink":"/staging/main/blog/tags/jet-stream-2"},{"inline":true,"label":"AWS","permalink":"/staging/main/blog/tags/aws"},{"inline":true,"label":"Google Cloud","permalink":"/staging/main/blog/tags/google-cloud"},{"inline":true,"label":"HPC","permalink":"/staging/main/blog/tags/hpc"},{"inline":true,"label":"Wukong","permalink":"/staging/main/blog/tags/wukong"},{"inline":true,"label":"Pantarhei","permalink":"/staging/main/blog/tags/pantarhei"},{"inline":true,"label":"On-Premises Services","permalink":"/staging/main/blog/tags/on-premises-services"}],"readingTime":8.22,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"Assistant Director, IT and DevOps","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2025","page":null},{"name":"April Johnson","title":"Community and People Lead","title2":"2i2c","url":"https://2i2c.org/author/april-johnson/","imageURL":"https://2i2c.org/author/april-johnson/avatar_hud6741f5ab4e43e6424a30a21a54023f3_190455_270x270_fill_lanczos_center_3.png","key":"april-johnson","page":null},{"name":"Benjamin Lee","title":"Development Operations Engineer","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/seungchanlee/","imageURL":"/staging/main/img/blog/authors/benjamin-lee.png","key":"benjamin-lee","page":null},{"name":"Nia Minor","title":"Graduate Research Assistant","title2":"Alabama Water Institute","url":"https://github.com/sheargrub","imageURL":"/staging/main/img/blog/authors/nia-minor.png","key":"nia-minor","page":null},{"name":"Harsha Vemula","title":"DevOps Engineer","title2":"Alabama Water Institute","url":"https://github.com/harshavemula-ua","imageURL":"/staging/main/img/blog/authors/harsha-vemula.jpeg","key":"harsha-vemula","page":null}],"frontMatter":{"title":"Powering CIROH DevCon 2026: How CIROH and 2i2c Ran Cloud Computing at Scale","description":"Our Research Cyberinfrastructure team provisioned cloud resources for 15 hands-on workshops across three days in close collaboration with our partners at 2i2c. Here\'s what we ran, and how.","slug":"devcon26-infra","authors":["arpita-2025","april-johnson","benjamin-lee","nia-minor","harsha-vemula"],"tags":["Blog","CIROH","Conference","CIROH DevCon","Services","NSF","NSF Access","2i2c","JetStream2","AWS","Google Cloud","HPC","Wukong","Pantarhei","On-Premises Services"],"hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"CIROH Flood Inundation Mapping (FIM) Community Ecosystem: A Large-Scale Operational Flood Modeling-to-Evaluation Framework","permalink":"/staging/main/blog/fim-community-ecosystem"},"nextItem":{"title":"Continental-Scale Streamflow Simulation Using Kriging in the NGIAB-NRDS NextGen Ecosystem","permalink":"/staging/main/blog/continental-scale-streamflow-kriging-ngiab-nrds"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\nAt the [2026 CIROH Developers Conference](https://ciroh.ua.edu/devconference-2026-ciroh-developers-conference/)\\n(University of Utah, May 27\u201329) participants used a variety of tools and models on cloud infrastructure\\nthey\'d never had to install, configure, or even think about. To enable that seamless experience,\\nour Research Cyberinfrastructure team provisioned cloud resources for **15 hands-on workshops**\\nacross three days in close collaboration with our partners at 2i2c. Here\'s what we ran, and how.\\n\\n## What we provisioned, by the numbers\\n\\nRunning an event of this scale requires more than just a single cloud context, as each workshop posed\\nits own computing and data access requirements. CIROH Cyberinfrastructure met this challenge via a\\ncoordinated stack spanning multiple cloud providers and services. Across the\\n[15 workshops](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues?q=is%3Aissue%20state%3Aclosed%20label%3ADevCon2026)\\nthat needed infrastructure (14 requests), the R2OHC cloud provisioned the following:\\n\\n| Provider                  | Workshops | What it carried |\\n|---------------------------|-----------|-----------------|\\n| 2i2c JupyterHub on GCP    | 12        | A mix of Small, Medium, Large, and GPU servers; **9 workshops ran on custom-built images** |\\n| AWS                       | 3         | NRDS, HydroServer, TEEHR |\\n| Google NWM BigQuery API   | 2         | Input data for Flood Inundation Mapping (multi-source DB / HAND visualization) and Hydroinformatics (Essential Geospatial Skills) |\\n| NSF Access                | 1         | GPU-powered VMs for the \\"Talk to NRDS\\" LLM workshop |\\n\\n## One link, no setup: the Workshop Hub\\n\\nFor 12 of these workshops, their backbone was the **CIROH\u20132i2c JupyterHub**, a managed JupyterHub\\nenvironment that 2i2c operates on Google Cloud. For the conference, we provisioned a dedicated\\n**Workshop Hub**: an ephemeral environment that lives only for the duration of the event and then spins back down.\\n\\n{/* truncate */}\\n\\n## The work that happens before anyone logs in: custom images\\n\\n**Nine of the twelve JupyterHub workshops needed a custom software image** to support their unique computing needs.\\nSessions covering topics like the Community Asset Computation Hub (CCNH), Foundations of Machine Learning,\\nCUAHSI Hydroinformatics, HydroServer, INFLECT-based Flood Inundation Mapping, Satellite Data Projection,\\nMachine-Learned Model Emulators, and Water Quality Modeling from Hillslope to Watershed Scales each had distinct dependency stacks.\\n\\nThat\'s a coordination problem, and it was solved weeks before the conference. Workshop leads told us what their sessions needed,\\nwe defined those environments in our public [`awi-ciroh-image` repository on GitHub](https://github.com/CIROH-UA/awi-ciroh-image),\\nand 2i2c deployed them. By the time attendees arrived, the right libraries were already in place, all but eliminating the usual\\nloop of haggling with installations and configurations that \u201Cwork on my machine\u201D. Instead, there were reproducible environments,\\nready and consistent on day one, demonstrating clear evidence of how tightly the CIROH and 2i2c teams work together.\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   class=\\"dark-mode-white-bg\\"\\n   src={useBaseUrl(\'/img/blog/2026-06-devcon/devcon26-usage.png\')}\\n   width=\'100%\'\\n   alt=\\"A line graph showing usage of CIROH-2i2c JupyterHub environments over time. A spike in usage occurs on May 27th, peaking on the 27th at 132 workshop users, before leveling back off to near-zero levels after the conference\'s end on June 1st.\\"\\n   />\\n  <figcaption><em>During DevCon, as many as 132 participants were logged into CIROH-2i2c JupyterHub per day.</em></figcaption>\\n</figure>\\n\\n## CCNH: Instant Access to NextGen in JupyterHub\\n\\nTwo of the twelve workshops also marked the first appearance of the\\n[**CIROH Community NextGen Hub** (**CCNH**)](https://hub.ciroh.org/docs/products/ngiab-ecosystem/ngiab/distributions/nextgen-2i2c/)\\nat a DevCon event! This JupyterHub image contains all of the dependencies\\nrequired to run the NextGen Framework, bypassing the framework\'s notorious\\ncomplexity. CCNH represents a new paradigm where the NextGen framework can\\nbe run entirely from the comfort of a web browser, further extending its\\naccessibility and expanding the potential for research and development with\\nthe framework.\\n\\n## DevCon 2026 workshops using CIROH Cyberinfrastructure\\n\\n-\\t**[#463 \u2014 Hands-on LSTM and Transformer for Operational Streamflow Prediction](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/463)** (Penn State): Brings state-of-the-art deep-learning sequence models into an operational streamflow forecasting workflow. This workshop made use of **2i2c GPU servers** to enable its cutting-edge approach.\\n-\\t**[#462 \u2014 Foundations of ML: From Architecture to Optimization](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/462)** (UA): Entry-level on-ramp giving hydrology researchers the core building blocks of machine learning workflow.\\n-\\t**[#460 \u2014 Machine Learning: Satellite Data Projection and Georeferencing with Satpy](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/460)** (Stevens): Teaches the remote-sensing preprocessing (projection/georeferencing of polar-orbiting data) needed to feed satellite inputs into models.\\n-\\t**[#458 \u2014 Essential Geospatial Data and Coding Skills for CIROH Researchers / CUAHSI Hydroinformatics](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/458)** (CUAHSI): Establishes the baseline geospatial-data and coding literacy that underpins nearly every other track.\\n-\\t**[#455 \u2014 Physics-Based Framework to Predict Water Quality from Hillslope to Watershed Scales](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/455)** (U. Iowa): Applies a physics-first modeling approach to demonstrate the design decisions that go into scaling a model from local to regional contexts.\\n-\\t**[#449 \u2014 Topographically Derived High Flow Thresholds for Flood Inundation Mapping](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/449)** (USU): Demonstrates an approach to improve flood-inundation mapping by deriving high-flow thresholds directly from terrain.\\n-\\t**[#441 \u2014 Temporary API Key for CIROH NWM API](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/441)**: Two workshops queried large hydrologic datasets directly through the **Google BigQuery API**, one in Flood Inundation Mapping and one in Hydroinformatics.\\n-\\t**[#411 \u2014 Talk to NRDS: LLM Chat for TethysDash to Explore the NextGen Research Data Stream](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/411)** (BYU/Aquaveo): Demonstrates a natural-language/LLM interface for querying NRDS outputs, lowering the barrier to exploring the data stream. (Notably, this workshop used **50 custom-provisioned VMs** on the JetStream2 cloud to handle the heightened GPU requirements of this novel technology.)\\n-\\t**[#410 \u2014 Machine-Learned Emulator Models for Water-Quality Uncertainty](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/410)** (UVM): Trains ML emulators on the output of baseline models to quantify predictive uncertainty cheaply, replacing expensive repeated runs of in-depth physical simulations.\\n-\\t**[#408 \u2014 Integrating Models in NGIAB, NRDS](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/408)** (UA): The core research-to-operations session covering the model-integration lifecycle from BMI into NGIAB and onward to NRDS.\\n-\\t**[#389 \u2014 Managing and Standards-Based Sharing of Hydrologic Observations Using HydroServer](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/389)** (USU): Standardizes how observational data is collected, organized, and shared via built-for-purpose software, solidifying the evaluation/ground-truth side of modeling.\\n-\\t**[#388 \u2014 Orchestrating End-to-End Reproducible NextGen Workflows](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/388)** (U. Calgary): Focuses on reproducibility, chaining NextGen and adjacent steps into repeatable, shareable workflows. This session made use of both a single \\"Community Asset\\" image and a **shared storage** volume, with input data pre-staged in a common folder so dozens of users could work against the same datasets across both sessions.\\n-\\t**[#383 \u2014 Uncertainty Analysis for Extreme Event Hydrometry](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/383)** (U. Iowa): Provides the theory and tools for quantifying uncertainty specifically in extreme-event measurement.\\n-\\t**[#379 \u2014 Interactive CIROH Research Apps with Python-only Tethys Component Apps](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/379)** (Aquaveo/BYU): Lets researchers build interactive web apps for their results in pure Python, without the overhead of learning unwieldy front-end frameworks.\\n\\n## HydroShare integration: from a resource to a running notebook\\n\\nMany workshop materials were published as HydroShare resources and launched straight into the Workshop Hub via a single link, pulling notebooks and data into the user\'s environment automatically. What might otherwise have been an onerous process of managing cluttered Downloads folders and local directory structures was instead compressed into a single click.\\n\\n## Why the 2i2c partnership matters\\n\\n2i2c\'s significance in this process went far beyond just hosting the JupyterHub. 2i2c specializes in open-source cloud infrastructure for research, and that shared commitment shaped our collaboration. Our entire stack \u2014 JupyterHub, the container images, the HydroShare connector \u2014 is open source and lives in public repositories. Another institution could easily read our Dockerfiles or dependency configurations to launch similar environments.\\n\\nThe operational model matters too. 2i2c manages JupyterHubs for many science communities, and what they learn from one community gets shared quickly with others. Our pre-conference testing and prep was informed by dashboards 2i2c built for EarthScope\'s computing-intense workshops, and the temporary storage approach 2i2c and CIROH used at DevCon is now being re-used with other communities (including EarthScope). \\n\\n## Lessons we\'re carrying forward\\n\\n**Pre-event automation is everything.** Nine custom images don\'t build themselves on the morning of a workshop. Front-loading that work meant we could focus on people, not infrastructure, during the event.\\n\\n**Treat infrastructure as tracked engineering.** Thirteen GitHub issues turned a sprawling set of requests into an auditable plan \u2014 and a head start on next year.\\n\\n**Reproducibility scales.** Version-controlled environment images are the difference between 15 consistent workshops and 15 individual troubleshooting sessions \u2014 and they let any of these workshops be re-run on the mainline (NM2.1) 2i2c JupyterHub environment.\\n\\n**Open-source, public-private partnerships work.** Corporate cloud providers (AWS/Google Cloud), an NSF-funded computing resource, a mission-driven infrastructure partner with 2i2c, and a university research institute (CIROH) all contributed aspects of the DevCon experience. The result was a unified experience across every workshop. That\'s the model we want to keep building on.\\n\\nTo our partners at 2i2c, and to the providers and resources that backed DevCon 2026: thank you. To our DevCon networking sponsors \u2014 Lynker, Google Cloud, Civil and Environmental Engineering at The University of Utah \u2014 thank you.\\n\\nAnd to everyone who logged in, ran the notebooks, and pushed their work forward \u2014 that\'s exactly what this infrastructure is for.\\n\\nInterested in CIROH\'s cloud resources? Learn more at [hub.ciroh.org/docs/services/intro](/docs/services/intro) or reach the CIROH Cyberinfrastructure team at [ciroh-it-support@ua.edu](mailto:ciroh-it-support@ua.edu)."},{"id":"continental-scale-streamflow-kriging-ngiab-nrds","metadata":{"permalink":"/staging/main/blog/continental-scale-streamflow-kriging-ngiab-nrds","source":"@site/blog/2026-05-26-continental-scale-streamflow-kriging.mdx","title":"Continental-Scale Streamflow Simulation Using Kriging in the NGIAB-NRDS NextGen Ecosystem","description":"Hourly streamflow kriging is now operational within the NextGen Research Data Stream, delivering spatially complete streamflow estimates for all NextGen v2.2 hydrofabric catchments across CONUS.","date":"2026-05-26T00:00:00.000Z","tags":[{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"Kriging","permalink":"/staging/main/blog/tags/kriging"},{"inline":true,"label":"Streamflow","permalink":"/staging/main/blog/tags/streamflow"},{"inline":true,"label":"NRDS","permalink":"/staging/main/blog/tags/nrds"},{"inline":true,"label":"DataStream","permalink":"/staging/main/blog/tags/data-stream"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"AWS","permalink":"/staging/main/blog/tags/aws"},{"inline":true,"label":"T-Route","permalink":"/staging/main/blog/tags/t-route"},{"inline":true,"label":"CONUS","permalink":"/staging/main/blog/tags/conus"}],"readingTime":4.76,"hasTruncateMarker":true,"authors":[{"name":"Suma Battula","title":"Department of Geological Sciences","title2":"The University of Alabama","url":"https://github.com/sumabattula","imageURL":"/staging/main/img/blog/authors/suma-battula.jpeg","key":"suma-battula","page":null},{"name":"Kunal Sarna","title":"Department of Computer Science","title2":"The University of Alabama","url":"https://github.com/Kunal2605","imageURL":"/staging/main/img/blog/authors/kunal-sarna.jpeg","key":"kunal-sarna","page":null},{"name":"Sonali Vyas","title":"Department of Computer Science","title2":"The University of Alabama","url":"https://github.com/sonalivyascse19-stack","imageURL":"/staging/main/img/blog/authors/sonali-vyas.png","key":"sonali-vyas","page":null},{"name":"Harsha Vemula","title":"DevOps Engineer","title2":"Alabama Water Institute","url":"https://github.com/harshavemula-ua","imageURL":"/staging/main/img/blog/authors/harsha-vemula.jpeg","key":"harsha-vemula","page":null},{"name":"Arpita Patel","title":"Assistant Director, IT and DevOps","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2025","page":null},{"name":"Jonathan Frame","title":"Assistant Professor, Department of Geological Sciences","title2":"Alabama Water Institute, The University of Alabama","url":"https://github.com/jmframe","imageURL":"https://github.com/jmframe.png","key":"jonathan-frame","page":null}],"frontMatter":{"title":"Continental-Scale Streamflow Simulation Using Kriging in the NGIAB-NRDS NextGen Ecosystem","description":"Hourly streamflow kriging is now operational within the NextGen Research Data Stream, delivering spatially complete streamflow estimates for all NextGen v2.2 hydrofabric catchments across CONUS.","slug":"continental-scale-streamflow-kriging-ngiab-nrds","authors":["suma-battula","kunal-sarna","sonali-vyas","harsha-vemula","arpita-2025","jonathan-frame"],"tags":["NextGen","Kriging","Streamflow","NRDS","DataStream","NGIAB","AWS","T-Route","CONUS"],"hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Powering CIROH DevCon 2026: How CIROH and 2i2c Ran Cloud Computing at Scale","permalink":"/staging/main/blog/devcon26-infra"},"nextItem":{"title":"TEEHR and CIROH Advance Cloud-Based Hydrologic Model Evaluation into a New Era","permalink":"/staging/main/blog/teehr-april-2026"}},"content":"Hourly streamflow kriging is now operational within the NextGen Research Data Stream, delivering spatially complete estimates for all NextGen v2.2 hydrofabric catchments. This observation-based approach supports streamflow analysis, NWM calibration, forecasting, and data assimilation for ungauged basins.\\n\\n## Kriging-Based Streamflow Estimation\\n\\nProcess-based hydrologic models are subject to structural and forcing uncertainties throughout the modeling domain, yet these can only be evaluated where USGS gauge observations exist. There is a clear need for a data-driven, observation-based framework that provides spatially complete streamflow estimates with well-characterized uncertainty, independent of model structure. Recent results from the CIROH project \\"Developing and Benchmarking Data Assimilation Methods on a Standardized Testbed\\" suggest that a simple Kriging interpolation between USGS gauged locations is both scalable and accurate for producing such spatially complete streamflow fields. As a pure data-driven method, this interpolation cannot be used directly for forecasting, but it serves as a valuable \\"pseudo-observation\\" for streamflow analysis and historical reconstruction.\\n\\n{/* truncate */}\\n\\n## Hourly Streamflow Kriging Across CONUS\\n\\nStreamflow kriging effectively leverages spatial correlations in observations and has previously been implemented in the National Hydrologic Model for calibration and evaluation at daily timescales ([Farmer et al., 2019](https://ascelibrary.org/doi/10.1061/%28ASCE%29HE.1943-5584.0001854)). Here, we extend this approach to hourly resolution using instantaneous-value (IV) discharge records from approximately 7,300 active USGS gauges across CONUS. Instantaneous values are aggregated to hourly means, and variogram parameters are estimated using a spherical variogram model. These parameters drive gridded hourly interpolated runoff and kriging error variance fields across CONUS, which are then used to estimate distributed runoff at every catchment divide within the NextGen hydrofabric.\\n\\n## Integration into the NextGen Research Data Stream\\n\\nTo make hourly kriging operationally available, we integrated it into the NextGen Research Data Stream (NRDS; [ngen-datastream#352](https://github.com/CIROH-UA/ngen-datastream/issues/352)). Kunal Sarna designed the software stack aligning the outputs in a long-format Brotli-compressed Parquet schema that downstream consumers such as T-Route expect, and built a Docker image packaging the kriging workflow (`docker.io/awiciroh/qkrig:2.2.0`). Harsha Vemula led and executed all aspects of deployment: configuring the AWS infrastructure, setting up the EventBridge schedule, provisioning and managing the nightly EC2 instance, orchestrating the end-to-end data pipeline and delivery of outputs to the NRDS status dashboard.\\n\\nThe NRDS at CIROH-UA now runs qkrig as a first-class datastream, updating the previous 24 hourly estimates once per day. Each night at 00:30 ET, the pipeline:\\n\\n1. Fetches USGS instantaneous-value discharge for ~7,300 active gauges\\n2. Fits an ordinary kriging field across CONUS at hourly resolution\\n3. Samples the field at every NextGen v2.2 catchment centroid\\n\\nThe full daily output \u2014 24 hourly kriged NetCDFs and variograms, kriging plots and a daily GIF, and a single ~13 MB Parquet file covering all 831,777 catchments \xd7 24 hours of streamflow \u2014 is published publicly at:\\n\\n```\\ns3://ciroh-community-ngen-datastream/outputs/qkrig/qkrig.{YYYYMMDD}/\\n```\\n\\nand tracked on the [NRDS status dashboard](https://ciroh-community-ngen-datastream.s3.amazonaws.com/status/dashboard.html) alongside other operational datastreams.\\n\\n![Hourly kriged streamflow and variogram across CONUS](/img/blog/2026-05-kriging/kriging-streamflow-variogram.gif)\\n\\n**Figure 1:** Hourly kriged streamflow and variogram for the CONUS region, accessed from the NextGen Research Data Stream: [https://datastream.ciroh.org/#outputs/qkrig/qkrig.20260519/plots/kriging/](https://datastream.ciroh.org/#outputs/qkrig/qkrig.20260519/plots/kriging/)\\n\\n## Streamflow Simulation Using T-Route\\n\\nTo evaluate the utility of kriging for generating spatially distributed runoff in ungauged basins, we interpolated runoff over the South Toe River hydrofabric by withholding observations from 20% of USGS gauges affected by Hurricane Helene in September 2024. The resulting kriged runoff was used to initialize T-Route, a river-routing engine developed by NOAA\'s Office of Water Prediction. Sonali Vyas implemented streamflow simulation with interpolated runoff at hydrofabric catchments using T-Route. Comparison of routed streamflow at the gauge outlet with observations showed that the kriging-initialized T-Route simulation captured both the peak timing and recession during Hurricane Helene. This demonstrates that combining streamflow kriging with T-Route is a viable approach for streamflow simulation (with lag times of 1\u201324 hours) in ungauged basins within the NextGen water resources modeling framework.\\n\\n![T-route simulation at South Toe River using kriged runoff](/img/blog/2026-05-kriging/t-route-south-toe.png)\\n\\n**Figure 2:** T-route simulation of streamflow initialized using held-out kriged runoff in the NextGen hydrofabric of the South Toe River.\\n\\n## Summary\\n\\nHourly streamflow kriging is now operational within the NextGen Research Data Stream, delivering spatially complete estimates for all NextGen v2.2 hydrofabric catchments. This observation-based approach supports a broad range of potential applications including streamflow analysis and historical reconstruction, National Water Model calibration, streamflow forecasting, and data assimilation for ungauged basins.\\n\\n## Links\\n\\n1. [GitHub repository \u2014 streamflow kriging (qkrig)](https://github.com/DualEarth/qkrig)\\n2. [GitHub repository \u2014 T-route streamflow simulation with kriging](https://github.com/sonalivyascse19-stack/t-route)\\n3. [Streamflow analysis from kriging DataStream](https://datastream.ciroh.org/#outputs/qkrig/)\\n4. [Daily streamflow reanalysis dataset based on kriging](https://us-east-2.console.aws.amazon.com/s3/buckets/streamflow-interpolation-noaa14?region=us-east-2&prefix=daily_kriging%2F&showversions=false&tab=objects)\\n5. [Hourly streamflow reanalysis dataset based on kriging](https://us-east-2.console.aws.amazon.com/s3/buckets/streamflow-interpolation-noaa14?region=us-east-2&prefix=hourly_kriging%2F&showversions=false&tab=objects)\\n\\n## Acknowledgements\\n\\nSpecial thanks to Kunal Sarna and Harsha Vemula for collaborating and integrating hourly kriging into NRDS in 3 weeks.\\n\\nThis research was supported by the Cooperative Institute for Research to Operations in Hydrology (CIROH) through NOAA Cooperative Agreement NA22NWS4320003. CIROH cyberinfrastructure used: AWS S3 (daily and hourly streamflow reanalysis products from 1979\u20132025 WYs), EC2 (testing the kriging workflow in NRDS), and DataStream (hourly streamflow analysis outputs)."},{"id":"teehr-april-2026","metadata":{"permalink":"/staging/main/blog/teehr-april-2026","source":"@site/blog/2026-04-24-Teehr.mdx","title":"TEEHR and CIROH Advance Cloud-Based Hydrologic Model Evaluation into a New Era","description":"TEEHR advances hydrologic model evaluation at scale by combining a cloud-based data platform and a Python analytics package built for large, iterative analysis across models, locations, and time periods","date":"2026-04-24T00:00:00.000Z","tags":[{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"TEEHR","permalink":"/staging/main/blog/tags/teehr"}],"readingTime":5.51,"hasTruncateMarker":true,"authors":[{"name":"Sam Lamont","title":"Lead Software Developer","title2":"RTI International","url":"https://www.linkedin.com/in/sam-lamont-3a972813/","imageURL":"/staging/main/img/blog/authors/Sam_Lamont.jpg","key":"sam-lamont","page":null},{"name":"Matthew Denno","title":"Lead Software Developer","title2":"RTI International","url":"https://www.linkedin.com/in/matthew-denno-pe-9b9316a/","imageURL":"/staging/main/img/profiles/Matthew_Denno.jpg","key":"matt-denno","page":null},{"name":"Katie van Werkhoven","title":"Lead Science Advisor","title2":"RTI International","url":"https://www.linkedin.com/in/katievanwerkhoven/","imageURL":"/staging/main/img/profiles/Katie_Werkhoven.jpg","key":"katie-van-werkhoven","page":null},{"name":"Sam Landsteiner","title":"Software Developer","title2":"RTI International","url":"https://www.linkedin.com/in/sam-landsteiner-00752913/","imageURL":"/staging/main/img/profiles/Sam_Landsteiner.png","key":"sam-landsteiner","page":null}],"frontMatter":{"title":"TEEHR and CIROH Advance Cloud-Based Hydrologic Model Evaluation into a New Era","description":"TEEHR advances hydrologic model evaluation at scale by combining a cloud-based data platform and a Python analytics package built for large, iterative analysis across models, locations, and time periods","slug":"teehr-april-2026","tags":["CIROH","TEEHR"],"authors":["sam-lamont","matt-denno","katie-van-werkhoven","sam-landsteiner"],"image":"/img/blog/2026-04-teehr/fig5.png"},"unlisted":false,"prevItem":{"title":"Continental-Scale Streamflow Simulation Using Kriging in the NGIAB-NRDS NextGen Ecosystem","permalink":"/staging/main/blog/continental-scale-streamflow-kriging-ngiab-nrds"},"nextItem":{"title":"The NextGen Research DataStream (NRDS): A Reproducible Numerical Prediction System for Accelerating Research to Operations in Hydrology","permalink":"/staging/main/blog/nextgen-research-datastream-april-2026"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\nimport ProfileCards from \'/src/components/ProfileCards\';\\n\\nexport const teehrProfiles = [\\n  {\\n    name: \'Matthew Denno (PI)\',\\n    title: \'Lead Software Developer\',\\n    organization: \'RTI International\',\\n    email: \'mdenno@rti.org\',\\n    imagePath: \'/img/profiles/Matthew_Denno.jpg\',\\n  },\\n  {\\n    name: \'Katie van Werkhoven\',\\n    title: \'Lead Science Advisor\',\\n    organization: \'RTI International\',\\n    email: \'kvanwerkhoven@rti.org\',\\n    imagePath: \'/img/profiles/Katie_Werkhoven.jpg\',\\n  },\\n  {\\n    name: \'Sam Lamont\',\\n    title: \'Lead Software Developer\',\\n    organization: \'RTI International\',\\n    email: \'slamont@rti.org\',\\n    imagePath: \'/img/profiles/Sam_Lamont.jpg\',\\n  },\\n  {\\n    name: \'Sam Landsteiner\',\\n    title: \'Software Developer\',\\n    organization: \'RTI International\',\\n    email: \'slandsteiner@rti.org\',\\n    imagePath: \'/img/profiles/Sam_Landsteiner.png\',\\n  },\\n]\\n\\nCIROH is advancing hydrologic model evaluation into a new era. Led by a core team of developers and scientists at RTI, with testing and contributions from others across the consortium, we\'ve built TEEHR \u2014 a system purpose-built for evaluating models at scale. Combining novel approaches to data analytics with cutting-edge open data infrastructure, TEEHR enables a truly complete picture of model and forecast performance across datasets, sites, historical time periods, and forecast horizons. \\n\\n## Why do we need TEEHR?\\n\\nTEEHR is built on a fundamental question: \u201CWhich hydrologic model is better?\u201D. At its simplest, this can seem trivial; the model simulation is paired with observations, a few performance metrics are calculated, and you\'re on your way to a common performance analysis. Things can start to get more complicated if want to go larger, dig deeper or ask more nuanced questions:\\n\\n-\\tWhat if we want to compare many models against each other?\\n-\\tWhat if we want to analyze thousands of locations with 40-years of hourly timestep data at the continental scale?\\n-\\tWhat if we want to interrogate the data with questions like:\\n    -\\t\u201CHow does performance during high-flow events compare to low-flow events?\u201D\\n    -\\t\u201CHow does model performance relate to physical basin attributes?\u201D\\n    -\\t\u201CWhat\'s the uncertainty associated with the resulting metrics?\u201D\\n-\\tWhat if we want to make the data easily accessible to the hydrologic community to support both historical and near-real time analyses?\\n\\nThese are the challenges TEEHR is designed to address.\\n\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   class=\\"dark-mode-white-bg\\"\\n   src={useBaseUrl(\'/img/blog/2026-04-teehr/fig1.png\')}\\n   width=\'100%\'\\n   alt=\\"TEEHR is optimized for large-scale iterative model interrogation and data management.\\"\\n   />\\n  <figcaption><em>TEEHR is optimized for large-scale iterative model interrogation and data management</em></figcaption>\\n</figure>\\n\\n{/* truncate */}\\n\\n## What is TEEHR?\\n### The TEEHR Framework\\nTEEHR began as a Python package enabling robust and iterative evaluation of hydrologic models.  It has since expanded into a cloud-based platform (TEEHR-Cloud) consisting of a high-performance data warehouse optimized for huge analytic tables, a suite of cloud-based services supporting data exploration, automated processing and data ingests, and web-hosted interactive dashboards. \\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   class=\\"dark-mode-white-bg\\"\\n   src={useBaseUrl(\'/img/blog/2026-04-teehr/fig2.png\')}\\n   width=\'60%\'\\n   alt=\\"The TEEHR-Cloud framework consists of a high-performance data warehouse, cloud-based evaluation manager, and an installable Python package\\"\\n   />\\n  <figcaption><em>The TEEHR-Cloud framework consists of a high-performance data warehouse, cloud-based evaluation manager, and an installable Python package</em></figcaption>\\n</figure>\\n\\n### TEEHR-Cloud\\nTEEHR-Cloud delivers evaluation-ready insights and datasets that are publicly available and continuously updated \u2014 including 40 years of hourly retrospective streamflow simulations across more than 8,000 gage sites, model forcings summarized to drainage basins (mean areal precipitation and temperature), and a real-time evaluation manager for live data ingestion and analysis of operational NWM, RFC forecasts and CIROH\u2019s NextGen Research Data Stream (NRDS). It\'s all built on Apache Iceberg, an open table format designed for the demands of big data at scale and proven by well-known big data industries (e.g., Netflix).\\n\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   class=\\"dark-mode-white-bg\\"\\n   src={useBaseUrl(\'/img/blog/2026-04-teehr/fig3.png\')}\\n   width=\'100%\'\\n   alt=\\"A suite of services in the evaluation manager enables real-time ingests, web-based dashboards, interactive exploration, and more.\\"\\n   />\\n  <figcaption><em>A suite of services in the evaluation manager enables real-time ingests, web-based dashboards, interactive exploration, and more.</em></figcaption>\\n</figure>\\n\\n### TEEHR-Python\\nTEEHR-Python is the analytics engine that puts this data to work. Powered by PySpark for scalable, distributed compute and Apache Iceberg for robust data management \u2014 including time travel, upsert/append/delete operations, schema evolution, and ACID transactions \u2014 it gives analysts the full power of modern data engineering in a hydrologic context. An ever-growing suite of signature, deterministic, and probabilistic metrics, with sampling uncertainty estimation built-in, means users can interrogate model performance in ways that simply weren\'t easily accessible before.  TEEHR-Python is still a Python package that users can install in their own environment via `pip install teehr` to use with their own data and to access datasets in the TEEHR-Cloud data warehouse.\\n\\n<figure style={{ textAlign: \\"center\\"}}>\\n  <img\\n   class=\\"dark-mode-white-bg\\"\\n   src={useBaseUrl(\'/img/blog/2026-04-teehr/fig4.png\')}\\n   width=\'100%\'\\n   alt=\\"TEEHR-Python consists of tools supporting data fetching and loading, validation and storage, and robust analytics.\\"\\n   />\\n  <figcaption><em>TEEHR-Python consists of tools supporting data fetching and loading, validation and storage, and robust analytics.</em></figcaption>\\n</figure>\\n\\n### What are the TEEHR-Cloud Dashboards?\\n\\nSeveral web-based dashboards, currently in development, allow users to view and interact with the data warehouse from application-specific perspectives. The two active dashboards include more general retrospective model comparisons and forecast analysis, while other, more application-specific, dashboards in development will focus on:\\n-\\tOperational forecast (NWM, RFC) diagnostic and event-based evaluation\\n-\\tMulti-model intercomparison to baselines with uncertainty\\n-\\tEnsemble water supply forecasts\\n-\\tForecast Informed Reservoir Operations (FIRO)\\n-\\tFlash flood forecasts\\n-\\tLow flow forecasts\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   class=\\"dark-mode-white-bg\\"\\n   src={useBaseUrl(\'/img/blog/2026-04-teehr/fig5.png\')}\\n   width=\'100%\'\\n   alt=\\"Screen capture of the retrospective model comparison dashboard\\"\\n   />\\n  <figcaption><em>Screen capture of the retrospective model comparison dashboard</em></figcaption>\\n</figure>\\n## Summary\\n\\nThe TEEHR framework is under active development, as we continue to expand historical and real-time data ingests, application-specific dashboards, and core TEEHR-Python functionality. To learn more about TEEHR, the [documentation](https://rtiinternational.github.io/teehr/) is a good place to start (link below). If you want to ask a question, request a change or new feature, or report a bug, you can reach out through the CIROH #teehr slack channel, by creating an issue on the [TEEHR GitHub repos](https://GitHub.com/RTIInternational/teehr), or by contacting us directly. Thanks for reading!\\n\\n### Additional Links:\\n- Documentation: https://hub.ciroh.org/docs/products/evaluation/rtiteehr/\\n- TEEHR documentation: https://rtiinternational.github.io/teehr/\\n- Dashboards (in-development): https://dashboards.teehr.rtiamanzi.org/\\n- TEEHR repo: https://github.com/RTIInternational/teehr\\n- TEEHR-Cloud repo: https://github.com/RTIInternational/teehr-hub\\n\\n## Our Team\\n\\n<ProfileCards profiles={teehrProfiles} />"},{"id":"nextgen-research-datastream-april-2026","metadata":{"permalink":"/staging/main/blog/nextgen-research-datastream-april-2026","source":"@site/blog/2026-03-25-A-NextGen-Research-DataStream.mdx","title":"The NextGen Research DataStream (NRDS): A Reproducible Numerical Prediction System for Accelerating Research to Operations in Hydrology","description":"An open, cloud-based numerical prediction system enabling rapid, reproducible research-to-operations workflows in hydrology using NextGen.","date":"2026-03-25T00:00:00.000Z","tags":[{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NRDS","permalink":"/staging/main/blog/tags/nrds"},{"inline":true,"label":"AWS","permalink":"/staging/main/blog/tags/aws"},{"inline":true,"label":"Hydrology","permalink":"/staging/main/blog/tags/hydrology"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"Open Source","permalink":"/staging/main/blog/tags/open-source"},{"inline":true,"label":"Cloud Computing","permalink":"/staging/main/blog/tags/cloud-computing"},{"inline":true,"label":"DevOps","permalink":"/staging/main/blog/tags/dev-ops"},{"inline":true,"label":"R2O","permalink":"/staging/main/blog/tags/r-2-o"},{"inline":true,"label":"Numerical Prediction","permalink":"/staging/main/blog/tags/numerical-prediction"}],"readingTime":9.66,"hasTruncateMarker":true,"authors":[{"name":"Jordan Laser","title":"Software Engineer","title2":"Lynker","url":"https://github.com/JordanLaserGit","imageURL":"https://avatars.githubusercontent.com/u/79336055?v=4","key":"jordan","page":null},{"name":"Arpita Patel","title":"Assistant Director, IT and DevOps","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2025","page":null},{"name":"Harsha Vemula","title":"DevOps Engineer","title2":"Alabama Water Institute","url":"https://github.com/harshavemula-ua","imageURL":"/staging/main/img/blog/authors/harsha-vemula.jpeg","key":"harsha-vemula","page":null}],"frontMatter":{"title":"The NextGen Research DataStream (NRDS): A Reproducible Numerical Prediction System for Accelerating Research to Operations in Hydrology","description":"An open, cloud-based numerical prediction system enabling rapid, reproducible research-to-operations workflows in hydrology using NextGen.","slug":"nextgen-research-datastream-april-2026","tags":["CIROH","NextGen","NGIAB","NRDS","AWS","Hydrology","National Water Model","Open Source","Cloud Computing","DevOps","R2O","Numerical Prediction"],"authors":["jordan","arpita-2025","harsha-vemula"],"image":"/img/blog/2026-03-nrds/T2D_2_TMP_2maboveground_cali.gif"},"unlisted":false,"prevItem":{"title":"TEEHR and CIROH Advance Cloud-Based Hydrologic Model Evaluation into a New Era","permalink":"/staging/main/blog/teehr-april-2026"},"nextItem":{"title":"Expanding Access to NextGen Research through the CIROH Community NextGen Hub (CCNH) in Cloud","permalink":"/staging/main/blog/ciroh-ccnh-nextgen-march-2026"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\nTechnological advances are evolving water prediction capabilities at a ludicrous pace. From revolutionary machine learning algorithms to dramatic advances in computational hardware, the potential for making accurate hydrologic predictions has never been higher. To meet this new potential, the hydrologic community continuously generates models and approaches based on cutting edge research that could potentially benefit operational systems. However, many of these innovations lack a path to operational deployment.\\n\\n**The NextGen Research Datastream (NRDS) provides a mechanism by which these ideas can be refined and make their way into operations.**\\n\\nDeveloped by Lynker and the Alabama Water Institute (a Cooperative Institute for Research to Operations in Hydrology partnership), the NRDS facilitates the actualization a research idea from the community in a scalable and deployable numerical prediction system. \\nTo evaluate each of these modeling concepts, NRDS deploys prototype models to generate a continuous \u201Cdatastream\u201D. These outputs can then be evaluated and made more accurate. This cycle of streamlined deployment and iterative design lets these prototypes mature into a product that can be picked up by an operational forecasting team.\\n\\nTo enable this process to be done rapidly and smoothly, the entire system is designed with reproducibility and iterative improvement as core principles.\\nThe NRDS is an automated numerical prediction system generating regular stream flow forecasts that uses the NextGen Water Resources Modeling Framework (NextGen) as the core modeling engine and NextGen In A Box (NGIAB) as the simulation environment. This system generates forecasts across the contiguous United States (CONUS) on CIROH\'s operational cyberinfrastructure backbone: the research-to-operations (R2O) Hybrid Cloud (R2OHC) platform, with deployment on the AWS cloud. What makes the NRDS exciting is that the entire system is open-sourced, reproducible, publicly browsable, and potentially editable by anyone in the hydrologic community.\\n\\n{/* truncate */}\\n\\n## Why the NRDS Matters\\n\\nFor decades, operational hydrologic modeling has been a largely closed process. National-scale models like the National Water Model (NWM) are developed and maintained by federal agencies where HPC access is limited. While these models frequently produce insights and forecasts of excellent quality, the simulations themselves have proven difficult to reproduce and improve upon from within the hydrologic research community, hindering the knowledge flow from research to operations. By contrast, the NRDS is totally public and open. This provides both researchers and national agencies with immediate access, reducing the latency between the discovery of new and potentially valuable knowledge and its operational implementation.\\n\\nDeployed on AWS cloud from the [ngen-datastream repository](https://github.com/CIROH-UA/ngen-datastream), the NRDS regularly ingests meteorological forcing data, processes it through the NextGen framework using community-configured parameters, and produces streamflow predictions for river reaches across the country. The forcing data, model configuration, infrastructure, and simulation outputs are all publicly available through the [NRDS S3 data portal](https://datastream.ciroh.org/index.html) and the [NRDS visualizer](http://nrds.ciroh.org/). Researchers can browse the results, compare them against observations, and reproduce or run their own simulations with the exact tooling that supports the NRDS. This transparency and usability enables researchers to readily propose improvements to any component of the NRDS system stack.\\n\\nThis is a fundamentally new paradigm for how national-scale water prediction can work: an open, iterative, community-driven feedback loop where regional expertise flows directly into an operational-like system.\\n\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n    src={useBaseUrl(\'/img/blog/2026-03-nrds/architecture.png\')}\\n    alt=\\"Figure 1. An overview diagram of the NRDS architecture. NWM data from the NOAA is used as a forcing source, which is converted into catchment-averaged forcing files by the Forcing Processor. Meanwhile, DattreamCLI draws from the Community Hydrofabric and community parameters to generate BMI configurations. Together, these are used to execute a model run in NextGen in a Box, the outputs of which are stored in an AWS S3 bucket for browsing via datastream.ciroh.org.\\"\\n  />\\n  <figcaption><em>Figure 1. An overview diagram of the NRDS architecture.</em></figcaption>\\n</figure>\\n\\n## How the Community Can Contribute\\n\\nThis open contribution model is perhaps the most exciting aspect of the NRDS. The configuration files and NextGen model formulation that drive the daily simulations are publicly hosted and directly referenced during every execution. This means that community-proposed improvements to parameterization can flow directly into the operational system just by modifying these files.\\n\\nThe process is intentionally straightforward. A researcher who has improved upon the parameterization of a particular VPU realization file can navigate to the [ngen-datastream Issues page](https://github.com/CIROH-UA/ngen-datastream/issues) on GitHub, open a new issue using the dedicated \\"Propose NRDS/NextGen Research DataStream parameter update\\" template, and submit their updated configuration along with supporting evidence. The CIROH team then reviews these contributions; once validated, they are merged and deployed into the live NRDS system.\\n\\nThis contribution pathway was a central theme at the [2025 CIROH Developers Conference (DevCon 2025)](https://ciroh.ua.edu/devconference/2025-ciroh-developers-conference/), where a dedicated workshop walked participants through the complete process of proposing a configuration change. Attendees received access to virtual machines on NSF JetStream2 with pre-installed tooling, enabling them to run local simulations, compare results, and prepare a contribution \u2014 all within a single workshop session.\\n\\nThe NRDS is not designed to be a product delivered by a central team. It is a platform designed to absorb and amplify the collective expertise of the hydrologic community.\\n\\n## Multiple Datastreams Live and Scaling\\n\\nThe long-term potential of the NRDS is further amplified by its scalability in deploying additional model formulations to generate regular forecasts. The system now runs multiple concurrent datastreams, each using a different hydrologic modeling approach within the NextGen framework to generate streamflow forecasts.\\n\\nCurrently, the NRDS operates a CFE-NOM datastream across all CONUS and parallelized across Vector Processing Units (VPUs), which pairs the Conceptual Functional Equivalent (CFE) rainfall-runoff model with the Noah-OWP-Modular land surface model. Alongside this, an LSTM DataStream has been deployed for all CONUS, bringing cutting-edge machine learning-based streamflow prediction into an operational-like system. Both of these datastreams route the NextGen outputs using T-Route.\\n\\nThe most recent release, [v2.2.0](https://github.com/CIROH-UA/ngen-datastream/releases/tag/v2.2.0) (February 2026), deployed the LSTM model into the production NRDS system \u2014 a milestone that brings differentiable and machine learning-based hydrology into an automated, cloud-based production environment. This builds on the broader CIROH effort to integrate models like \u03B4HBV 2.0 from Penn State\'s MHPI group. \\n\\nThere is also a Routing-Only DataStream for VPU 03W. This datastream focuses on channel routing NWM outputs using T-Route only, a novel experiment by [Quinn Lee](https://github.com/quinnylee).\\n\\n## The Broader Ecosystem\\n\\nThe NRDS is deeply interconnected with the broader suite of CIROH tools that are making NextGen modeling accessible. NextGen In A Box (NGIAB) provides the containerized runtime environment that researchers can use locally to test configurations before proposing them to the NRDS. The DataStreamCLI (now in its [own repository](https://github.com/CIROH-UA/datastreamcli)) automates the complete workflow from data preprocessing to NextGen execution. The ForcingProcessor (also [split out](https://github.com/CIROH-UA/forcingprocessor)) handles the conversion of gridded meteorological data into the catchment-averaged forcings that NextGen requires. Once the model outputs are generated, TEEHR (Tools for Exploratory Evaluation in Hydrologic Research) provides standardized evaluation capabilities for comparing model outputs against observations (dashboard available [here](https://dashboards.teehr.rtiamanzi.org/forecast)).\\n\\nTogether, these tools form a coherent pipeline: prepare data with the ForcingProcessor and DataStreamCLI, run simulations locally with NGIAB, evaluate results with TEEHR, and \u2014 if improvements are found \u2014 contribute them back to the NRDS for operational deployment. \\n\\n## What\'s Next\\n\\nThe trajectory of the NRDS points toward an increasingly capable and diverse operational system. Active development efforts include implementing the hourly, deep learning-based differentiable model \u03B4HBV 2.0 MTS, which was recently embedded into the NGIAB-NRDS ecosystem through a collaboration between Penn State and the Alabama Water Institute. This model has demonstrated continental-scale streamflow forecasting capabilities that rival the current National Water Model.\\n\\nThere is also ongoing work to make the NRDS outputs more accessible and useful to downstream consumers. The [NRDS Visualizer](http://nrds.ciroh.org/) now provides a web-based interface for browsing and exploring daily simulation results. The [TEEHR Evaluation Dashboard](https://dashboards.teehr.rtiamanzi.org/forecast) now provides rapid evaluation of these simulation results, enabling researchers to gauge model performance as events are occurring and weigh the performance of each datastream (NextGen model-formulation) relative to other datastreams.\\n\\nWith NRDS ecosystem quickly reaching maturity, now is the time for hydrologic researchers to put their research ideas to the test and deploy them in this operational-like environment. \\n\\n## Get Involved\\n\\nThe NextGen Research DataStream represents a new kind of infrastructure for water science: one that is as much a social and organizational innovation as it is a technical one. By making national-scale hydrologic simulations open, reproducible, and community-editable, the NRDS creates the conditions for a distributed network of research hydrologists to incrementally improve the accuracy and reliability of streamflow predictions across the country.\\n\\nWhether you are a graduate student exploring NextGen for the first time, a river forecast center hydrologist with deep regional expertise, or a researcher developing novel modeling approaches, the NRDS offers a concrete pathway from your work to operational impact.\\n\\nHere\'s how to get started:\\n- NRDS on the NextGen in a Box product portfolio website: [ngiab.ciroh.org/#/nrds](https://ngiab.ciroh.org/#/nrds)\\n- Explore the data: Browse daily outputs at [datastream.ciroh.org](https://datastream.ciroh.org/) or the [NRDS Visualizer](http://nrds.ciroh.org/)\\n- Examine the NRDS deployment status timeline to see which datastreams have been deployed, when, and at what scale: [NRDS Status](https://github.com/CIROH-UA/ngen-datastream/blob/main/docs/nrds/STATUS_AND_METADATA.md)\\n- Propose an improvement: Use the [NRDS Issues page](https://github.com/CIROH-UA/ngen-datastream/issues) to submit your idea for a new datastream or an edit to an existing deployment.\\n- Join the conversation: Participate in [GitHub Discussions](https://github.com/CIROH-UA/ngen-datastream/discussions) to connect with the community\\n- Read the documentation: Visit the [CIROH Hub NRDS page](https://hub.ciroh.org/docs/products/ngiab-ecosystem/nrds/) for comprehensive documentation on the NRDS system and broader ecosystem.\\n- Try out NRDS tools: Clone the various NRDS repositories to experiment with the NRDS workflow.\\n  - [DataStreamCLI](https://github.com/CIROH-UA/datastreamcli) *(Figure 2)*: the on-server workflow tool used in NRDS simulations. This tool offers the ability to reproduce NRDS simulations, with a modular design for integrating research configurations and processing components.\\n  - [ForcingProcessor](https://github.com/CIROH-UA/forcingprocessor/) *(Figure 3)*: a scalable tool for processing NWM operational data files into NextGen inputs. This tool provides the processing to generate NRDS forcings. \\n\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n    src={useBaseUrl(\'/img/blog/2026-03-nrds/datastreamcli.jpg\')}\\n    alt=\\"Figure 2. The DataStreamCLI workflow. From left to right: \'LynkerSpatial Hydrofabric via hfsubset\', \'National Water Model Forcings processing\', \'NextGen and BMI config file generation\', \'File and directory validation\', \'NextGen in a Box\', \'Data file hashing and metadata\', \'Evaluation by TEEHR\'.\\"\\n  />\\n  <figcaption><em>Figure 2. The DataStreamCLI workflow.</em></figcaption>\\n</figure>\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n    src={useBaseUrl(\'/img/blog/2026-03-nrds/T2D_2_TMP_2maboveground_cali.gif\')}\\n    alt=\\"Figure 3. An animated gif depicting forcing data before and after subsetting via ForcingProcessor. On the right, the processed data visibly matches the NWM original, but is neatly cut out to match the boundaries of the NGEN run.\\"\\n  />\\n  <figcaption><em>Figure 3. Forcing data before and after subsetting via ForcingProcessor.</em></figcaption>\\n</figure>\\n\\n### The future of water prediction is open. Come build it with us.\\n\\n---\\n\\n*The NextGen Research DataStream is developed and maintained by CIROH at the University of Alabama, with funding under award NA22NWS4320003 from the NOAA Cooperative Institute Program. Learn more at [ciroh.ua.edu](https://ciroh.ua.edu/).*"},{"id":"ciroh-ccnh-nextgen-march-2026","metadata":{"permalink":"/staging/main/blog/ciroh-ccnh-nextgen-march-2026","source":"@site/blog/2026-03-24-CCNH-in-Cloud.mdx","title":"Expanding Access to NextGen Research through the CIROH Community NextGen Hub (CCNH) in Cloud","description":"A cloud-based, ready-to-use environment that simplifies access to the NextGen water modeling framework for researchers.","date":"2026-03-24T00:00:00.000Z","tags":[{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"Cloud Computing","permalink":"/staging/main/blog/tags/cloud-computing"},{"inline":true,"label":"Hydrology","permalink":"/staging/main/blog/tags/hydrology"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"Open Source","permalink":"/staging/main/blog/tags/open-source"},{"inline":true,"label":"DevOps","permalink":"/staging/main/blog/tags/dev-ops"},{"inline":true,"label":"Cyberinfrastructure","permalink":"/staging/main/blog/tags/cyberinfrastructure"}],"readingTime":4.35,"hasTruncateMarker":true,"authors":[{"name":"Ayman Nassar","title":"Postdoctoral Researcher","title2":"Utah State University","url":"https://www.linkedin.com/in/ayman-nassar-24a92723/","imageURL":"/staging/main/img/blog/authors/ayman_nassar.png","key":"ayman","page":null},{"name":"David Tarboton","title":"Professor","title2":"Utah Water Research Laboratory","url":"https://www.linkedin.com/in/dtarb/","imageURL":"/staging/main/img/blog/authors/david_tarboton.jpg","key":"david","page":null},{"name":"Arpita Patel","title":"Assistant Director, IT and DevOps","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2025","page":null},{"name":"Furqan Baig","title":"Research Programmer","title2":"University of Illinois at Urbana-Champaign","url":"https://www.linkedin.com/in/furqanbaig/","imageURL":"/staging/main/img/blog/authors/furqan-baig.jpeg","key":"furqan-baig","page":null},{"name":"Homa Salehabadi","title":"Postdoctoral Researcher","title2":"Utah State University","url":"https://www.linkedin.com/in/homasalehabadi/","imageURL":"https://scholar.googleusercontent.com/citations?view_op=medium_photo&user=LsGbadwAAAAJ&citpid=5","key":"homa","page":null},{"name":"Benjamin Lee","title":"Development Operations Engineer","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/seungchanlee/","imageURL":"/staging/main/img/blog/authors/benjamin-lee.png","key":"benjamin-lee","page":null},{"name":"Josh Cunningham","title":"Software Engineer","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/josh-cunningham-6906a7108/","imageURL":"/staging/main/img/blog/authors/josh.jpeg","key":"josh","page":null}],"frontMatter":{"title":"Expanding Access to NextGen Research through the CIROH Community NextGen Hub (CCNH) in Cloud","description":"A cloud-based, ready-to-use environment that simplifies access to the NextGen water modeling framework for researchers.","slug":"ciroh-ccnh-nextgen-march-2026","tags":["CIROH","NextGen","NGIAB","Cloud Computing","Hydrology","National Water Model","Open Source","DevOps","Cyberinfrastructure"],"authors":["ayman","david","arpita-2025","furqan-baig","homa","benjamin-lee","josh"],"image":"/img/blog/2026-03-ccnh/diagram.png"},"unlisted":false,"prevItem":{"title":"The NextGen Research DataStream (NRDS): A Reproducible Numerical Prediction System for Accelerating Research to Operations in Hydrology","permalink":"/staging/main/blog/nextgen-research-datastream-april-2026"},"nextItem":{"title":"Hourly Differentiable Modeling Arrives in the NGIAB-NRDS NextGen Ecosystem","permalink":"/staging/main/blog/awi-psu-collab2"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\n## Opening New Doors for Research with the NextGen Framework\\n\\nThe NextGen framework holds great potential for hydrologic modeling, but is often inaccessible due to its strenuous setup and requirements. As such, embedding it within a cloud-based framework offers a natural solution to this problem by removing some of the administrative and technical requirements for compute resource setup and computational library configuration, thus opening the door for a wider audience to tke advantage of the strengths of the framework.\\n\\nWith the **CIROH Community NextGen Hub (CCNH)**, we\u2019ve created a cloud-based environment that addresses exactly those setup challenges, so users can focus on science instead of software.\\n\\n## A Preconfigured, Ready-to-Use Cloud Environment\\nCCNH is a containerized, cloud-based modeling environment hosted on the [CIROH-2i2c JupyterHub](https://ciroh.awi.2i2c.cloud/). It packages everything a researcher needs to run end-to-end NextGen workflows \u2014 from input preprocessing through model execution, calibration, evaluation, and output visualization \u2014 into a single, ready-to-use JupyterHub image.\\nBuilt on the same containerization patterns as NGIAB, CCNH leverages a Pangeo base image and includes:\\n\\n- **Pre-compiled NextGen framework binaries** from NGIAB based docker image\\n- **NGIAB data preprocessing tools** for automated retrieval and subsetting of hydrofabric and meteorological forcing datasets\\n- **T-Route** routing components for streamflow simulation\\n- **SPOTPY**(Statistical Parameter Optimization Tool for Python) for model calibration\\n- **TEEHR**(Tools for Exploratory Evaluation in Hydrologic Research) for performance evaluation\\n- **PyNGIAB**, a Python wrapper that lets you run NextGen simulations directly from Jupyter notebooks\\n- **HydroShare integration tools** (nbfetch, hs_files-jupyter, hsclient) for seamless data exchange to save results in HydroShare for collaboration, reproducibility and publishing \\n- **JupyterLab** with distributed computing capabilities for interactive, scalable workflows\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img\\n   class=\\"dark-mode-white-bg\\"\\n   src={useBaseUrl(\'/img/blog/2026-03-ccnh/diagram.png\')}\\n   width=\'60%\'\\n   alt=\\"Diagram illustrating how HydroShare resources, 2i2c JupyterHub, and S3 Object Store interact to enable streamlined NextGen workflows in the cloud.\\"\\n   />\\n  <figcaption><em>Diagram illustrating how HydroShare resources, 2i2c JupyterHub, and S3 Object Store interact to enable streamlined NextGen workflows in the cloud.</em></figcaption>\\n</figure>\\nThe result: researchers can go from zero to running a calibrated NextGen simulation in a fraction of the time previously required.\\n\\n{/* truncate */}\\n\\n## Streamlined Workflow, Clear Results\\nThrough guided notebooks, users can:\\n\\n- Prepare and subset input data  \\n- Run simulations  \\n- Calibrate models  \\n- Evaluate performance  \\n- Explore outputs interactively  \\n\\n...all within a single environment designed for efficiency and discovery.\\n\\n## Why It Matters\\nBy lowering technical barriers and using a cloud-based approach, CCNH makes NextGen accessible to a broader research community.\\nIt allows scientists to spend less time on setup and more time advancing hydrologic understanding.\\n\\n## How to Access CCNH\\n<img\\n  src={useBaseUrl(\'/img/blog/2026-03-ccnh/screenshot.png\')}\\n  width=\'100%\'\\n  alt=\\"Picture of the CIROH-2i2c JupyterHub interface showing the Server Options page where users can select compute profiles and the CCNH image to launch a NextGen modeling environment in the cloud.\\"\\n/>\\nThere are two primary ways to launch CCNH in the CIROH-2i2c JupyterHub environment:\\n\\n### Option 1: Launch Directly from CIROH-2i2c JupyterHub\\n1. Go to: https://ciroh.awi.2i2c.cloud/  \\n2. Click **\u201CLogin to continue\u201D** and authenticate with your CIROH credentials. (If this is your first time, you may be prompted to authorize access through GitHub.) \\n3. On the **Server Options** page:\\n   - Select the desired compute profile (Small, Medium, Large, or Huge).\\n   - Select the **CIROH Community NextGen Hub image**.\\n4. Click **Start** to launch the JupyterHub.\\n\\nYou are now inside a CIROH 2i2c JupyterHub session running the CCNH image, which provides a fully configured NextGen modeling environment.\\n\\n### Option 2: Launch from a HydroShare Resource (\u201COpen With\u201D)\\nOne of the most powerful features of CIROH-2i2c JupyterHub is its [integration with HydroShare](https://hub.ciroh.org/ciroh_hub_staging/docs/services/cloudservices/2i2c/hydroshare-integration). You can open a HydroShare resource directly in a CIROH-2i2c JupyterHub session running the CCNH image:\\n1. Navigate to a HydroShare resource. (for example: https://www.hydroshare.org/resource/27045581bdea4808a393330f2417379c/)  \\n2. Click **Open With**  (top-right of the resource page) and select **CIROH-2i2c JupyterHub**. \\n3. Click **\u201CLogin to continue\u201D** and authenticate with your CIROH credentials. (If this is your first time, you may be prompted to authorize access through GitHub.) \\n4. On the **Server Options** page:\\n   - Select the desired compute profile (Small, Medium, Large, or Huge).\\n   - Select the **CIROH Community NextGen Hub** image.\\n5. Click **Start** to launch the JupyterHub.\\n6. (If you did this with the example resource above, click on and launch one of the Jupyter Notebooks to step through the NextGen workflows.)\\n\\n## References\\n- Nassar, A., Tarboton, D., Baig, F., Cunningham, J., Patel, A., Halgren, J., Lee, B., Salehabadi, H., Castronova, A., and Garousi-Nejad, I. \\"Accelerating community research applications of the NextGen water modeling framework through CUAHSI HydroShare linked with CIROH-2i2c JupyterHub.\\" *Environmental Modelling & Software*. (In-review)\\n- Nassar, A., Tarboton, D., Baig, F., Patel, A., Cunningham, J., and Salehabadi, H. (2026). NextGen Water Modeling Workflow for Research-Scale Applications. https://www.hydroshare.org/resource/27045581bdea4808a393330f2417379c  \\n- I-GUIDE VCO: [Enabling Community Research with the Next Generation National Water Modeling Framework](https://i-guide.io/i-guide-vco/enabling-community-research-with-the-next-generation-national-water-modeling-framework-through-streamlined-workflows-on-ciroh-jupyterhub/)\\n- CIROH Hub: https://hub.ciroh.org/docs/products/ngiab-ecosystem/ngiab/distributions/nextgen-2i2c/"},{"id":"awi-psu-collab2","metadata":{"permalink":"/staging/main/blog/awi-psu-collab2","source":"@site/blog/2026-02-20-Hourly-dHBV2.mdx","title":"Hourly Differentiable Modeling Arrives in the NGIAB-NRDS NextGen Ecosystem","description":"Penn State and AWI reunite to introduce an hourly differentiable model to AWI\'s NextGen Ecosystem.","date":"2026-02-20T00:00:00.000Z","tags":[{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Alabama Water Institute","permalink":"/staging/main/blog/tags/alabama-water-institute"},{"inline":true,"label":"Pennsylvania State University","permalink":"/staging/main/blog/tags/pennsylvania-state-university"},{"inline":true,"label":"Hydrology","permalink":"/staging/main/blog/tags/hydrology"},{"inline":true,"label":"Differentiable Modeling","permalink":"/staging/main/blog/tags/differentiable-modeling"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NRDS","permalink":"/staging/main/blog/tags/nrds"},{"inline":true,"label":"Hourly","permalink":"/staging/main/blog/tags/hourly"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"Cloud Services","permalink":"/staging/main/blog/tags/cloud-services"},{"inline":true,"label":"AI and Machine Learning","permalink":"/staging/main/blog/tags/ai-and-machine-learning"}],"readingTime":8.76,"hasTruncateMarker":true,"authors":[{"name":"Leo Lonzarich","title":"Graduate Researcher","title2":"Pennsylvania State University","url":"https://www.linkedin.com/in/leoglonz","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U075PFL5NUE-150fbf871a79-512","key":"leo","page":null},{"name":"Quinn Lee","title":"Programmer Analyst","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/linked--quinn/","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U072YTSNJFL-6bae7401aaac-192","key":"quinn","page":null},{"name":"Josh Cunningham","title":"Software Engineer","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/josh-cunningham-6906a7108/","imageURL":"/staging/main/img/blog/authors/josh.jpeg","key":"josh","page":null},{"name":"Benjamin Lee","title":"Development Operations Engineer","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/seungchanlee/","imageURL":"/staging/main/img/blog/authors/benjamin-lee.png","key":"benjamin-lee","page":null},{"name":"Arpita Patel","title":"Assistant Director, IT and DevOps","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2025","page":null}],"frontMatter":{"title":"Hourly Differentiable Modeling Arrives in the NGIAB-NRDS NextGen Ecosystem","description":"Penn State and AWI reunite to introduce an hourly differentiable model to AWI\'s NextGen Ecosystem.","slug":"awi-psu-collab2","tags":["CIROH","Blog","Alabama Water Institute","Pennsylvania State University","Hydrology","Differentiable Modeling","NextGen","NGIAB","NRDS","Hourly","National Water Model","Cloud Services","AI and Machine Learning"],"authors":["leo","quinn","josh","benjamin-lee","arpita-2025"]},"unlisted":false,"prevItem":{"title":"Expanding Access to NextGen Research through the CIROH Community NextGen Hub (CCNH) in Cloud","permalink":"/staging/main/blog/ciroh-ccnh-nextgen-march-2026"},"nextItem":{"title":"CIROH Hub: Your New Central Home for CIROH Research, Tools, and Community Resources","permalink":"/staging/main/blog/ciroh-hub-release"}},"content":"In October 2025, Penn State\'s Multi-scale Hydrology, Processes and Intelligence group (MHPI), led by Dr. Chaopeng Shen, and the Alabama Water Institute (AWI), led by Steve Burian and Arpita Patel, achieved a milestone R2O effort: the preliminary integration of \u03B4HBV 2.0 [4] -- a daily-scale, high-resolution, distributed differentiable model -- into a NextGen ecosystem. This resulted in the first adoption of a differentiable model into [NextGen In A Box (NGIAB)](https://github.com/CIROH-UA/NGIAB-CloudInfra) [2] and provided an opportunity for CIROH researchers to fine-tune the \u03B4HBV 2.0 architecture for NextGen operation.\\n\\nHaving proven viability for daily timescale predictions on high-resolution river networks [4], MHPI researchers recently adapted \u03B4HBV 2.0 into a multi-timescale architecture designed to parameterize HBV and simulate streamflow at hourly intervals, at scale, across the NextGen HydroFabric. This new model, \u03B4HBV 2.0 MTS (Multi-TimeScale) [5], is a fusion of a daily and hourly \u03B4HBV 2.0 model designed to efficiently handle ML training with high geospatial *and* temporal complexity. (See [MTS Architecture](/blog/awi-psu-collab2#mts-architecture) for more details about this construction.)\\n\\nWith \u03B4HBV 2.0 MTS maintaining similar forecasting skill compared to its daily-scale counterpart [5], Penn State and AWI were once again reunited in a joint effort to embed hourly scale differentiable modeling within AWI\'s operational ecosystem as a demonstration of model viability and to facilitate open access to its runtime.\\n\\n## Differentiable Models\\n\\n\u03B4HBV 2.0 and \u03B4HBV 2.0 MTS differentiable model constructions are briefly outlined here to contextualize the development efforts. For further detail, see each model\'s respective citation.\\nAt their core, differentiable models embed traditional process-based equations (here, the [HBV](https://en.wikipedia.org/wiki/HBV_hydrology_model) rainfall-runoff model) inside a machine learning training loop. Because these models are designed to be differentiable (e.g., in PyTorch), gradients flow end-to-end from the loss function back through the physical equations and into the neural networks that supply their parameters. This lets the model learn optimal parameterizations directly from observed data while still obeying mass-balance and storage constraints encoded in HBV -- combining interpretability and physical consistency of process-based hydrology with the flexibility of deep learning.\\n\\n{/* truncate */}\\n\\n### \u03B4HBV 2.0\\n\\nThe daily model uses Long Short-Term Memory (LSTM)  and Multi-Layer Perceptron (MLP) neural networks (NNs) to learn time-dynamic and static parameters for HBV 2.0 [4] (a modified form of HBV). Weather forcings (precipitation, temperature, PET) and static catchment attributes are used as inputs to simulate hydrological states and fluxes:\\n\\n$$\\n\\\\begin{align*}\\n    \\\\theta_{d, m}^{1:t} &= \\\\text{LSTM}( x_m^{1:t}, A_m ) \\\\\\\\\\n    \\\\theta_{s, m} &= \\\\text{MLP}( A_m ) \\\\\\\\\\n    Q_k^{1:t}, S_k^{1:t} &= \\\\text{HBV}(x_m^{1:t}, \\\\theta_{d, m}^{1:t}, \\\\theta_{s, m})\\n\\\\end{align*}\\n$$\\n\\nwhere:\\n* $\\\\theta$: Learned dynamic ($d$) and static ($s$) parameters.\\n* $x_m, A_m$: Forcings and attributes for unit basin $m$.\\n* $Q, S$: Model fluxes (e.g., streamflow) and states (e.g., snowpack).\\n\\nIn NextGen, hourly input forcings are aggregated at the end of every day to produce a single daily prediction, which is then distributed across the following 24 hours before a new prediction is made.\\nBecause HBV is a recurrent, bucket-based model, its internal states (e.g., groundwater stores) must be \\"warmed up\\" by running the model over a period just prior to the target simulation window so that storages can equilibrate. The same process initializes the internal states of the parameterization LSTM, which is itself recurrent.\\n\\n### MTS Architecture\\n\\nExtending \u03B4HBV 2.0 from daily to hourly resolution is not simply a matter of shortening the timestep. Hourly simulation demands sensitivity to rapid forcing variability, yet the model\'s internal storages still depend on slow-evolving, seasonal-scale memory. Training a single hourly model with a sufficiently long lookback to capture both regimes (i.e., 365 days) would be prohibitively expensive. The MTS (Multi-TimeScale) architecture [5] addresses this by coupling a daily and hourly \u03B4HBV 2.0 model in a two-stage design:\\n\\n1. **Daily warmup (long memory)**: The daily model processes ~351 days of aggregated daily inputs, building up slow-evolving states such as deep groundwater and snowpack.\\n2. **Hourly warmup (short memory)**: Those states are handed off to the hourly model, which refines them over 7 days of hourly forcing to capture fast dynamics like sub-daily storm response.\\n3. **Hourly simulation**: With states fully initialized, the hourly model produces 7 days of predictions.\\n4. **Rolling window**: At the end of each 7-day simulation window, the cache shifts forward 7 days and the warmup process repeats.\\n\\nA rolling-window input caching mechanism underpins this cycle, storing ~351 days of daily inputs alongside ~7 days of hourly inputs so that each warmup-simulation pass can be executed efficiently without reprocessing the full history.\\n\\n## Building A Stronger Bridge\\n\\nSupporting \u03B4HBV 2.0 MTS in AWI\'s [NextGen](https://github.com/CIROH-UA/ngen), NGIAB, and [NGIAB Data-Preprocess](https://github.com/CIROH-UA/NGIAB_data_preprocess) required significant contributions and dialogue between both institutions. \\n\\nFrom Penn State, Leo Lonzarich incorporated MTS into the existing [dhbv2](https://github.com/mhpi/dhbv2) NextGen module, which couples with the differentiable modeling framework [\u03B4MG](https://github.com/mhpi/generic_deltamodel) to build hybrid models [3]. This update for MTS architecture addressed three key challenges for NextGen deployment: time-sequential runtimes not traditionally supported by ML models that operate on all timesteps simultaneously, the absence of daily forcing data, and no available derived potential evapotranspiration (PET) forcing.\\n\\nTo address the first two challenges, a new ring buffer mechanism was added to the BMI module. As described above, both the LSTM and HBV require warmup with historical data; the ring buffer caches batches of input forcings so that states can be warmed up in bulk (more efficiently than step-by-step) before the model advances sequentially with the initialized states. The ring buffer also handles the fact that NextGen (NWM 4.0, CIROH-UA) are intended to provide an hourly forcing while \u03B4HBV 2.0 MTS requires daily inputs as well. In such a case, the buffer aggregates hourly forcings to daily scale on the fly during runtime.\\n\\nThe final challenge was replacing Hargreaves PET, one of the standard inputs for \u03B4HBV 2.0 MTS, which previously needed to be computed in advance of runtime. Hargreaves\' method is a daily measure requiring a full day of observations -- fundamentally incompatible with the MTS BMI\'s sequential operation. To resolve this, a Penman-Monteith calculation was added within the BMI to derive PET on-the-fly.\\n\\nAt AWI, Quinn Lee and Josh Cunningham, with help from Benjamin Lee, spearheaded the architectural integration and operational evaluation of the \u03B4HBV 2.0 module within the NGIAB ecosystem. AWI\'s efforts centered on data orchestration, model runtime validation and BMI compliance, and systems integration.\\n\\nAWI developed automated workflows within NGIAB Data-Preprocess to generate the inputs required by both the daily and MTS models, aligning high-resolution HydroFabric attributes with hourly AORC forcing data and ensuring that realization and routing configurations met \u03B4HBV 2.0 and NextGen expectations. With these inputs, AWI tested the \u03B4HBV 2.0 BMI runtime to verify that outputs were reproducible across systems and that Data-Preprocess was producing correct model behavior.\\n\\nPerhaps the most substantial effort involved reconciling \u03B4HBV 2.0\'s dependencies with the existing NGIAB architecture for Docker image construction. This ultimately required refactoring \u03B4HBV 2.0 and its supporting packages (\u03B4MG, [hydrodl2](https://github.com/mhpi/hydrodl2)) as well as parts of NGIAB\'s Dockerfile for more efficient builds.\\n\\nIn sum, this collaboration ensured that \u03B4HBV 2.0 MTS did not remain a standalone model, but a fully containerized, \\"plug-and-play\\" component of the NextGen ecosystem, ready for deployment across diverse computing environments.\\n\\n## Looking Forward\\n\\nWith both daily- and hourly-scale \u03B4HBV 2.0 models implemented in NGIAB and NGIAB Data-Preprocess, the next step is adoption into the [NextGen Research DataStream (NRDS)](https://github.com/CIROH-UA/ngen-datastream). This work is already scheduled, and we anticipate recurring runtimes of both models with near-realtime simulations on the Community HydroFabric available to CIROH collaborators in the near future. Differentiable model simulations will then be accessible through the NRDS Visualizer, where researchers and community members can explore, assess, and iterate on outputs in real time.\\n\\nFor NOAA-OWP, ongoing work will continue to support the integration of \u03B4HBV 2.0 MTS into their NextGen test bench for preliminary evaluation as a candidate for the NWM 4.0.\\n\\nDifferentiable routing products are also in consideration for operational deployment. For instance, differentiable Muskingum-Cunge, introduced by Tadd Bindas et al. [1] at Penn State, is actively being developed and could appear operationally as a dynamic parameterization module for T-Route or as a standalone routing module. Public development is ongoing in [DDR](https://github.com/DeepGroundwater/ddr).\\n\\nAWI and Penn State\'s strong collaborative track record is anticipated to continue as both teams support and potentially integrate new models into their NGIAB-NRDS ecosystem. Some of these efforts may also appear in DevCon later this spring. Ultimately, these successes stand as testaments to the value of inter-institutional collaboration for accelerating the integration of lab-bound research into operations for the broader CIROH community.\\n\\n---\\n\\n## Code\\n\\n* [\u03B4HBV 2.0 Operational Module Repository](https://github.com/mhpi/dhbv2)\\n* [\u03B4MG Differentiable Modeling Framework](https://github.com/mhpi/generic_deltamodel) (Backbone for \u03B4HBV 2.0; includes documentation and tutorials for building custom differentiable hydrologic models.)\\n* [Differentiable Distributed Routing (DDR)](https://github.com/DeepGroundwater/ddr)\\n* [MHPI Codebase](https://mhpi.github.io/codes/)\\n\\n## Publications\\n\\n1. Bindas, T., Tsai, W.-P., Liu, J., Rahmani, F., Feng, D., Bian, Y., et al. (2024). Improving river routing using a differentiable Muskingum-Cunge model and physics-informed machine learning. Water Resources Research, 60, e2023WR035337. [https://doi.org/10.1029/2023WR035337](https://doi.org/10.1029/2023WR035337)\\n2. Patel, A., Halgren, J., Wills, Z., Frazier, N., Lee, B., Cunningham, J., et al. (2025). NextGen In A Box (NGIAB): Open-Source containerization of the NextGen framework to enable community-driven hydrology modeling. Environmental Modelling & Software, Volume 193. [https://doi.org/10.1016/j.envsoft.2025.106666](https://doi.org/10.1016/j.envsoft.2025.106666)\\n3. Lonzarich, L., Shen, C., Song, Y., Rahmani, F., & Lawson, K. (2025). mhpi/generic_deltamodel: High-resolution differentiable model, \u{1D6FF}HBV2.0 (Version v1.4.0) [Computer software]. Zenodo. [https://doi.org/10.5281/zenodo.14828008](https://doi.org/10.5281/zenodo.14828008)\\n4. Song, Y., Bindas, T., Shen, C., Ji, H., Knoben, W. J. M., Lonzarich, L., et al. (2025). High-resolution national-scale water modeling is enhanced by multiscale differentiable physics-informed machine learning. Water Resources Research, 61, e2024WR038928. [https://doi.org/10.1029/2024WR038928](https://doi.org/10.1029/2024WR038928)\\n5. Yang, W., Ji, H., Lonzarich, L., Song, Y., Shen, C. (2025). Diffusion-Based Probabilistic Modeling for Hourly Streamflow Prediction and Assimilation. arXiv. [https://arxiv.org/abs/2510.08488](https://arxiv.org/abs/2510.08488) [In Review]"},{"id":"ciroh-hub-release","metadata":{"permalink":"/staging/main/blog/ciroh-hub-release","source":"@site/blog/2026-02-20-ciroh-hub-release.mdx","title":"CIROH Hub: Your New Central Home for CIROH Research, Tools, and Community Resources","description":"January Monthly Blog Update","date":"2026-02-20T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"CIROH Hub","permalink":"/staging/main/blog/tags/ciroh-hub"}],"readingTime":5.72,"hasTruncateMarker":true,"authors":[{"name":"Nia Minor","title":"Graduate Research Assistant","title2":"Alabama Water Institute","url":"https://github.com/sheargrub","imageURL":"/staging/main/img/blog/authors/nia-minor.png","key":"nia-minor","page":null},{"name":"Manjila Singh","title":"Graduate Research Assistant","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/manjilasingh/","imageURL":"https://ngiab.ciroh.org/assets/img/team/Me.jpg","key":"manjila","page":null},{"name":"Prajwal Halalae","title":"Undergraduate Research Intern","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/prajwal-nh/","imageURL":"/staging/main/img/profiles/Prajwal_Halalae.jpg","key":"prajwal-halalae","page":null},{"name":"Giovanni Romero","title":"Hydroinformatics Engineer","title2":"Aquaveo","url":"https://www.linkedin.com/in/elkin-giovanni-romero-bustamante-b834b5a8","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U057VCZQWRW-fe48d8f10837-192","key":"gio","page":null},{"name":"James Dolinar","title":"Software Engineer","title2":"Aquaveo","url":"https://github.com/James-Dolinar","imageURL":"/staging/main/img/blog/authors/james-dolinar.png","key":"james-dolinar","page":null},{"name":"Dan Ames","title":"Professor","title2":"Brigham-Young University","url":"https://cce.byu.edu/directory/dan-ames","imageURL":"/staging/main/img/profiles/Dan_Ames.jpg","key":"dan-ames","page":null},{"name":"Arpita Patel","title":"Assistant Director, IT and DevOps","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2025","page":null}],"frontMatter":{"title":"CIROH Hub: Your New Central Home for CIROH Research, Tools, and Community Resources","description":"January Monthly Blog Update","slug":"ciroh-hub-release","authors":["nia-minor","manjila","prajwal-halalae","gio","james-dolinar","dan-ames","arpita-2025"],"tags":["Blog","CIROH","CIROH Hub"],"hide_table_of_contents":false,"image":"img/blog/2026-02-ciroh-hub-release/hub_header.png"},"unlisted":false,"prevItem":{"title":"Hourly Differentiable Modeling Arrives in the NGIAB-NRDS NextGen Ecosystem","permalink":"/staging/main/blog/awi-psu-collab2"},"nextItem":{"title":"CIROH Cyberinfrastructure and Hydroinformatics Team at AGU25","permalink":"/staging/main/blog/agu2025"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\nimport { Carousel } from \\"react-responsive-carousel\\"\\n\\nFor the past three years, CIROH Portal and DocuHub have greatly expanded the visibility of CIROH\u2019s research and software products,\\nallowing hydrology professionals from across the community to explore and leverage each other\u2019s developments to maximize their operational\\nbenefits and enhance life-saving outcomes in domains like streamflow modeling, flood inundation mapping, and public outreach. However,\\nboth sites have always experienced some overlap in their purposes, leading to occasional confusion that has hampered their efforts\\nto make CIROH research truly accessible to the community.\\n\\nTo address this, we are excited to introduce **CIROH Hub**: a fully unified platform that brings all CIROH resources together in one place. \\n\\nVisit [hub.ciroh.org](https://hub.ciroh.org) to explore the full breadth of CIROH\u2019s research and resources, including dynamic collections\\nof community [datasets](/datasets), [applications](/apps), [courses](/courses), and [notebooks](/notebooks) through HydroShare, a listing of CIROH [publications](/publications) through the community Zotero\\ncollection, extensive [documentation](/docs/products/intro) on CIROH\u2019s tools and software, guidance on [accessing leading infrastructure](/docs/services/intro) for hydrological computing,\\nand much more.\\n\\n<Carousel\\n  showThumbs={false}\\n  autoPlay={true}\\n  stopOnHover={false}\\n  useKeyboardArrows={true}\\n  emulateTouch={true}\\n  interval={3500}\\n  infiniteLoop\\n  showStatus={false}\\n  showIndicators={true}\\n  >\\n   <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2026-02-ciroh-hub-release/hub_preview_1.png\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"Preview of CIROH Hub homepage\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2026-02-ciroh-hub-release/hub_preview_2.png\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"Preview of CIROH Hub\'s Applications page\\"\\n    />\\n  </div>\\n   <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2026-02-ciroh-hub-release/hub_preview_3.png\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"Preview of CIROH Hub\'s Documentation landing page\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2026-02-ciroh-hub-release/hub_preview_4.png\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"Preview of CIROH Hub\'s Working Groups page\\"\\n    />\\n  </div>\\n</Carousel>\\n\\n{/* truncate */}\\n\\n## What\'s New in CIROH Hub\\nCIROH Hub preserves everything you relied on from CIROH Portal and DocuHub, while introducing powerful new features to enhance visibility, usability, and collaboration across the consortium.\\n\\n### A Fresh Visual Experience\\nCIROH Hub launches with a dynamic new visual theme with interactive elements. The interface is designed to be engaging for first\u2011time users while improving navigation for returning visitors.\\n\\n### Dedicated Jupyter Notebooks Portal\\n\\nPreviously, Jupyter Notebooks were posted under the \u201CDatasets\u201D section of the CIROH Portal \u2014 a location that didn\u2019t reflect their purpose and made them harder to find.\\nCIROH Hub now offers a purpose\u2011built [\u201CNotebooks\u201D section](/notebooks), giving notebooks a clear identity and improving their accessibility. Notebook authors can have their resources surfaced by adding the keyword `ciroh_hub_notebook` in HydroShare.\\n\\n### Public Directory of Working Groups\\n\\nCIROH Hub now also includes CIROH\'s [Working Groups](/working-groups). We hope this resource will make it easy for researchers to identify working groups relevant to their work, enhancing collaboration and strengthening the consortium\u2019s shared mission.\\n\\n---\\n\\n## Contributing to CIROH Hub\\n\\nWith all of the CIROH resources consolidated in one place, contributing your work has never been simpler. \\nCIROH Hub enables you to share your resources with the community.\\n\\n### Share Research via HydroShare\\n\\nThe \u201CResearch Portal\u201D section of CIROH Hub hosts content from CIROH Portal and, like it, is open to community contributions.\\nWhether you\u2019d like to share a web application, dataset, educational course, presentation, or Jupyter Notebook, any of these\\nresources can be easily surfaced onto CIROH Hub from HydroShare via the inclusion of [appropriate keyword tags and optional metadata](/contribute#hydroshare).\\n\\n### Update HydroShare Tags\\n\\nTo coincide with the merger, new HydroShare tags have been established to populate resources in CIROH Hub.\\nWhile we expect to support the existing, deprecated set of keywords indefinitely, we recommend transitioning\\nyour resources to use the new CIROH Hub keywords where possible.\\n\\nA full list of current and deprecated HydroShare keywords is available on the [Contribute page](/contribute#hydroshare).\\nPlease ensure the appropriate tags are applied to your resources in HydroShare.\\n\\n### Add Publications via Zotero\\n\\nSubmitting your publications via Zotero ensures they appear in CIROH Hub\u2019s consolidated publication listings, which allows the community to view, iterate on, and cite your research.\\n[Request access to the CIROH group library now](/contribute#zotero) to get started. \\n\\n### Contributing Documentation\\nIf you\u2019ve created a tool or software with useful documentation, the Documentation section of CIROH Hub is a great place to make that information easily accessible.\\nThis documentation can be automatically mirrored from your project\u2019s GitHub repository README.md, allowing you to meet CIROH\u2019s open-science best practices while\\nkeeping maintenance simple. To get started, [submit a request or PR through the CIROH Hub repository](/contribute#resources-documentation).\\n\\n---\\n\\n## Sunsetting CIROH Portal and DocuHub\\n\\nWith CIROH Hub taking over their roles, we will be winding down CIROH Portal and DocuHub in the coming weeks. As of Monday, February 16th, 2026, neither site will be updated with the latest content and features, though dynamically loaded content will continue to populate both sites. During this time, we strongly recommend updating your links and bookmarks to point to the new site to ensure continuity of service for your users and readers.\\n\\nBoth CIROH Portal and DocuHub will remain online until **Thursday, March 25th, 2026**. When that date arrives, both portal.ciroh.org and docs.ciroh.org will be converted into redirect domains that point to the corresponding locations on CIROH Hub.\\n\\n### Accessibility Updates\\n\\nWhile CIROH Hub\u2019s visual refresh may be appealing, we are aware that the site\u2019s new animated elements may pose challenges for users with visual focus or computer performance issues. As such, we plan to introduce a reduced-motion mode by the end of March to address these limitations, ensuring that CIROH Hub\u2019s core pursuit of accessibility is truly honored in every sense of the word. This timeframe means that both CIROH Portal and DocuHub will remain available in their current forms until a fully accessible version of CIROH Hub is available, ensuring that everyone can continue to take full advantage of CIROH resources.\\n\\n---\\n\\n## Looking Ahead\\n\\nCIROH\u2019s strength lies in its community and dedication to open science. By centralizing access to CIROH\u2019s resources, we aim to bring the consortium into closer collaboration, maximizing our effectiveness as we translate cutting-edge advancements into operational successes in water management and public safety.\\n\\nIf you have any questions, feedback, or feature requests, reach out to the CIROH Hub team:\\n\\nGitHub: Submit an issue on the [ciroh_hub repository](https://github.com/ciroh-ua/ciroh_hub)\\n\\nSlack: Join the #ciroh-hub channel (Email [ciroh-it-support@ua.edu](ciroh-it-support@ua.edu) for access)"},{"id":"agu2025","metadata":{"permalink":"/staging/main/blog/agu2025","source":"@site/blog/2026-01-23-AGU2025.mdx","title":"CIROH Cyberinfrastructure and Hydroinformatics Team at AGU25","description":"January Monthly Blog Update","date":"2026-01-23T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"},{"inline":true,"label":"AGU","permalink":"/staging/main/blog/tags/agu"}],"readingTime":6.99,"hasTruncateMarker":true,"authors":[{"name":"Quinn Lee","title":"Programmer Analyst","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/linked--quinn/","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U072YTSNJFL-6bae7401aaac-192","key":"quinn","page":null},{"name":"Arpita Patel","title":"Assistant Director, IT and DevOps","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2025","page":null}],"frontMatter":{"title":"CIROH Cyberinfrastructure and Hydroinformatics Team at AGU25","description":"January Monthly Blog Update","slug":"agu2025","authors":["quinn","arpita-2025"],"tags":["Blog","Conference","CIROH","Monthly Update","AGU"],"hide_table_of_contents":false,"image":"img/blog/2026-01-agu25/AGU_01.jpg"},"unlisted":false,"prevItem":{"title":"CIROH Hub: Your New Central Home for CIROH Research, Tools, and Community Resources","permalink":"/staging/main/blog/ciroh-hub-release"},"nextItem":{"title":"AWS re:Invent 2025: Key Insights for Research and Cyberinfrastructure ","permalink":"/staging/main/blog/aws-reinvent-2025"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\nimport { Carousel } from \\"react-responsive-carousel\\"\\n\\nAs we do every year, the CIROH team took on the American Geophysical Union (AGU) Annual Meeting 2025 by storm. The Amtrak shuttled us from famously frigid Tuscaloosa to balmy New Orleans, where we *laiss\xe2mes les bons temps rouler* a few months early. From December 15-19, our team shared presentations and posters (and beignets and Cajun food), demonstrating CIROH\'s commitment to advancing hydrologic science, open collaboration, and sharing technological advancements.\\n\\n{/* truncate */}\\n\\n<Carousel\\n  showThumbs={false}\\n  autoPlay={true}\\n  stopOnHover={false}\\n  useKeyboardArrows={true}\\n  emulateTouch={true}\\n  interval={3500}\\n  infiniteLoop\\n  showStatus={false}\\n  showIndicators={true}\\n  >\\n   <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2026-01-agu25/AGU_05.jpeg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"AGU 2025\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2026-01-agu25/AGU_06.jpg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\'AGU 2025\'\\n    />\\n  </div>\\n   <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2026-01-agu25/AGU_01.jpg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"AGU 2025\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2026-01-agu25/AGU_02.jpeg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\'AGU 2025\'\\n    />\\n  </div>\\n    <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2026-01-agu25/AGU_03.jpeg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\'AGU 2025\'\\n    />\\n  </div>\\n\\n</Carousel>\\n\\n## Where Science Connects Us\\nAll good event attendees embrace the theme, and we happen to be great event attendees. This year\'s AGU theme, \\"Where Science Connects Us,\\" aligned with CIROH\'s mission to democratize water modeling and foster community engagement in hydrologic research. Our presentations highlighted how we use containerization, cloud infrastructure, and collaborative frameworks in the world of operational and research hydrology. We also loved connecting with the broader CIROH community through the CIROH Research Exchange (lovingly dubbed T-REX by our talented events team), our biggest exhibit hall booth to date, a very packed poster presentation caravan led by our fearless Steve Burian, Martyn Clark, and Katie van Werkhoven, and, in classic AGU fashion, running into colleagues randomly in the extremely long convention center hallways.\\n\\n## Featured Presentations & Posters by CIROH Science Team & Friends\\n\\n### NextGen In A Box (NGIAB) Ecosystem\\n1. **Advancing Hydrological Modeling: CIROH\u2019s NextGen In A Box (NGIAB) and Enhanced Tools for Community-Driven Research**\\n\\n    Presenter: Bhavya Duvvuri\\n\\n    Session: Poster Presentation H41Q-1427\\n\\n2. **NextGen Research DataStream: Community Contributions Towards Improved Hydrologic Predictions**\\n   \\n    Presenter: Zach Wills\\n\\n    Session: Oral Presentation H31G-03\\n\\n3. **Assessing the use of Physics and AI-Driven Precipitation Forecasts for Streamflow Prediction Using the NextGen In A Box (NGIAB) National Water Model**\\n\\n    Presenter: Jorge Bravo\\n    \\n    Session: Poster Presentation H41Q-1410\\n\\n4. **NextGen In A Box (NGIAB) and DataStream Visualizer: A Containerized Web Application for Interactive Geospatial and Temporal Visualization and Analysis of Hydrologic Model Outputs**\\n    \\n    Presenter: Gio Romero\\n    \\n    Session: Oral Presentation H31G-08\\n\\n5. **Streamlining Community Modeling through Automated Data Processing for the Next Generation Water Resources Modeling Framework**\\n    \\n    Presenter: Sonam Lama\\n   \\n    Session: Poster Presentation IN33B-0380\\n\\n### Cyberinfrastructure\\n\\n1. **Cloud infrastructure for NextGen Water Resources Modeling: CIROH\u2019s R2OHC Cloud Platform**\\n   \\n    Presenter: Harsha Vemula\\n   \\n    Session: Poster Presentation H41Q-1425\\n\\n2. **High-Performance Computing Infrastructure for NextGen Water Resources Modeling: CIROH\'s R2OHC HPC Platform**\\n  \\n    Presenter: Trupesh Patel\\n \\n    Session: Oral Presentation H33J-07\\n\\n### Data Sharing & Community Engagement\\n1. **CIROH DocuHub and Portal: Knowledge Management System for Collaborative Water Resources Research**\\n  \\n    Presenter: Manjila Singh\\n  \\n    Session: Poster Presentation H41Q-1426\\n\\n2. **Demonstrating new tools and frameworks to facilitate continental-scale hydrologic data access and evaluation**\\n \\n    Presenter: Sam Lamont\\n   \\n    Session: Oral Presentation IN42A-04\\n\\n3. **Enabling Community Research with the Next Generation National Water Modeling Framework on through Streamlined Workflows**\\n   \\n    Presenter: Ayman Nassar\\n  \\n    Session: Oral Presentation H31G-07\\n\\n4. **Modernizing HydroShare: Using a Cloud-Native Architecture to Accelerate Water Science Innovation**\\n  \\n    Presenter: Tony Castronova\\n  \\n    Session: Oral Presentation IN42A-02\\n\\n## Reflections from AGU25\\n\\nAGU is a wild world. It\u2019s incredible how you can pack the population of a small town into one convention center and still have room left to spare. It\u2019s even more incredible that at seemingly every turn, we always recognized at least a few citizens of said small town. We had such a wonderful time getting to see old friends and make new ones and come away from each conversation with a new idea for how CIROH Science Team could collaborate with the community. \\nOur team was so encouraged by the number of presentations and posters we saw that used our community resources like our NGIAB container and our high-performance computing cyberinfrastructure offerings like Pantarhei and Wukong. (Perhaps you were one of our 13,101 NGIAB Docker deployments?) Not mentioned in the brief list above are all the presentations we got to see about model developments for the NextGen Framework. We love supporting our member and partner institutions\u2019 research-to-operations work with our cyberinfrastructure resource offerings and community resource repositories like the [Data Preprocessor](https://github.com/CIROH-UA/NGIAB_data_preprocess), [TEEHR](https://github.com/CIROH-UA/ngiab-teehr), and the [Tethys Visualizer](https://github.com/CIROH-UA/ngiab-client). We would also love to showcase that work in our NextGen Research Datastream, running every hour for all of CONUS on AWS. If you\u2019ve got a model that you\u2019d like included in NGIAB and/or NRDS, we are more than happy to chat about it (or read through your GitHub issues submitted through our [model integration issue form](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues)). We\u2019re excited to get to work this year and support you and all of your R2O dreams!\\n\\n## Community Resources\\nAll AGU25 presentation materials, including posters and slide decks, are available in our GitHub repository: [CIROH-UA/Conferences/AGU25](https://github.com/CIROH-UA/Conferences/tree/main/AGU25)\\n\\n## Join the Community and Get Involved\\nDid AGU leave you wanting more from CIROH? We might not be able to see all of you in person every day (we miss y\u2019all already), but whether you\'re a hydrologist, software developer, data scientist, or agency partner, there are many ways to get involved.\\n\\n\u2022\\t**Try NGIAB**: Download from [DockerHub](https://hub.docker.com/r/awiciroh/ciroh-ngen-image) or access [NGIAB 101](https://docs.ciroh.org/training-NGIAB-101/) for more details.\\n\\n\u2022\\t**Contribute Models to NGIAB**: Submit BMI-compliant models integration request through our [model integration issue form](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues) under the \u201CNew issue\u201D button.\\n\\n\u2022\\t**Calibrate Models**: Use our [calibration tools](https://github.com/CIROH-UA/ngiab-cal) to calibrate models for your favorite watersheds (we all have those, don\u2019t pretend like you don\u2019t know what we\u2019re talking about!).\\n\\n\u2022\\t**Share Feedback**: Open [GitHub issues](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues) to report bugs and suggest improvements, or join our Community Resources Working Group discussions.\\n\\n\u2022\\t**Slack Channel**: Join our public slack channels for community discussions\\n\\n\u2022\\t**Working Groups**: Participate in one (or more, for you overachievers) of [CIROH\u2019s working groups](https://app.smartsheet.com/b/form/019f1f425a1d717180af65a76b9fa26f) \u2013 Artificial Intellgience, Community Resources, Decision Support, Early Career, Flood Inundation Mapping, Hydroinformatics, Hydrologic Modeling, Model and Forecast Evaluation.\\n\\n\u2022\\t**Student Summer Education Programs**: Are you/do you know any undergraduates interested in AI and operational hydrology who are looking for research experiences over the summer? We have an [REU](https://graduate.ua.edu/academics/summer-research-programs-for-undergraduate-students/ai-for-operational-hydrology/) for exactly that. Applications are due March 1. (Side effects: students may leave as Alabama football fans. Roll Tide!!)\\n\\n\u2022\\t**DevCon**: Attend yearly Developer Conference in May. DevCon 2026 is in Salt Lake City, UT from May 27-29.\\n\\n## Acknowledgments\\nCIROH\'s work is supported by NOAA Cooperative Institute Program under award NA22NWS4320003. We gratefully acknowledge the contributions from our numerous academic and agency partners who make this collaborative research possible.\\n\\nThe AGU25 presentations represent the collective effort of researchers, developers, and operational forecasters working together to advance hydrologic science. They are a culmination of months and years of dedication and love for science and research. Thank you to everyone who said hi, visited our posters, attended our presentations, and engaged in discussions about the future of water modeling. We\u2019ll see you next year in San Francisco!"},{"id":"aws-reinvent-2025","metadata":{"permalink":"/staging/main/blog/aws-reinvent-2025","source":"@site/blog/2026-01-02-AWS-Reinvent.mdx","title":"AWS re:Invent 2025: Key Insights for Research and Cyberinfrastructure ","description":"Insights from AWS re:Invent 2025 on AI, cloud efficiency, security, and innovations relevant to CIROH\u2019s hybrid cyberinfrastructure.","date":"2026-01-02T00:00:00.000Z","tags":[{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"AWS","permalink":"/staging/main/blog/tags/aws"}],"readingTime":3.86,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"Assistant Director, IT and DevOps","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2025","page":null},{"name":"Scott Hendrickson","title":"Sr Solutions Architect WWPS Education","title2":"Amazon Web Services","url":"https://www.linkedin.com/in/scott-hendrickson-76273b2/","imageURL":"/staging/main/img/blog/authors/scott-hendrickson.jpeg","key":"scott-hendrickson","page":null}],"frontMatter":{"title":"AWS re:Invent 2025: Key Insights for Research and Cyberinfrastructure ","description":"Insights from AWS re:Invent 2025 on AI, cloud efficiency, security, and innovations relevant to CIROH\u2019s hybrid cyberinfrastructure.","slug":"aws-reinvent-2025","tags":["CIROH","Blog","AWS"],"authors":["arpita-2025","scott-hendrickson"],"image":"/img/blog/2026-01-aws-reinvent/AWS_blog_pic_0.png"},"unlisted":false,"prevItem":{"title":"CIROH Cyberinfrastructure and Hydroinformatics Team at AGU25","permalink":"/staging/main/blog/agu2025"},"nextItem":{"title":"Moving Hydrologic Prediction Forward \u2014 A software integration meeting at the Alabama Water Institute","permalink":"/staging/main/blog/software-integration-meeting"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img src={useBaseUrl(\\"/img/blog/2026-01-aws-reinvent/AWS_blog_pic_1.png\\")} alt=\\"A photo from AWS re:Invent 2025\\" style={{ maxWidth: \\"100%\\" }} />\\n</figure>\\n\\n## AI, DevOps and the Future of Cloud Infrastructure \\nAWS re:Invent did not disappoint! I spent the first week of December at Amazon Web Services\' flagship conference in Las Vegas. The event delivered cutting-edge technical insights, showcased the rapid evolution of cloud computing and AI, and provided countless opportunities to connect with industry leaders.  \\n\\nThe energy across all five conference venues was more vibrant than I ever imagined it would be. \\n{/* truncate */}\\n## The Central Theme: AI and Agentic AI \\nUnsurprisingly, the hottest topics throughout the conference were AI and Agentic AI. From keynote sessions to hands-on demos, the focus was on real-world applications, responsible AI development, and the next frontier of autonomous systems. Seeing how organizations are leveraging AI to create value sparked new ideas for advancing research infrastructure. \\n\\nHowever, an important reality: security remains paramount. As Agentic AI systems grow more capable, robust security frameworks will be essential to ensure trust and stability. \\n\\n## A Developer and DevOps Paradise \\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img src={useBaseUrl(\\"/img/blog/2026-01-aws-reinvent/AWS_blog_pic_0.png\\")} alt=\\"Photos from AWS re:Invent 2025\\" style={{ maxWidth: \\"100%\\" }} />\\n</figure>\\nAs a first-time attendee of AWS re:Invent, I was amazed by the work showcased during this conference! The conference showcased new ways to develop and bring ideas from concept to production-scale prototypes. As AWS CEO Matt Garman said in his keynote: \\"Why not?\\" That spirit of possibility and rapid innovation was there throughout the week. For those who missed it, I highly recommend watching the rapid-fire announcements from Matt\u2019s keynote here: [AWS re:Invent 2025 Keynote](https://reinvent.awsevents.com/keynotes/?trk=direct).\\n\\nThe keynotes from both the CEO and Dr. Swami Sivasubramanian were insightful. AWS is making strategic moves that are fundamentally changing how we deploy applications on the cloud\u2014making workloads more cost-optimized and efficient. For CIROH, where we manage a hybrid infrastructure across multiple cloud platforms and on-premises, these insights are directly applicable to our ongoing efforts to democratize access to computational resources while managing costs effectively. \\n\\n## Community Connections \\n\\nOne of my favorite experiences was attending the AWS Community Builder Hub. As a member of the AWS Community Builders program, I had the privilege of connecting with others working with AWS. The group was warm, welcoming, and incredibly insightful. Everyone I spoke with shared advice and perspectives that left me feeling both energized and supported. \\n\\nI also got a chance to meet Jason Dunn in person\u2014a great leader in sharing AWS content and community knowledge! These personal connections remind me why community-driven initiatives are so powerful. \\n\\n## Key Takeaways for Research Cyberinfrastructure \\n\\nThe pace of technological advancement is staggering\u2014tasks that once took months can now be completed in days thanks to AI, GenAI, and agent-based systems. But speed brings responsibility: security must scale with innovation. \\n\\n \\n\\nThe conference highlighted several critical areas: \\n- **Cloud cost optimization & Storage innovations**: Check out AWS Graviton5 Processors for HPC Workloads (could be a fit for those hydrological modeling workflows) and Amazon S3 Express One Zone for Research Data  (great for frequently accessed datasets with new cost savings).\\n- **Developer velocity**: Lambda Durable Functions could simplify some of your long-running pipelines, and the new AI-powered workflow design for Step Functions makes building orchestrations much faster. You can use natural language to do this, so it starts to democratize Step Function development. You don\'t need to be a developer to use it.\\n- **DevOps tooling**: CDK Pipelines v2 with AI-Assisted Development has some cool features for infrastructure-as-code that could speed up your deployment cycles.\\n- **Observability**: Amazon CloudWatch AI-Powered Anomaly Detection, especially the cost anomaly detection feature, seems like a must-have for grant-funded budgets\u2014it\'ll alert you when spending patterns deviate unexpectedly. \\n\\nThese developments reinforce CIROH\u2019s hybrid approach\u2014combining cloud scalability, collaborative computing, and on-premises HPC infrastructure-to stay ahead of the curve. \\n\\n## Learn More \\nFor deeper insights into AWS re:Invent 2025 announcements, check out these resources: \\n- [AWS News Blogs: Top annoucements of AWS re:Invent 2025](https://aws.amazon.com/blogs/aws/top-announcements-of-aws-reinvent-2025/?trk=ac97e39c-d115-4d4a-b3fe-c695e0c9a7ee&sc_channel=el)\\n\\n- [AWS Weekly Roundup: AWS re:Invent keynote recap, on-demand videos, and more](https://aws.amazon.com/blogs/aws/aws-weekly-roundup-aws-reinvent-keynote-recap-on-demand-videos-and-more-december-8-2025/)\\n\\n- [A Journey into the cloud: From an on-prem admin to an AWS enthusiast](https://alan.dbla.tech/)\\n\\n- [re:Watch: AWS re:Invent Video Library](https://myrewatch.link/)"},{"id":"software-integration-meeting","metadata":{"permalink":"/staging/main/blog/software-integration-meeting","source":"@site/blog/2025-11-24-Software-Integration-Meeting.mdx","title":"Moving Hydrologic Prediction Forward \u2014 A software integration meeting at the Alabama Water Institute","description":"A recap of a multi-institution software integration meeting at the Alabama Water Institute focused on advancing NextGen hydrologic prediction.","date":"2025-11-24T00:00:00.000Z","tags":[{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Alabama Water Institute","permalink":"/staging/main/blog/tags/alabama-water-institute"},{"inline":true,"label":"University of Calgary","permalink":"/staging/main/blog/tags/university-of-calgary"},{"inline":true,"label":"Hydrology","permalink":"/staging/main/blog/tags/hydrology"},{"inline":true,"label":"RTI","permalink":"/staging/main/blog/tags/rti"},{"inline":true,"label":"Lynker","permalink":"/staging/main/blog/tags/lynker"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NRDS","permalink":"/staging/main/blog/tags/nrds"},{"inline":true,"label":"TEEHR","permalink":"/staging/main/blog/tags/teehr"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"AWS","permalink":"/staging/main/blog/tags/aws"}],"readingTime":9.44,"hasTruncateMarker":true,"authors":[{"name":"Martyn Clark","title":"Professor of Hydrology","title2":"University of Calgary","url":"https://scholar.google.com/citations?user=xFGnDqsAAAAJ&hl=en","imageURL":"/staging/main/img/blog/authors/martyn-clark.jpeg","key":"martyn-clark","page":null},{"name":"James Halgren","title":"Assistant Director of Science","title2":"Alabama Water Institute","url":"https://github.com/jameshalgren","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U03UDT3AMST-4a6c980b793d-512","key":"james-halgren","page":null},{"name":"Matthew Denno","title":"Lead Software Developer","title2":"RTI International","url":"https://www.linkedin.com/in/matthew-denno-pe-9b9316a/","imageURL":"/staging/main/img/profiles/Matthew_Denno.jpg","key":"matt-denno","page":null},{"name":"Arpita Patel","title":"Assistant Director, IT and DevOps","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2025","page":null},{"name":"Josh Cunningham","title":"Software Engineer","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/josh-cunningham-6906a7108/","imageURL":"/staging/main/img/blog/authors/josh.jpeg","key":"josh","page":null},{"name":"Quinn Lee","title":"Programmer Analyst","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/linked--quinn/","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U072YTSNJFL-6bae7401aaac-192","key":"quinn","page":null},{"name":"Sam Lamont","title":"Lead Software Developer","title2":"RTI International","url":"https://www.linkedin.com/in/sam-lamont-3a972813/","imageURL":"/staging/main/img/blog/authors/Sam_Lamont.jpg","key":"sam-lamont","page":null},{"name":"Darri Eythorsson","title":"Postdoctoral Researcher","title2":"University of Calgary","url":"https://www.linkedin.com/in/darri-eythorsson/","imageURL":"/staging/main/img/blog/authors/darri-eythorsson.jpeg","key":"darri-eythorsson","page":null},{"name":"Cyril Thebault","title":"Postdoctoral Associate","title2":"University of Calgary","url":"https://www.linkedin.com/in/cyril-thebault/","imageURL":"/staging/main/img/blog/authors/cyril.png","key":"cyril-thebault","page":null},{"name":"Sifan A. Koriche","title":"Research [Hydrologic] Scientist","title2":"Alabama Water Institute","url":"https://github.com/skoriche","imageURL":"https://avatars.githubusercontent.com/u/71176390?s=400&u=7972b6bf562150237c77ba739972cf436a5b45c3&v=4","key":"sifan","page":null}],"frontMatter":{"title":"Moving Hydrologic Prediction Forward \u2014 A software integration meeting at the Alabama Water Institute","description":"A recap of a multi-institution software integration meeting at the Alabama Water Institute focused on advancing NextGen hydrologic prediction.","slug":"software-integration-meeting","tags":["CIROH","Blog","Alabama Water Institute","University of Calgary","Hydrology","RTI","Lynker","NextGen","NGIAB","NRDS","TEEHR","National Water Model","AWS"],"authors":["martyn-clark","james-halgren","matt-denno","arpita-2025","josh","quinn","sam-lamont","darri-eythorsson","cyril-thebault","sifan"],"image":"/img/blog/2025-11-integration-meeting/group_pic.png"},"unlisted":false,"prevItem":{"title":"AWS re:Invent 2025: Key Insights for Research and Cyberinfrastructure ","permalink":"/staging/main/blog/aws-reinvent-2025"},"nextItem":{"title":"Building Bridges: CIROH\u2013Penn State Collaboration Formalizes Differentiable Modeling for NRDS","permalink":"/staging/main/blog/ciroh-psu-collab"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-11-integration-meeting/group_pic.png\\")} alt=\\"Group photo from the software integration meeting at the Alabama Water Institute\\" style={{ maxWidth: \\"100%\\" }} />\\n</figure>\\n\\n<br />\\nLast week, at the invitation and expert coordination of James Halgren, teams from RTI\\nInternational (Sam Lamont and Matt Denno) and the University of Calgary (Darri\\nEythorsson, Cyril Thebault, and Martyn Clark) met at AWI for an intensive working session\\nfocused on weaving recent CIROH research into AWI\u2019s fork of the NOAA Office of Water\\nPrediction (OWP) Next Generation Water Resources Modeling Framework (nicknamed\\n\u201CNextGen\u201D). James took the lead in developing the agenda, lining up the right scientific and\\ntechnical expertise and ensuring that the week targeted the most critical software\\nintegration challenges. Throughout the visit, the RTI and UCalgary teams collaborated\\nclosely with AWI software engineers Quinn Lee, Josh Cunningham, hydrologic scientist Sifan A. Koriche, and James himself. The\\ndays were filled with whiteboards, deep technical conversations, and strategic planning\\naround the future of NextGen water prediction. This recap captures the key themes and\\nthe momentum that carried through the week.\\n\\n{/* truncate */}\\n\\n## Getting started\\nThe U Calgary team arrived quite late Sunday night. The plane landed around 9:30 p.m.,\\nbut with no dinner on board, the drive from Birmingham to Tuscaloosa became an\\nunexpectedly comprehensive tour of places that were neither open nor in possession of a\\nsingle vegetable. The group checked into the Indigo just before midnight, somewhat\\nhungry but otherwise intact.\\n\\nAfter Team Calgary\u2019s epic late-night journey, we kicked off early on Monday morning with\\na whiteboard session to map out the \u201Cassets\u201D we rely on for hydrologic modeling\u2014datasets,\\nmodels, tools\u2014everything from the CAMELS dataset to TOPMODEL to NOAH-OWP-Modular, plus the\\nassortment of geospatial processing and calibration methods that we all\\ndepend on. The aim was to start corralling this sprawling collection of community\\nresources into something a bit more coherent, mostly because no single group has the\\nexpertise (or the workforce) needed to tackle all the challenges of building state-of-the-art\\nprediction systems. The conversation naturally focused on software integration\u2014the\\nwhole point of the trip\u2014as we tried to figure out how to get these pieces to play nicely with\\neach other.\\n\\nA high point of the morning was meeting with our operational colleagues at the NOAA\\nOffice of Water Prediction\u2014Dr. Fred Ogden, Dr. Fernando Salas, and Dr. Jason Regina. They\\nshared updates on OWP\u2019s vision for future versions of the National Water Model and\\noutlined plans for defining model configurations and calibratng them across the national\\ndomain.\\n\\nRefueled by a terrific lunch at the Curry Kitchen, we reconvened to focus on two key\\nintegration efforts: introducing the SYMFLUENCE integration architecture for large-domain modeling\\nand enabling SUMMA\u2019s process-based simulations to run seamlessly\\nwithin the NextGen workflow.\\n\\nDarri Eythorsson walked the group through SYMFLUENCE, an integration architecture\\ndesigned to make hydrologic modeling workflows more structured and efficient,\\ndescribing how SYMFLUENCE supports everything from defining spatial domains and\\npreparing data to model setup, calibration, optimization, and evaluation. He emphasized\\nthat SYMFLUENCE can also drive simulations from NextGen, giving NextGen access to\\ncapabilities such as large-sample calibration and geospatial preprocessing. Darri noted\\nthat the system runs on laptops, HPC clusters, and cloud-compute platforms, making it\\nadaptable to modeling at different scales.\\n\\nWe closed out Monday with a deep dive into bringing SUMMA into NOAA/OWP\u2019s NextGen\\nframework. The meeting was scheduled late in the day so that Ashley van Beusekom, one\\nof SUMMA\u2019s primary developers, could join from her home in Okinawa, Japan. A couple of\\nyears ago, Ashley added BMI support to SUMMA, making it possible to run the model\\nwithin the NextGen architecture. Ahead of the meeting, she and Darri Eythorsson worked\\ntogether to set up SUMMA as a spatially distributed model in NextGen, and they\\nsuccessfully reproduced the Provo and Oyster River test cases to verify that everything was\\nrunning as intended. Quinn and Josh from AWI were excited by the results and\\nimmediately started weaving SUMMA capabilities into the broader NextGen framework.\\n\\nThe U Calgary crew wrapped up the day on the Indigo Hotel rooftop, sharing giant pretzels,\\nvegetables, and the warm Alabama night air. They toasted the momentum of the visit and\\nthe possibilities ahead. As the night settled in, Team RTI\u2019s Matt Denno and Sam Lamont\\narrived mid-evening Monday, ready to jump into the work the next morning.\\n\\n## Technical deep dives\\nThe RTI and U Calgary teams met up for breakfast on Tuesday morning at Heritage House\\nwhere they exchanged high-fives and consumed the caffeine and carbohydrates needed to\\ntackle another ambitious day of software integration.\\n\\nOnce everyone settled in at AWI, the group dug into the two main challenges of the week:\\nintegrating models into the NextGen framework (the U Calgary effort) and evaluating those\\nsimulations with shared protocols (the RTI focus). The conversation broadened as Arpita Patel (UA), Jordan Laser (Lynker), Zach Wills (Lynker), Nels Frazier (Lynker), Sifan A. Koriche (AWI), Giovanni Romero (Aquaveo), Jonathan Frame (UA), Trupesh Patel (UA), Harsha Vemula (UA) and Manjila Singh (UA) joined to discuss their work on making NextGen accessible and useful to the wider community. Together, the group reviewed progress on SYMFLUENCE,\\nthe NextGen/SUMMA integration, and the TEEHR data model. As always, James Halgren\\nkept everything running seamlessly, turning lunch into a productive working session so\\nthe team could update the University of Alabama\u2019s computer science leads on recent\\nadvances and ongoing challenges.\\n\\nBefore long, the team divided into smaller groups so they could move quickly on the most\\npressing software-integration tasks on the schedule. Throughout the day, the big question\\nhovered: How do we create a seamless pipeline from model execution data ingest\u2192\\nevaluation \u2192 model improvement?\\n\\nOn the RTI side, much of the effort focused on preparing outputs for seamless use within\\nthe TEEHR Evaluation System. This involved translating the output from NextGen\\nsimulations into the TEEHR data schema and determining how best to extract the\\nmetadata needed to track which model configuration produced each forecast. The team\\nalso worked on defining crosswalks to link simulation points to USGS gage IDs, ensuring\\nthat model results could be cleanly tied back to the appropriate metadata and hydrofabric,\\nand they began documenting key operational details such as run intervals and latency\\ncharacteristics of near-real-time runs. By the time the dust settled, the RTI and AWI teams had\\nstitched the pieces together and emerged with the gratifying sense that they had made\\ngood initial progress on the problem they came to solve.\\n\\nOn the U Calgary side, the team split off into two groups. In one corner Darri Eythorsson\\nand Cyril Thebault met with Josh Cunningham to make progress on integrating SUMMA in\\nto NextGen. There were lots of issues to consider, including appropriately linking with\\ndifferent software libraries and ensuring that SUMMA could run effectively in the\\ncontainerized NextGen instantiation \u201CNextGen In a Box\u201D (NGIAB). The software\\nintegration progress was rapid, thanks in large part to the Herculean efforts of Ashley van\\nBeusekom prior to the visit.\\n\\nIn another corner, Martyn Clark sat down with James Halgren, Quinn Lee and Sifan A. Koriche to put\\ntogether a SWOT (Strengths, Weaknesses, Opportunities, Threats) analysis for the AWI-led efforts to transition CIROH research into\\nNOAA/OWP operations. The timing mattered: James was preparing to drive to Utah the\\nfollowing week for a faculty position at Brigham Young University, and leadership of his\\ngroup was in the process of transitioning to Quinn Lee and Josh Cunningham. The SWOT\\nanalysis brought a sense of optimism and excitement as the team saw the promise in\\nrecent hydrologic prediction advances and brainstormed several clear steps to make the\\nresearch-to-operations path smoother and more effective.\\n\\nLater in the day, Arpita Patel and Matt Denno met with NOAA/OWP Chief Scientist Fred\\nOgden to walk through the latest NextGen Framework design diagram and discuss how\\ntheir development of NextGen In A Box (NGIAB) aligns with NOAA/OWP\u2019s component-based architecture.\\nTheir conversation highlighted that NGIAB already follows many of\\nthese principles, including modular components, stand-alone tools, and fully BMI-compliant model\\nexecution. They also identified clear opportunities to strengthen the\\nalignment, particularly around refining the runtime environment, enhancing component\\ndecoupling, and mapping NGIAB\u2019s architecture onto OWP\u2019s emerging design. The meeting\\nset the stage for ongoing coordination.\\n\\nDinner at the River Caf\xe9 was a highlight of the day. With a table on the terrace and the\\nBlack Warrior River drifting by below, the team enjoyed an evening of easy conversation\\nand good-natured reflection on the progress over the past two days.\\n\\n\\n## A springboard for the future\\nWednesday saw the RTI and U Calgary teams peel off in different directions. RTI paired\\nwith AWI software engineers to advance the TEEHR model evaluation manager, tightening\\nthe evaluation protocols, metadata requirements, and workflow linkages needed for\\nbasin-scale and national-scale verification. U Calgary spent the day with CIROH leadership\\n\u2014Steve Burian, Sagy Cohen, and Erin White\u2014reviewing their major research advances\\nand the steps required to improve the research-to-operations pipeline. A clear highlight of\\nthe day came when SUMMA was successfully integrated into NextGen: Martyn Clark\\nmarked the moment with a celebratory dance\u2014hands clasped, fingers interlocked, and his\\nupper body swaying with unmistakable satisfaction.\\n\\nThat evening, everyone gathered at Steve Burian\u2019s home for a farewell celebration in\\nhonor of James Halgren. Steve and his wife Cindy laid out an extraordinary taco spread,\\nenough to nourish the lively crowd that had gathered to see James off in style. James\\nbrought with him a tall stack of mounted photographs he had taken around the U.S., and\\nhe spent the night offering warm goodbyes and writing personal messages on the back of\\neach one. It was a lovely gesture, and a reminder of how much his enthusiasm and\\nkindness had meant to the community.\\n\\nThe joint visit wrapped up on Thursday morning, when the full team gathered to chart a\\npath forward. Together they mapped out the key components of the NextGen Research\\nData Stream (NRDS\u2014affectionately pronounced \u201Cnerds\u201D) and clarified how NRDS fits\\nwithin the broader NOAA/OWP NextGen framework, including the orchestration manager,\\ncalibration manager, and evaluation manager that had occupied so much attention\\nthroughout the week. The discussion concluded with a clear set of immediate priorities,\\nidentifying the specific steps needed over the next six months to realize near-term\\nsuccesses in the transition of research to operations.\\n\\n\\n## CIROH Cyberinfrastructure: Accelerating Hydrologic Research\\nThis collaborative work exemplifies how CIROH\'s cyberinfrastructure investments are accelerating the pace of hydrologic research. The platforms developed by CIROH\'s DevOps team - the Research to Operations Hydrologic Community (R2OHC) platform and tools developed by CIROH\'s Science team, Lynker team, RTI team and Aquaveo team \u2014including NextGen In A Box (NGIAB), NRDS, and containerized modeling environments\u2014provide researchers with immediate access to computational resources and standardized workflows. By eliminating the traditional barriers of infrastructure setup and configuration, these platforms allow research teams like University of Calgary, RTI International, Lynker, Aquaveo and AWI to focus their energy on scientific innovation rather than technical implementation. This meeting at AWI represents the kind of rapid, collaborative progress that becomes possible when robust cyberinfrastructure removes technical friction from the research process."},{"id":"ciroh-psu-collab","metadata":{"permalink":"/staging/main/blog/ciroh-psu-collab","source":"@site/blog/2025-10-29-AWI-PSU-Collaboration.mdx","title":"Building Bridges: CIROH\u2013Penn State Collaboration Formalizes Differentiable Modeling for NRDS","description":"Collaboration between CIROH and Penn State introduces differentiable models to the Next Generation Research Data Stream.","date":"2025-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Alabama Water Institute","permalink":"/staging/main/blog/tags/alabama-water-institute"},{"inline":true,"label":"Pennsylvania State University","permalink":"/staging/main/blog/tags/pennsylvania-state-university"},{"inline":true,"label":"Hydrology","permalink":"/staging/main/blog/tags/hydrology"},{"inline":true,"label":"Differentiable Modeling","permalink":"/staging/main/blog/tags/differentiable-modeling"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NRDS","permalink":"/staging/main/blog/tags/nrds"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"Cloud Services","permalink":"/staging/main/blog/tags/cloud-services"},{"inline":true,"label":"AI and Machine Learning","permalink":"/staging/main/blog/tags/ai-and-machine-learning"}],"readingTime":5.8,"hasTruncateMarker":true,"authors":[{"name":"Leo Lonzarich","title":"Graduate Researcher","title2":"Pennsylvania State University","url":"https://www.linkedin.com/in/leoglonz","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U075PFL5NUE-150fbf871a79-512","key":"leo","page":null},{"name":"Quinn Lee","title":"Programmer Analyst","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/linked--quinn/","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U072YTSNJFL-6bae7401aaac-192","key":"quinn","page":null},{"name":"Josh Cunningham","title":"Software Engineer","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/josh-cunningham-6906a7108/","imageURL":"/staging/main/img/blog/authors/josh.jpeg","key":"josh","page":null},{"name":"Arpita Patel","title":"Assistant Director, IT and DevOps","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2025","page":null},{"name":"James Halgren","title":"Assistant Director of Science","title2":"Alabama Water Institute","url":"https://github.com/jameshalgren","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U03UDT3AMST-4a6c980b793d-512","key":"james-halgren","page":null}],"frontMatter":{"title":"Building Bridges: CIROH\u2013Penn State Collaboration Formalizes Differentiable Modeling for NRDS","description":"Collaboration between CIROH and Penn State introduces differentiable models to the Next Generation Research Data Stream.","slug":"ciroh-psu-collab","tags":["CIROH","Blog","Alabama Water Institute","Pennsylvania State University","Hydrology","Differentiable Modeling","NextGen","NGIAB","NRDS","National Water Model","Cloud Services","AI and Machine Learning"],"authors":["leo","quinn","josh","arpita-2025","james-halgren"],"image":"/img/blog/2025-10-psu-collab/carousel-1.jpeg"},"unlisted":false,"prevItem":{"title":"Moving Hydrologic Prediction Forward \u2014 A software integration meeting at the Alabama Water Institute","permalink":"/staging/main/blog/software-integration-meeting"},"nextItem":{"title":"From Research to Impact: CIROH Science Meeting 2025 Resources and Reflections","permalink":"/staging/main/blog/science-meeting-2025"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\nimport { Carousel } from \\"react-responsive-carousel\\"\\n\\n<Carousel\\n  showThumbs={false}\\n  autoPlay={true}\\n  stopOnHover={false}\\n  useKeyboardArrows={true}\\n  emulateTouch={true}\\n  interval={3500}\\n  infiniteLoop\\n  showStatus={false}\\n  showIndicators={true}\\n  >\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-10-psu-collab/carousel-1.jpeg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Assemblage of collaborators at AWI and Penn State\\"\\n      />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-10-psu-collab/carousel-2.jpeg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Leo Lonzarich, Quinn Lee, and Arpita Patel at University of Alabama\'s Diwali event\\"\\n      />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-10-psu-collab/carousel-3.jpeg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Josh Cunningham, Quinn Lee, and Leo Lonzarich deep in a debugging session\\"\\n      />\\n  </div>\\n</Carousel>\\n<br />\\nAlmost from the start, 2025 has been a banner year in hydrologic modeling, with advancements in capabilities on both sides of the aisle of CIROH\'s research-to-operations (R2O) pipeline. \\n\\n- From the **research** skunkworks, Penn State\'s [MHPI](https://sites.google.com/view/mhpi/team) group, led by Dr. Chaopeng Shen introduced a new generation of distributed, differentiable hydrologic models spearheaded by [\u03B4HBV 2.0](https://agupubs.onlinelibrary.wiley.com/doi/10.1029/2024WR038928). Capable of high-resolution, continental-scale streamflow forecasting across the CONUS Hydrofabric, \u03B4HBV 2.0 fuses process-based modeling and machine learning to enable efficient parameter calibration and interpretable predictions at scale -- with demonstrated viability as a National Water Model 3.0 successor.\\n\\n{/* truncate */}\\n\\n- Meanwhile, from the **operations** core, CIROH\'s Science and Cyberinfrastructure team at the [Alabama Water institute (AWI)](https://awi.ua.edu), headed by Arpita Patel and James Halgren, debuted an operational pipeline composed chiefly of flagships [NextGen In a Box (NGIAB)](https://ngiab.ciroh.org) and the [Next Generation Research Datastream (NRDS)](https://hub.ciroh.org/docs/products/ngiab-ecosystem/nrds/), forming an open-source software stack powering an accessible operational implementation of NOAA\'s Next Generation National Water Model. NRDS, in particular, executes a regularly scheduled set of continental-scale, NextGen-based hydrologic forecasts on CIROH\'s cloud-based cyberinfrastructure, and is designed to be a canvas for showcasing community modeling advances as potential R2O opportunities for NextGen.\\n\\nAs destined in CIROH, these two efforts converged in early October during a week-long collaboration hosted by AWI, bringing Penn State researcher Leo Lonzarich south to Tuscaloosa, Alabama, to join in facilitating the formal introduction of differentiable models like \u03B4HBV 2.0 into the NRDS.\\n\\n{/* truncate */}\\n\\n## Keyboard Accomplishments \u{1F47E}\\n\\nDuring the visit, the CIROH Science and Cyberinfrastructure team worked with Leo to finalize the formal integration of the \u03B4HBV 2.0 model into the NextGen ecosystem. Between extensive code reviews, model refactoring, and validation runs, we verified \u03B4HBV 2.0\'s operations-ready performance through its Basic Model Interface (BMI) within the NextGen runtime, ensuring full compliance with BMI standards and alignment with previously published benchmarks. We enhanced the model to support both batch and sequential timestep simulations \u2014 the latter mirroring the runtime behavior of NextGen \u2014 while maintaining high computational efficiency and reproducibility across environments.\\n\\nOnce \u03B4HBV 2.0 was verified and tuned, we expanded the scope to broader ecosystem integration. The model was finalized on GitHub with modular configuration capabilities, daily and hourly (model coming soon) simulation modes, and confirmed compatibility with the T-route routing component. Significant performance optimizations were implemented to improve scalability across large basin networks. We added \u03B4HBV 2.0 support to the NGIAB distribution, enabling cloud-based state loading from AWS S3 (PR coming soon), and extended its reach into the [NGIAB Data Preprocess](https://github.com/CIROH-UA/NGIAB_data_preprocess) to allow on-demand generation of forcings, static catchment attributes, and model realizations for NextGen. Finally, the static catchment attributes were incorporated into the CIROH Community Hydrofabric, ensuring the model is represented and interoperable within the hydrologic framework used across the consortium.\\n\\nThe beauty of these efforts lies in the fact that \u03B4HBV 2.0 is built upon a model-agnostic, differentiable modeling framework \u2014 [\u03B4MG](https://github.com/mhpi/generic_deltamodel). Therefore, the formalization accomplished during this visit scales to all new research products and advancements made through the framework, streamlining future NGIAB and NRDS integrations and reducing development overhead across projects.\\n\\n## Beyond the Keyboard\\n\\nOut of the office, this week also offered opportunities for cross-team engagement and a deeper look into CIROH\'s computational backbone. In one such case, Leo and the team toured the **University of Alabama\'s data center**, meeting with Josh Lotfi and other members of the **Office of Information Technology (OIT)** who help manage CIROH\'s on-premises high-performance computing resources. Naturally, this included 1-on-1 time with the flashing lights and silicon of Wukong (which supports a bulk of Penn State\'s R&D) and Pantarhei HPCs. Across the board, these interactions gave valuable insight into work going on behind the scenes at AWI and about how CIROH\'s cyberinfrastructure supports researchers and partners across academia, government, and industry.\\n\\nIt is easy to see these collaborations as purely technical exchanges. However, the deep friendships that were built during this visit are at least as important, they inevitably inspire open flows of ideas, mentorship, and future synergies in service of CIROH\'s mission and the broader community.\\n\\n## Looking Forward\\n\\nWith \u03B4HBV 2.0\'s integration near completion, differentiable models will soon be running as part of CIROH\'s NRDS nightly forecasts \u2014 accessible through the NRDS Visualizer where other researchers and community members will be able to explore, assess, and iterate on simulations from this latest crop of hydrologic models in real time.\\n\\nWe anticipate continuing this AWI-Penn State collaboration, with future projects e.g., being additions to NGIAB and NRDS including more differentiable models, a formal hourly \u03B4HBV 2.0 model, and differentiable routing. Some of this work may also arrive in a DevCon to showcase the efforts of both of groups.\\n\\nOverall, this visit exemplifies how CIROH\'s approach to developing a community of practice catalyzes scientific advancements, fosters lasting inter-institutional relationships, and makes normally lab-bound research products salient to the broader R2O community. In these collaborations, CIROH\'s core mission, strengthening the link between scientific discovery and operational forecasting, remains clear and in view.\\n\\nMany thanks are owed to Arpita, James, and the whole of CIROH\'s Science and Cyberinfrastructure team -- `git merge` on research products has never been easier.\\n\\n### Resources for the Curious \\n\\n- [\u03B4HBV 2.0 Operational Model Repository](https://github.com/mhpi/dhbv2)\\n\\n- [\u03B4MG Differentiable Modeling Framework](https://github.com/mhpi/generic_deltamodel) (Backbone for \u03B4HBV 2.0; includes documentation and tutorials for building custom differentiable hydrologic models.)\\n\\n- [MHPI Codebase](https://mhpi.github.io/codes/)\\n\\n### Publication\\n\\n<ol>\\n    <li>Song, Y., Bindas, T., Shen, C., Ji, H., Knoben, W. J. M., Lonzarich, L., et al. (2025). High-resolution national-scale water modeling is enhanced by multiscale differentiable physics-informed machine learning. Water Resources Research, 61, e2024WR038928. https://doi.org/10.1029/2024WR038928</li>\\n</ol>"},{"id":"science-meeting-2025","metadata":{"permalink":"/staging/main/blog/science-meeting-2025","source":"@site/blog/2025-09-26-Ciroh-Science-Meeting.mdx","title":"From Research to Impact: CIROH Science Meeting 2025 Resources and Reflections","description":"Best CIROH Science Meeting Yet! Reflecting on the 2025 CIROH Science Meeting held September 15-18 in Tuscaloosa, Alabama. Access meeting resources, session recordings, and presentation slides while we celebrate four days of collaborative water science research and community building.","date":"2025-09-26T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Conferences","permalink":"/staging/main/blog/tags/conferences"}],"readingTime":3.17,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null},{"name":"Charity McCalpin","title":"Research Project Coordinator","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/charity-mccalpin/","imageURL":"/staging/main/img/blog/authors/charity.jpeg","key":"charity","page":null}],"frontMatter":{"title":"From Research to Impact: CIROH Science Meeting 2025 Resources and Reflections","description":"Best CIROH Science Meeting Yet! Reflecting on the 2025 CIROH Science Meeting held September 15-18 in Tuscaloosa, Alabama. Access meeting resources, session recordings, and presentation slides while we celebrate four days of collaborative water science research and community building.","slug":"science-meeting-2025","tags":["Blog","CIROH","Conferences"],"authors":["arpita-2023","charity"],"image":"/img/blog/2025-09-science-meeting/group.jpg"},"unlisted":false,"prevItem":{"title":"Building Bridges: CIROH\u2013Penn State Collaboration Formalizes Differentiable Modeling for NRDS","permalink":"/staging/main/blog/ciroh-psu-collab"},"nextItem":{"title":"Focusing on Streamflow Data: New Software for Camera-Based Hydrologic Modeling","permalink":"/staging/main/blog/streamflow-data-camera-based-hydrologic-modeling-software"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\nimport { Carousel } from \\"react-responsive-carousel\\"\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-09-science-meeting/group.jpg\\")} alt=\\"Group photo from the CIROH science meeting\\" style={{ maxWidth: \\"100%\\" }} />\\n  <figcaption><em>Group photo from the CIROH science meeting</em></figcaption>\\n</figure>\\n\\n\\n## Meeting Highlights: Transforming Research into Real-World Impact\\n\\nOver four days, our community showed how scientific innovation translates into tools and systems that support communities, enhance resilience, and improve decision-making across the nation. From AI advances in water prediction to flood inundation mapping, the presentations and discussions demonstrated the collaborative, open-science approach that defines CIROH.\\n\\n<Carousel\\n  showThumbs={false}\\n  autoPlay={true}\\n  stopOnHover={false}\\n  useKeyboardArrows={true}\\n  emulateTouch={true}\\n  interval={3500}\\n  infiniteLoop\\n  showStatus={false}\\n  showIndicators={true}\\n  >\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-09-science-meeting/carousel_1.JPG\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Dr. Steve Burian presenting at the CIROH science meeting\\"\\n      />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-09-science-meeting/carousel_2.JPG\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Matt Womble presenting at the CIROH science meeting\\"\\n      />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-09-science-meeting/carousel_3.JPG\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"Dr. Jim Nelson presenting at the CIROH science meeting\\"\\n    />\\n  </div>\\n   <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-09-science-meeting/carousel_4.jpeg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"2025 CIROH Science Meeting Trivia Session\\"\\n    />\\n  </div>\\n</Carousel>\\n\\n{/* truncate */}\\n\\n## Access Meeting Resources\\n\\nWe are excited to share a comprehensive collection of assets from the 2025 CIROH Science Meeting, including session recordings, presentation slides, and group photos! Whether you attended in person, joined virtually, or could not participate, these materials are available to you.\\n\\n### \u{1F517} **[Access the Shared Drive](https://drive.google.com/drive/folders/1xHsyHXXprXfwJTPsezk45R0GYQBzQ-qn)**\\n\\nPlease note that materials are being uploaded continuously as we receive images and additional files from presenters and participants. We encourage you to check back periodically for updates. If you are a presenter and prefer not to have your slides or poster included in the shared drive, please contact Charity McCalpin (cnmccalpin@ua.edu) for removal.\\n\\n### \u{1F310} Visit the Event Microsite\\n\\nExplore the agenda, highlights, and media on the CIROH Science Meeting site.\\n\\n\u{1F449} **[Ciroh Science Meeting](https://cirohsciencemeeting.my.canva.site/)**\\n\\n## Your Feedback Matters\\n\\n### \u{1F4DD} **Complete Our Post-Event Survey**\\n\\nIf you attended the meeting, either in person or virtually, we kindly ask that you complete our post-event survey. Your feedback is invaluable in helping us improve future meetings and ensure they continue to serve our community\'s needs effectively.\\n\\n\u{1F449} **[Complete the Post-Event Survey](https://app.smartsheet.com/b/form/019952b37f2b717283879bd01f8da300)**\\n\\n## Looking Forward: Building on Our Collaborative Foundation\\n\\nThe 2025 Science Meeting reinforced CIROH\'s commitment to building a collaborative, open-science community that transforms research into real-world impact. The connections made and innovations shared during these four days will continue to drive our mission forward throughout the year.\\n\\n## Thank You\\n\\nThank you for your ongoing support and participation in making the 2025 CIROH Science Meeting a tremendous success. Your commitment to advancing water science and translating research into operational tools that benefit communities nationwide is what makes CIROH\'s mission possible.\\n\\nTogether, we continue building a future where scientific innovation directly serves society\'s water-related challenges and opportunities.\\n\\n---\\n\\n*The CIROH Science Meeting 2025 was held September 15-18 in Tuscaloosa, Alabama. For more information about future meetings and CIROH initiatives, visit our website (https://ciroh.ua.edu/) and stay connected with our community.*"},{"id":"streamflow-data-camera-based-hydrologic-modeling-software","metadata":{"permalink":"/staging/main/blog/streamflow-data-camera-based-hydrologic-modeling-software","source":"@site/blog/2025-09-24-Camera-Based-Hydrologic-Modeling-Software.mdx","title":"Focusing on Streamflow Data: New Software for Camera-Based Hydrologic Modeling","description":"New open-source software tools enable scalable, automated camera-based streamflow monitoring using low-cost field computers and cloud computing services.","date":"2025-09-24T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Serverless Compute","permalink":"/staging/main/blog/tags/serverless-compute"},{"inline":true,"label":"Hydrologic Monitoring","permalink":"/staging/main/blog/tags/hydrologic-monitoring"},{"inline":true,"label":"Streamflow","permalink":"/staging/main/blog/tags/streamflow"},{"inline":true,"label":"Gage","permalink":"/staging/main/blog/tags/gage"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"USGS","permalink":"/staging/main/blog/tags/usgs"},{"inline":true,"label":"HydrocamCompute","permalink":"/staging/main/blog/tags/hydrocam-compute"},{"inline":true,"label":"HydrocamCollect","permalink":"/staging/main/blog/tags/hydrocam-collect"},{"inline":true,"label":"Camera-Based Monitoring","permalink":"/staging/main/blog/tags/camera-based-monitoring"},{"inline":true,"label":"Computer Vision","permalink":"/staging/main/blog/tags/computer-vision"},{"inline":true,"label":"Utah State University","permalink":"/staging/main/blog/tags/utah-state-university"}],"readingTime":4.36,"hasTruncateMarker":true,"authors":[{"name":"Sajan Neupane","title":"Graduate Research Assistant","title2":"Utah State University","url":"https://www.linkedin.com/in/sajan-neupane10/","imageURL":"/staging/main/img/blog/authors/sajan.jpeg","key":"sajan","page":null},{"name":"Razin Bin Issa","title":"Graduate Research Assistant","title2":"Utah State University","url":"https://www.linkedin.com/in/razin-bin-issa/","imageURL":"/staging/main/img/blog/authors/razin.jpeg","key":"razin","page":null},{"name":"Safran Khan","title":"Graduate Research Assistant","title2":"Utah State University","url":"https://www.linkedin.com/in/engr-safran-khan-b35866154/","imageURL":"/staging/main/img/blog/authors/safran.jpeg","key":"safran","page":null},{"name":"Sierra Young","title":"Assistant Professor","title2":"Utah State University","url":"https://www.linkedin.com/in/sierrayoung/","imageURL":"/staging/main/img/blog/authors/sierra.jpeg","key":"sierra","page":null},{"name":"Jeffery S. Horsburgh","title":"Professor","title2":"Utah State University","url":"https://www.linkedin.com/in/jeffery-horsburgh-aa1760b3/","imageURL":"/staging/main/img/blog/authors/jeffery.jpg","key":"jeffery","page":null}],"frontMatter":{"title":"Focusing on Streamflow Data: New Software for Camera-Based Hydrologic Modeling","description":"New open-source software tools enable scalable, automated camera-based streamflow monitoring using low-cost field computers and cloud computing services.","slug":"streamflow-data-camera-based-hydrologic-modeling-software","tags":["Blog","Serverless Compute","Hydrologic Monitoring","Streamflow","Gage","CIROH","USGS","HydrocamCompute","HydrocamCollect","Camera-Based Monitoring","Computer Vision","Utah State University"],"authors":["sajan","razin","safran","sierra","jeffery"],"image":"/img/blog/2025-09-camera-based-hydrologic-modeling/segmented_image.png"},"unlisted":false,"prevItem":{"title":"From Research to Impact: CIROH Science Meeting 2025 Resources and Reflections","permalink":"/staging/main/blog/science-meeting-2025"},"nextItem":{"title":"Evaluating NextGen\u2019s Performance in the MARFC Region with NGIAB","permalink":"/staging/main/blog/nextgen-marfc-performance"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\n\\n\\nReliable and high-resolution streamflow data are essential for hydrologic research, flood forecasting, and water resource management. Streamflow gages provide necessary measurements but can be difficult and expensive to build and operate. Camera-based monitoring offers a promising, non-contact alternative to or augmentation of traditional streamflow gages. However, broad use of camera-based streamflow monitoring has been limited by operational challenges including how to collect, store, manage, and process the large volume of image and video data produced by monitoring cameras. \\n\\nWith help from Arpita Patel and the CIROH Cyberinfrastructure and DevOps Team, who assisted our team with access to [Amazon Web Services and the Google Cloud Platform](https://hub.ciroh.org/docs/services/cloudservices/), we developed and tested new cyberinfrastructure that advances camera-based hydrologic monitoring. \\n\\nTraditional dataloggers used in hydrologic monitoring focus on interfacing with conventional sensors (e.g., pressure transducers, float gages, etc.) and lack some capabilities required for camera-based monitoring. Low-cost field computers like the [Raspberry Pi](https://www.raspberrypi.com/) provide a capable alternative, but lack out-of-the-box software required to support high-resolution image and video capture, management of the large volume of data that accumulates, data processing, and cloud uploading processes. Because of this, we had to build the functionality required to combine low-cost field computers with cloud computing services to produce an operational, real-time, cloud-integrated, camera-based streamflow monitoring system.\\n\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-09-camera-based-hydrologic-modeling/segmented_image.png\\")} alt=\\"Segmented images by the Hydrocamcompute software\\" style={{ maxWidth: \\"100%\\" }} />\\n  <figcaption><em>Figure 1. Segmented images showing pixels identified as water by the HydrocamCompute software. Quantifying water pixels within the rectangular areas of interest provide an estimate of stream stage and related discharge.</em></figcaption>\\n</figure>\\n\\n{/* truncate */}\\n\\nWe developed two new Python-based software programs compatible with inexpensive field computers such as Raspberry Pi: one that captures and processes the data from cameras, and one that automatically extracts hydrologically relevant data from image data in the cloud.\\n\\n1. **Hydrocam Collect**: automatically captures images and videos at user-specified intervals, manages local storage on field computers, and uploads captured image and video data to the cloud. Real-time data monitoring and alerts minimize potential for data loss.\\n2. **Hydrocam Compute**: This serverless cloud computing workflow extracts relevant hydrologic data from camera images and videos, such as depth/stage and velocity. Automated and scalable, the workflow can handle a large number of independent monitoring sites, each executing their own serverless functions using isolated cloud resources.\\n\\nIn an operational context, automation is key to a scalable, robust system capable of integrating camera-based monitoring with larger hydrologic monitoring networks such as those managed by the United States Geological Survey (USGS). We tested the automation of the system we developed using commercial cloud services via Amazon Web Services and Google Cloud Platform with access provided through CIROH. By leveraging CIROH-provided cloud services, our team was able to prototype, test, and scale the software to bridge the gap between proof-of-concept research and practical field use.\\n \\nThis linked software system we developed responds to data events (i.e., capture and upload of an image or video to the cloud) instantly and minimizes human intervention and error correction. The serverless and event driven design of Hydrocam Compute reduces infrastructure management overhead and cost because cloud resources are only used during execution of data processing tasks with no need to manage or maintain physical compute infrastructure. The models used for processing images and video can be swapped out to meet the needs of particular monitoring locations.\\n \\nThe Hydrocam workflows enhance the feasibility, reliability, and efficiency of camera-based streamflow monitoring. As hydrological conditions become more variable, access to high-resolution, real-time data becomes increasingly important for flood forecasting, water resource management, and long-term climate adaptation strategies. This work supports these broader goals in making camera-based monitoring more practical and scalable.\\n \\n---\\n\\n## Resources and Publications\\n\\n### Open Source Software\\n\\nThe [HydrocamCollect](https://github.com/hydrocam/collector) and [HydrocamCompute](https://github.com/hydrocam/serverlesscompute) software programs are available in GitHub repositories within the [hydrocam GitHub Organization](https://github.com/hydrocam).\\n\\n### Publications\\n\\nAccess the pre-prints of papers related to the Hydrocam software and camera-based monitoring:\\n<ol>\\n    <li>Neupane, S., Horsburgh, J. S., Bin Issa, R., Young, S. (2025). HydrocamCollect: A robust data acquisition and cloud data transfer workflow for camera-based hydrological monitoring. <i>Environmental Modelling & Software</i> (submitted). Available at SSRN: https://ssrn.com/abstract=5451102 or https://doi.org/10.2139/ssrn.5451102 </li>\\n\\n    <li>Neupane, S., Horsburgh, J. S., Bin Issa, R., Young, S. (2025). HydrocamCompute: Serverless cloud computing workflow for camera-based hydrological monitoring. <i>Environmental Modelling & Software</i> (submitted). Available at SSRN: https://ssrn.com/abstract=5451100 or https://doi.org/10.2139/ssrn.5451100  </li>\\n\\n    <li>Bin Issa, R., Neupane, S., Khan, S., Horsburgh, J. S., Young, S. (2025). Towards Real-Time Water Level and Discharge Measurements using Imagery, Machine Learning, and Edge Computing. <i>Journal of Hydrology</i> (submitted). Available at SSRN: https://ssrn.com/abstract=5531964 or https://doi.org/10.2139/ssrn.5531964 </li>\\n</ol>\\n\\n## Contact\\n<ul>\\n<li>Dr. Sierra Young, Utah State University, sierra.young@usu.edu</li>\\n<li>Dr. Jeff Horsburgh, Utah State University, jeff.horsburgh@usu.edu</li>\\n</ul>"},{"id":"nextgen-marfc-performance","metadata":{"permalink":"/staging/main/blog/nextgen-marfc-performance","source":"@site/blog/2025-08-29-MARFC-Blog-Post.mdx","title":"Evaluating NextGen\u2019s Performance in the MARFC Region with NGIAB","description":"A case study on using NextGen in a Box (NGIAB) to assess the NextGen Hydro Framework in the Middle Atlantic River Forecast Center (MARFC) region, comparing its performance with CHPS and NWM 3.0.","date":"2025-08-29T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"MARFC","permalink":"/staging/main/blog/tags/marfc"},{"inline":true,"label":"Hydrology","permalink":"/staging/main/blog/tags/hydrology"},{"inline":true,"label":"Modeling","permalink":"/staging/main/blog/tags/modeling"},{"inline":true,"label":"NOAA","permalink":"/staging/main/blog/tags/noaa"},{"inline":true,"label":"NWM","permalink":"/staging/main/blog/tags/nwm"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"CHPS","permalink":"/staging/main/blog/tags/chps"},{"inline":true,"label":"JetStream2","permalink":"/staging/main/blog/tags/jet-stream-2"}],"readingTime":6.04,"hasTruncateMarker":true,"authors":[{"name":"Hudson Finley Davis","title":"Hydrologist","title2":"NOAA Office of Water Prediction","url":"mailto:hudson.davis@noaa.gov","imageURL":"/staging/main/img/blog/authors/hudson.jpeg","key":"hudson","page":null},{"name":"Seann Reed","title":"Hydrologist","title2":"NOAA Office of Water Prediction","url":"mailto:seann.reed@noaa.gov","imageURL":"/staging/main/img/blog/authors/seann.png","key":"seann","page":null},{"name":"Josh Cunningham","title":"Software Engineer","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/josh-cunningham-6906a7108/","imageURL":"/staging/main/img/blog/authors/josh.jpeg","key":"josh","page":null},{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null},{"name":"James Halgren","title":"Assistant Director of Science","title2":"Alabama Water Institute","url":"https://github.com/jameshalgren","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U03UDT3AMST-4a6c980b793d-512","key":"james-halgren","page":null},{"name":"Sifan A. Koriche","title":"Research [Hydrologic] Scientist","title2":"Alabama Water Institute","url":"https://github.com/skoriche","imageURL":"https://avatars.githubusercontent.com/u/71176390?s=400&u=7972b6bf562150237c77ba739972cf436a5b45c3&v=4","key":"sifan","page":null},{"name":"Trupesh Patel","title":"Research Software Engineer","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/trupeshkumarpatel","imageURL":"/staging/main/img/profiles/Trupesh_Patel.png","key":"trupesh","page":null}],"frontMatter":{"title":"Evaluating NextGen\u2019s Performance in the MARFC Region with NGIAB","description":"A case study on using NextGen in a Box (NGIAB) to assess the NextGen Hydro Framework in the Middle Atlantic River Forecast Center (MARFC) region, comparing its performance with CHPS and NWM 3.0.","slug":"nextgen-marfc-performance","authors":["hudson","seann","josh","arpita-2023","james-halgren","sifan","trupesh"],"tags":["Blog","NGIAB","MARFC","Hydrology","Modeling","NOAA","NWM","NextGen","CHPS","JetStream2"],"image":"img/blog/2025-08-MARFC/fig4.png"},"unlisted":false,"prevItem":{"title":"Focusing on Streamflow Data: New Software for Camera-Based Hydrologic Modeling","permalink":"/staging/main/blog/streamflow-data-camera-based-hydrologic-modeling-software"},"nextItem":{"title":"Cross-Institutional Collaboration Enhances Hydrologic Modeling in the Logan River Watershed","permalink":"/staging/main/blog/logan-river-collaboration"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\n<div className=\\"margin-bottom--lg\\" />\\n\\nThe National Weather Service\'s Middle Atlantic River Forecast Center (MARFC) sees large variations in the performance of the National Water Model 3.0. Through its support for regionalized parameters and models, NOAA-OWP\u2019s Next Generation Water Resources Modeling Framework (NextGen framework) offers a potential solution to address these inconsistencies. As such, this study took advantage of NextGen in a Box (NGIAB) to evaluate the NextGen framework\u2019s performance in the MARFC region.\\n\\nThis study evaluated three operational hydrologic modeling frameworks targetted at the National Water Model (NWM): the Community Hydrologic Prediction System (CHPS), the NextGen framework, and version 3.0 of the National Water Model itself.\\n- CHPS is the current operational framework used by NOAA\'s River Forecast Centers. It incorporates the SNOW-17 model for snowmelt and the Sacramento Soil Moisture Accounting (SAC-SMA) model for runoff generation.\\n- For the early phases of this study, the NextGen framework was used with the default model configuration provided by the NGIAB ecosystem, which combines the Noah-OWP-Modular land surface model and the Conceptual Functional Equivalent (CFE) rainfall runoff model [[2]](/blog/nextgen-marfc-performance#references).\\n  - After initial runs with the baseline configuration, Noah-OWP-Modular was replaced with SNOW-17 output and simplified Potential Evapotranspiration (PET) values from the MARFC database.\\n  - The models were calibrated using two objective functions: Kling-Gupta Efficiency (KGE) [[6][7]](/blog/nextgen-marfc-performance#references) and Nash-Sutcliffe Efficiency (NSE) [[4][5]](/blog/nextgen-marfc-performance#references).\\n- The National Water Model 3.0 uses the Noah-MP land surface model coupled with the Weather Research and Forecasting Hydrologic model (WRF-Hydro) [[2][3]](/blog/nextgen-marfc-performance#references) to simulate hydrological processes across CONUS. \\n\\nThe case studies focused on the Westfield and Elkland basins in North-Central Pennsylvania.\\nThese basins provide good locations for comparison due to the presence of USGS stream gages\\nand their \\"flashy\\" behavior, characterized by rapid and unpredictable rises and falls in streamflow.\\nAdditionally, both Westfield and Elkland were sites of catastrophic flooding during Tropical Storm Debby in 2024,\\nwhich allowed for the models to be evaluated on a recent extreme flood event. Results from Westfield, PA are shown in Figure 1.\\n\\n<figure style={{ textAlign:\'center\', margin:\'1.5rem 0\' }}>\\n  <img\\n    src={useBaseUrl(\\"/img/blog/2025-08-MARFC/fig1.png\\")}\\n    alt=\\"A bar graph titled \'Westfield, PA Nash-Sutcliffe Efficiency values\'. SAC-SMA displayed the best performance, closely followed by SAC-SMA Uncalibrated and NGen Calibrated (NSE OFunc). NGen Calibrated (KGE OFunc) fell slightly further behind, while NGEN Uncalibrated was by far the lowest.\\"\\n    style={{ maxWidth:\'100%\', height:\'auto\' }}\\n  />\\n  <figcaption style={{ fontSize:\'0.95rem\', lineHeight:1.6, marginTop:\'0.6rem\', opacity:0.9 }}>\\n    **Figure 1**) Nash-Sutcliffe Efficiency (NSE) Metric for simulations from 2007 to 2020.\\n  </figcaption>\\n</figure>\\n\\n{/* truncate */}\\n\\nThe simulations executed for the case study are listed below:\\n\\n- **Uncalibrated CHPS**\\n- **Calibrated CHPS**\\n- **Uncalibrated NextGen** (AORC forcings)\\n- **Uncalibrated NextGen** (MARFC forcings)\\n- **Calibrated NextGen** (AORC forcings; calibrated on KGE objective function)\\n- **Calibrated NextGen** (AORC forcings; calibrated on NSE objective function)\\n- **Calibrated NextGen** (MARFC forcings; calibrated on KGE objective function)\\n- **National Water Model 3.0**\\n\\nThese simulations were executed on the [JetStream2](/docs/services/external-resources/nsf-access/jetstream) platform with the support of the CIROH Research Cyberinfrastructure Team.\\n\\n<figure style={{ textAlign:\'center\', margin:\'1.5rem 0\' }}>\\n  <div style={{ display:\'flex\', maxWidth:\'100%\' }}>\\n    <img\\n      src={useBaseUrl(\\"/img/blog/2025-08-MARFC/fig2_1.png\\")}\\n      alt=\\"A bar graph titled \'NSE of NextGen vs NextGen with Forcings Change\'. The version of NextGen that used MARFC forcings yielded a greater NSE value.\\"\\n      style={{ maxWidth:\'50%\', height:\'auto\' }}\\n    />\\n    <img\\n      src={useBaseUrl(\\"/img/blog/2025-08-MARFC/fig2_2.png\\")}\\n      alt=\\"A bar graph titled \'PBIAS of NextGen vs NextGen with Forcings Change\'. While both PBIAS values were negative, the version of NextGen that used MARFC forcings showed far lower PBIAS.\\"\\n      style={{ maxWidth:\'50%\', height:\'auto\' }}\\n    />\\n  </div>\\n  <figcaption style={{ fontSize:\'0.95rem\', lineHeight:1.6, marginTop:\'0.6rem\', opacity:0.9 }}>\\n    **Figure 2**)  Percent Bias and NSE of simulations from 2007 to 2020 generated with different forcings - AORC (referred as NextGen) and MARFC Hourly Operational Grids (referred as NextGen FC).\\n  </figcaption>\\n</figure>\\n\\nThe researchers observed that the calibrated runs for both NextGen and CHPS showed significant improvements over uncalibrated runs in both Westfield and Elkland basins. Among the calibrated runs, CHPS marginally outperformed NextGen. Additionally, both CHPS and NextGen outperformed NWM 3.0 in Westfield basin.\\n\\nWhen running the NextGen-based models, substitution of SNOW-17 output and simpler PET for the NOAH-OWP reduced calibration time by 50% and produced similar outputs.\\n\\nHowever, the models that performed best during calibration did not necessarily perform best during the Hurricane Debby extreme event. This suggests that including a greater number of extreme events in the calibration period is necessary to improve model robustness.\\n\\n<figure style={{ textAlign:\'center\', margin:\'1.5rem 0\' }}>\\n  <img\\n    src={useBaseUrl(\\"/img/blog/2025-08-MARFC/fig3.png\\")}\\n    alt=\\"A hydrograph depicting streamflow observations and outputs for Tropical Storm Debby on 08/09/2024.\\"\\n    style={{ maxWidth:\'100%\', height:\'auto\' }}\\n  />\\n  <figcaption style={{ fontSize:\'0.95rem\', lineHeight:1.6, marginTop:\'0.6rem\', opacity:0.9 }}>\\n    **Figure 3**) Hydrograph of Tropical Storm Debby on 08/09/2024. It is important to note that the observed data, denoted by black dots, cuts out halfway through the hydrograph. For this window, peak flow was estimated by the USGS to be just under 20,000 cfs, which is nearly double the second largest event on record.\\n  </figcaption>\\n</figure>\\n\\nNGIAB served as a critical enabler in this study, allowing for rapid iteration and in-depth exploration of the NextGen framework\u2019s configuration space. This evaluation of objective functions, forcing datasets, and baseline models would have been significantly more challenging with traditional workflows.\\n\\n> *The presentation and output data for this study have been made [available on Hydroshare](https://www.hydroshare.org/resource/4b1be922057a43c7aa001050d7964a20/).*\\n\\n---\\n\\n## References\\n\\n<ol>\\n  <li>National Oceanic and Atmospheric Administration. <em>Community Hydrologic Prediction System (CHPS) Documentation</em> [Internet]. National Oceanic and Atmospheric Administration; [updated 2024 Nov 26; cited 2025 Jul 28]. Available from: [https://vlab.noaa.gov/web/chps](https://vlab.noaa.gov/web/chps) </li>\\n\\n  <li>Araki R, Ogden FL, McMillan HK. Testing Soil Moisture Performance Measures in the Conceptual\u2010Functional Equivalent to the WRF-Hydro National Water Model. <em>JAWRA Journal of the American Water Resources Association</em>. 2025 Feb;61(1):e70002.</li>\\n\\n  <li>National Oceanic and Atmospheric Administration. <em>The National Water Model</em> [Internet]. National Water Prediction Service; [cited 2025 Jul 29]. Available from: [https://water.noaa.gov/about/nwm](https://water.noaa.gov/about/nwm) </li>\\n\\n  <li>Tijerina\u2010Kreuzer D, Condon L, FitzGerald K, Dugger A, O\u2019Neill MM, Sampson K, Gochis D, Maxwell R. Continental hydrologic intercomparison project, phase 1: A large\u2010scale hydrologic model comparison over the continental United States. <em>Water Resources Research</em>. 2021 Jul;57(7):e2020WR028931.</li>\\n\\n  <li>Moriasi DN, Arnold JG, Van Liew MW, Bingner RL, Harmel RD, Veith TL. Model evaluation guidelines for systematic quantification of accuracy in watershed simulations. <em>Transactions of the ASABE</em>. 2007;50(3):885-900.</li>\\n\\n  <li>Gupta HV, Kling H, Yilmaz KK, Martinez GF. Decomposition of the mean squared error and NSE performance criteria: Implications for improving hydrological modelling. <em>Journal of Hydrology</em>. 2009 Oct 20;377(1-2):80-91.</li>\\n\\n  <li>Vrugt JA, de Oliveira DY. Confidence intervals of the Kling-Gupta efficiency. <em>Journal of Hydrology</em>. 2022 Sep 1;612:127968.</li>\\n</ol>"},{"id":"logan-river-collaboration","metadata":{"permalink":"/staging/main/blog/logan-river-collaboration","source":"@site/blog/2025-08-29-USU-Logan-River-Collaboration.mdx","title":"Cross-Institutional Collaboration Enhances Hydrologic Modeling in the Logan River Watershed","description":"A joint effort by CIROH (University of Alabama) and Utah State University","date":"2025-08-29T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Hydrology","permalink":"/staging/main/blog/tags/hydrology"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"T-Route","permalink":"/staging/main/blog/tags/t-route"},{"inline":true,"label":"Logan River","permalink":"/staging/main/blog/tags/logan-river"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"USU","permalink":"/staging/main/blog/tags/usu"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"}],"readingTime":2.13,"hasTruncateMarker":true,"authors":[{"name":"Bhavya Duvuri","title":"Machine Learning Researcher","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/duvvuribhavya/","imageURL":"/staging/main/img/blog/authors/bhavya.jpeg","key":"bhavya","page":null},{"name":"Ayman Nassar","title":"Postdoctoral Researcher","title2":"Utah State University","url":"https://www.linkedin.com/in/ayman-nassar-24a92723/","imageURL":"/staging/main/img/blog/authors/ayman_nassar.png","key":"ayman","page":null},{"name":"James Halgren","title":"Assistant Director of Science","title2":"Alabama Water Institute","url":"https://github.com/jameshalgren","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U03UDT3AMST-4a6c980b793d-512","key":"james-halgren","page":null},{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null},{"name":"Josh Cunningham","title":"Software Engineer","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/josh-cunningham-6906a7108/","imageURL":"/staging/main/img/blog/authors/josh.jpeg","key":"josh","page":null},{"name":"David Tarboton","title":"Professor","title2":"Utah Water Research Laboratory","url":"https://www.linkedin.com/in/dtarb/","imageURL":"/staging/main/img/blog/authors/david_tarboton.jpg","key":"david","page":null}],"frontMatter":{"title":"Cross-Institutional Collaboration Enhances Hydrologic Modeling in the Logan River Watershed","description":"A joint effort by CIROH (University of Alabama) and Utah State University","slug":"logan-river-collaboration","tags":["Blog","Hydrology","NextGen","T-Route","Logan River","CIROH","USU","NGIAB"],"authors":["bhavya","ayman","james-halgren","arpita-2023","josh","david"],"image":"img/blog/2025-08-Logan-River/fig1.png"},"unlisted":false,"prevItem":{"title":"Evaluating NextGen\u2019s Performance in the MARFC Region with NGIAB","permalink":"/staging/main/blog/nextgen-marfc-performance"},"nextItem":{"title":"NGIAB Reaches 10,000 Docker Pulls: NextGen In A Box Makes Water Modeling More Accessible","permalink":"/staging/main/blog/ngiab-10k"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\n<figure style={{ textAlign: \\"center\\" }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-08-Logan-River/fig1.png\\")} alt=\\"A before-and-after comparison of the corrected catchment for the Logan River. Text: \'Correcting hydrofabric by removing catchments that do not drain into gauge\'\\" style={{ maxWidth: \\"100%\\" }} />\\n  <figcaption><em>Figure 1. A corrected reach arising from the UA-USU collaboration.</em></figcaption>\\n</figure>\\n\\n\\nRecent collaboration between researchers in the Cooperative Institute for Research to Operations in Hydrology (CIROH) from University of Alabama (UA) and Utah State University (USU) highlighted the value of cross-institutional partnerships in improving community hydrologic modeling. Focused on the Logan River watershed, this joint effort demonstrated how sharing tools, knowledge, and infrastructure can accelerate both model development and scientific discovery.\\n\\nThrough this engagement, USU researchers gained deeper understanding of the NextGen framework and T-Route modeling library, empowering them to improve physical process representations for the Logan River watershed for heightened simulation fidelity. The collaboration also provided valuable exposure to the developmental side of complex modeling tools, offering insights into framework design, automation workflows, and best practices for model setup and calibration. Both teams benefited from exposure to alternative research tools and methods, which helped enhance and refine the community development pipeline.\\n\\n{/* truncate */}\\n\\nOne key outcome was the correction of a spatial representation in the Logan River hydrofabric (Figure 1) using the USU\u2019s specific local knowledge. The reach for this region (highlighted in the zoomed subfigure) was updated to reflect its real world path, where it flows into an underwater tunnel that reconnects to Logan River further downstream. This correction will be integrated into the community hydrofabric, benefiting the wider community by improving model realism and reliability. Furthermore, in combination with freshly calibrated model parameters, these updates have improved the model\'s KGE metric by **0.2 units** \u2014 a significant gain in model accuracy.\\n\\nNGIAB played a central role in this success, streamlining the process of setting up, running, and analyzing multiple model configurations. By removing the typical installation and troubleshooting barriers, researchers could focus their time on advancing physical representations rather than infrastructure issues.\\n\\nThis collaboration sets a precedent for how community-driven, open science efforts can improve hydrologic model performance and usability. By combining localized knowledge with shared national tools, we move closer to creating reliable, reusable, and scalable flood forecasting systems, a crucial step for Research-to-Operations (R2O) success.\\n\\nWe look forward to repeating this model of collaboration with other regional experts and academic institutions to continually refine the National Water Model ecosystem and its supporting frameworks."},{"id":"ngiab-10k","metadata":{"permalink":"/staging/main/blog/ngiab-10k","source":"@site/blog/2025-08-01-NGIAB-10k.mdx","title":"NGIAB Reaches 10,000 Docker Pulls: NextGen In A Box Makes Water Modeling More Accessible","description":"NextGen In A Box (NGIAB) surpasses 10,000 Docker pulls, highlighting growing global adoption of accessible, containerized water modeling tools.","date":"2025-08-01T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Containerization","permalink":"/staging/main/blog/tags/containerization"},{"inline":true,"label":"Water Modeling","permalink":"/staging/main/blog/tags/water-modeling"},{"inline":true,"label":"Docker","permalink":"/staging/main/blog/tags/docker"},{"inline":true,"label":"Hydrology","permalink":"/staging/main/blog/tags/hydrology"},{"inline":true,"label":"Education","permalink":"/staging/main/blog/tags/education"},{"inline":true,"label":"Community Impact","permalink":"/staging/main/blog/tags/community-impact"}],"readingTime":3.24,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"NGIAB Reaches 10,000 Docker Pulls: NextGen In A Box Makes Water Modeling More Accessible","description":"NextGen In A Box (NGIAB) surpasses 10,000 Docker pulls, highlighting growing global adoption of accessible, containerized water modeling tools.","slug":"ngiab-10k","authors":["arpita-2023"],"tags":["Blog","NGIAB","NextGen","CIROH","Containerization","Water Modeling","Docker","Hydrology","Education","Community Impact"],"image":"img/blog/2025-08-ngiab-10k/ngiab-banner.png"},"unlisted":false,"prevItem":{"title":"Cross-Institutional Collaboration Enhances Hydrologic Modeling in the Logan River Watershed","permalink":"/staging/main/blog/logan-river-collaboration"},"nextItem":{"title":"CIROH Researchers Showcase Cutting-Edge Hydrologic Science at NHWC 2025","permalink":"/staging/main/blog/nhwc-2025"}},"content":"![NGIAB Banner](/img/blog/2025-08-ngiab-10k/ngiab-banner.png)\\n\\n\\nWe\'re thrilled to announce that **NextGen In A Box (NGIAB)** has surpassed **10,000 Docker pulls** \u2014 a significant milestone reflecting the growing adoption of water modeling tools that are accessible to all. This achievement creates opportunities for researchers, practitioners, and students worldwide to leverage advanced water prediction frameworks without infrastructure barriers, accelerating global water science innovation.\\n\\n> *Update, 8/29*: **NGIAB Journal Paper** now available in *Environmental Modelling and Software*  \\n> **[\u2192 Read the full paper](https://www.sciencedirect.com/science/article/pii/S1364815225003500)**\\n\\n## From Research Innovation to Community Tool\\n\\nWhen we first containerized the NextGen Water Resources Modeling Framework into NGIAB, our goal was simple yet ambitious: **remove the technical barriers** that prevented many researchers from accessing NOAA\'s next-generation water modeling capabilities.\\n\\nToday, with over 10,000 downloads, it\'s clear the community was ready for this transformation.\\n\\nThe University of Alabama recently highlighted NGIAB\'s impact in their news feature, *[\\"UA Software Makes Water Modeling More Accessible\\"](https://news.ua.edu/2025/05/ua-software-makes-water-modeling-more-accessible/)*,  recognizing how this tool is changing the landscape of hydrologic research and education. As the article notes, NGIAB turns what was once a complex, infrastructure-heavy process into something that researchers can run on their laptops in minutes.\\n\\n{/* truncate */}\\n\\n## What 10,000 Pulls Really Means\\n\\nBehind this number are stories of:\\n\\n \u{1F393} **Graduate students** exploring advanced modeling techniques with no setup headaches\\n\\n \u{1F3EB} **Educators** bringing cutting-edge tools into the classroom  \\n\\n \u{1F3E2} **Researchers at smaller institutions** gaining access to national-scale modeling  \\n\\n \u{1F30D} **International collaborators** contributing to water modeling advancement without infrastructure constraints \\n\\n \u{1F6A8} **Emergency managers** rapidly deploying models for flood prediction\\n\\n## Community Growth and Impact\\nThe rapid adoption of NGIAB reflects a broader movement:\\n\\n**1. Democratization of Advanced Modeling**<br />\\nNo longer do researchers need access to specialized HPC resources or deep DevOps knowledge to run sophisticated water models. NGIAB levels the playing field.\\n\\n**2. Reproducible Science**<br />\\nEvery one of those 10,000 pulls represents the exact same computational environment, ensuring that research results can be replicated anywhere in the world.\\n\\n**3. Accelerated Innovation**<br />\\nBy removing setup friction, researchers can focus on science rather than software configuration, leading to faster iterations and discoveries.\\n\\n\\n## Looking Forward: The Next 10,000\\nAs we celebrate this milestone, we\'re already working on what\'s next:\\n\\n\u{1F4E6} **Expanded model library**: Adding more BMI-compliant models to the NGIAB ecosystem\\n\\n\u2601\uFE0F **Cloud integration**: Seamless deployment on AWS, Google Cloud, and Azure\\n\\n\u{1F4CA} **Enhanced visualization**: Built-in tools for analyzing and presenting model outputs\\n\\n\u{1F91D} **Community contributions**: Making it easier for users to share their configurations and improvements\\n\\n\\n## Join the NGIAB Community\\nWhether you\'re pull number 10,001 or have been with us since the beginning, you\'re part of a growing community that\'s transforming water resources modeling.\\n\\n\\nHere\'s how to get involved:\\n\\n\u{1F449} [**Try NGIAB**](https://docs.ciroh.org/training-NGIAB-101): Visit the NGIAB 101 tutorial to get started\\n\\n\u270D\uFE0F [**Share your use case**](/contact): Tell us how you\'re using NGIAB in your research or operations\\n\\n\u{1F6E0} [**Contribute**](/docs/products/ngiab-ecosystem/ngiab/distributions/ngiab-docker/contribute): Submit bug reports, feature requests, or code contributions\\n\\n\u{1F4E2} **Spread the word**: Help others discover how NGIAB can accelerate their water modeling work  \\n\\n## Thank You to Our Community\\nThis milestone belongs to everyone who downloaded, tested, provided feedback, contributed code, or helped spread the word about NGIAB. Your engagement drives our continuous improvement and motivates us to make water modeling even more accessible.\\n\\nAs we reflect on reaching 10,000 Docker pulls, we\'re reminded that each download represents a researcher, student, or practitioner working to better understand and predict our water resources. Together, we\'re building a more resilient future through accessible, advanced water modeling.\\n\\nHere\'s to the next 10,000 pulls and the continued growth of our community!\\n\\n---\\n\\n*NGIAB is developed and maintained by the Cooperative Institute for Research to Operations in Hydrology (CIROH) at the University of Alabama. Learn more about our work in making water modeling accessible at [ciroh.org](https://ciroh.org).*"},{"id":"nhwc-2025","metadata":{"permalink":"/staging/main/blog/nhwc-2025","source":"@site/blog/2025-08-01-NHWC-Blog-Post.mdx","title":"CIROH Researchers Showcase Cutting-Edge Hydrologic Science at NHWC 2025","description":"CIROH researchers showcased innovative work and leadership at the 15th Biennial National Hydrologic Warning Conference (NHWC 2025), presenting cutting-edge hydrologic forecasting tools and earning top recognition.","date":"2025-08-01T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"NHWC","permalink":"/staging/main/blog/tags/nhwc"},{"inline":true,"label":"Conference Highlights","permalink":"/staging/main/blog/tags/conference-highlights"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Hydrologic Modeling","permalink":"/staging/main/blog/tags/hydrologic-modeling"},{"inline":true,"label":"Forecasting","permalink":"/staging/main/blog/tags/forecasting"},{"inline":true,"label":"National Weather Service","permalink":"/staging/main/blog/tags/national-weather-service"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"Deltares","permalink":"/staging/main/blog/tags/deltares"},{"inline":true,"label":"Alabama","permalink":"/staging/main/blog/tags/alabama"}],"readingTime":4.72,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null},{"name":"Md Shahabul Alam","title":"Research Scientist","title2":"The University of Alabama","url":"https://www.linkedin.com/in/md-shahabul-alam/","imageURL":"/staging/main/img/blog/authors/shahab.jpeg","key":"shahab","page":null}],"frontMatter":{"title":"CIROH Researchers Showcase Cutting-Edge Hydrologic Science at NHWC 2025","description":"CIROH researchers showcased innovative work and leadership at the 15th Biennial National Hydrologic Warning Conference (NHWC 2025), presenting cutting-edge hydrologic forecasting tools and earning top recognition.","slug":"nhwc-2025","authors":["arpita-2023","shahab"],"tags":["Blog","NHWC","Conference Highlights","CIROH","Hydrologic Modeling","Forecasting","National Weather Service","NextGen","Deltares","Alabama"],"image":"img/blog/2025-08-nhwc/team.JPG"},"unlisted":false,"prevItem":{"title":"NGIAB Reaches 10,000 Docker Pulls: NextGen In A Box Makes Water Modeling More Accessible","permalink":"/staging/main/blog/ngiab-10k"},"nextItem":{"title":"Tethys Summit 2025: Advancing Geoscience with Open-Source Web Apps","permalink":"/staging/main/blog/tethys-summit-2025"}},"content":"![NHWC 2025 Banner at Tucson, Arizona](/img/blog/2025-08-nhwc/team.JPG)\\n> *CIROH team at NHWC 2025 in Tucson, Arizona, standing by the event\u2019s official banner.*\\n\\nCIROH had a strong showing at the 15th Biennial National Hydrologic Warning Conference (NHWC 2025), with our researchers presenting innovative solutions and engaging with the broader hydrologic warning community. The conference brought together field personnel, innovators, engineers, hydrologists, forecasters, water resource managers, and emergency management officials from across the country to advance flood warning systems and address emerging challenges in evolving climate and drought management.\\n\\n{/* truncate */}\\n\\n## Advancing Model Reliability in Hydrologic Forecasting\\n\\nDuring the NextGen presentation track, moderated by Dr. Steve Burian, CIROH researchers focused on improving evaluation techniques for hydrologic models\u2014particularly in the context of the National Water Model (NWM).\\n\\n## NWS NextGen Program\\n\\n![Edwin Welles presenting on NextGen Operational Foundation](/img/blog/2025-08-nhwc/edwin.JPG)\\n> *Edwin Welles from Deltares USA presenting the NextGen framework.*\\n\\n**Edwin Welles** from Deltares USA kicked things off with insights into a groundbreaking initiative.\\nThe Office of Water Prediction, of the National Weather Service has undertaken an ambitious project to implement and apply a new framework for hydrological modeling: the \\nThe Next Genearation Water Resources Modeling Framework, or the NextGen framework, is designed to emphasize modularity, interoperability, and reproducibility, creating an environment where disparate modeling components can be freely combined to enhance modeling capabilities.\\nThese advantages offer critical support to the National Water Model, alongside other key initiatives such as national Flood Inundation Mapping research.\\nThe system is being implemented by Raytheon with subcontract support from Deltares USA. His presentation provided a summary of the project and envisioned outcomes.\\n\\n## Leading the NextGen Revolution\\n\\n![Arpita Patel presenting NGIAB](/img/blog/2025-08-nhwc/arpita1.JPG)\\n> *Arpita Patel presenting \u201CNavigating the NextGen Ecosystem and NextGen In A Box (NGIAB).\u201D*\\n\\n**Arpita Patel** followed with *\u201CNavigating the NextGen Ecosystem and NextGen In A Box (NGIAB),\u201D* a presentation focused on making the NextGen framework more accessible to researchers, forecasters, and water managers.\\nThis was achieved through the NextGen In A Box platform, which harnesses containerization and supportive tooling to make the NextGen framework accessible and easy to use.\\nThis work directly supports CIROH\u2019s mission to democratize access to advanced hydrologic modeling capabilities and foster broader adoption of next-generation water prediction tools.\\n\\n\u{1F949} Patel also demonstrated exceptional engagement throughout the conference. Her outstanding participation earned her an impressive **#3 ranking on the NHWC 2025 conference leaderboard** with 70,200 points.\\nThis demonstrated not only her technical expertise, but also her active involvement in conference activities and community engagement.\\n\\n## Rethinking Evaluation\\n\\n![Dr. Md Shahabul Alam presenting model evaluation methods](/img/blog/2025-08-nhwc/shahab.jpg)\\n> *Dr. Md Shahabul Alam presenting different model evaluation methods.*\\n\\n\\n\\nDr. **Md Shahabul Alam** also delivered a compelling talk titled \u201CRethinking Model Reliability: A Dual Evaluation of NWM Using Time Series and Extreme Events\u201D during the NextGen program track. His work focuses on advancing operational hydrology by developing more rigorous and resilient methods to evaluate the National Water Model across varying temporal scales and extreme event conditions\u2014a crucial step in improving forecasting and decision-making under a changing climate.\\nThis work represents CIROH\u2019s commitment to enhancing the reliability and accuracy of national-scale hydrologic prediction systems, directly supporting the operational forecasting community\u2019s need for trustworthy model outputs during both routine conditions and extreme weather events.\\n\\n\u{1F947} Dr. Alam earned also earned the **#1 ranking on the NHWC 2025 conference leaderboard**, maintaining a commanding lead of over 100,000 points throughout the week and finishing with a remarkable 194,700 points. \\nHis name quickly became a focal point of the conference. Each morning, attendees checked the Whova app with anticipation\u2014only to see Shahab had once again pulled further ahead.\\nHis energetic participation and engaging presence made him a standout at the conference, combining technical depth with social and technological savvy.\\nDr. Alam not only demonstrated exceptional leadership and charisma at the NHWC 2025 conference, but also brought well-deserved visibility to CIROH and its ongoing mission.\\n\\n\\n## Strengthening Community Connections\\n\\nThe inclusion of these presentations within the NextGen presentation track highlights CIROH\u2019s central role in advancing the NextGen Water Resources Modeling Framework. This alignment demonstrates our organization\u2019s commitment to translating research innovations into operational capabilities that serve the broader water resources community.\\n\\nFollowing the presentations, many researchers expressed immediate interest in using NextGen In A Box for both their research applications and operational forecasting. The tool\'s modular design, ease of deployment, and compatibility with diverse datasets resonated strongly with attendees seeking flexible and scalable modeling solutions. Several participants noted its potential for accelerating innovation in hydrologic modeling and expressed intent to integrate it into their ongoing and future projects.\\n\\nThe conference provided valuable opportunities for our researchers to connect with operational forecasters, emergency managers, and fellow scientists, fostering collaborations that will enhance the real-world impact of CIROH\u2019s research initiatives. These interactions are essential for ensuring our scientific advances address the practical challenges faced by those responsible for flood warning and water resource management.\\n\\n\\n## Looking Ahead\\n\\nCIROH\u2019s strong presence at NHWC 2025 underscores our dedication to bridging the gap between research and operations in hydrologic science. Our researchers\u2019 contributions to model evaluation methodologies and NextGen ecosystem development represent key steps toward more reliable, accessible, and effective water prediction systems.\\n\\nAs we continue to advance hydrologic science, conferences like NHWC 2025 provide essential platforms for sharing innovations, gathering feedback from the operational community, and building the collaborative relationships that drive progress in water resources management and flood warning systems.\\n\\nThe success of our team at NHWC 2025 reflects CIROH\u2019s growing impact in the hydrologic sciences community and our commitment to developing solutions that serve both scientific advancement and societal needs."},{"id":"tethys-summit-2025","metadata":{"permalink":"/staging/main/blog/tethys-summit-2025","source":"@site/blog/2025-08-01-TethysSummit2025.mdx","title":"Tethys Summit 2025: Advancing Geoscience with Open-Source Web Apps","description":"Explore the workshop materials and our experience at Tethys Summit 2025.","date":"2025-08-01T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"},{"inline":true,"label":"Tethys Platform","permalink":"/staging/main/blog/tags/tethys-platform"},{"inline":true,"label":"Geoscience","permalink":"/staging/main/blog/tags/geoscience"},{"inline":true,"label":"Open Source","permalink":"/staging/main/blog/tags/open-source"}],"readingTime":5.33,"hasTruncateMarker":true,"authors":[{"name":"Giovanni Romero","title":"Hydroinformatics Engineer","title2":"Aquaveo","url":"https://www.linkedin.com/in/elkin-giovanni-romero-bustamante-b834b5a8","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U057VCZQWRW-fe48d8f10837-192","key":"gio","page":null},{"name":"Manjila Singh","title":"Graduate Research Assistant","title2":"Alabama Water Institute","url":"https://www.linkedin.com/in/manjilasingh/","imageURL":"https://ngiab.ciroh.org/assets/img/team/Me.jpg","key":"manjila","page":null}],"frontMatter":{"title":"Tethys Summit 2025: Advancing Geoscience with Open-Source Web Apps","description":"Explore the workshop materials and our experience at Tethys Summit 2025.","slug":"tethys-summit-2025","authors":["gio","manjila"],"tags":["Blog","Conference","Tethys Platform","Geoscience","Open Source"],"image":"img/blog/2025-08-tethys-summit/tethys-summit-7.jpg"},"unlisted":false,"prevItem":{"title":"CIROH Researchers Showcase Cutting-Edge Hydrologic Science at NHWC 2025","permalink":"/staging/main/blog/nhwc-2025"},"nextItem":{"title":"AORC Data in Your Hands: User-Friendly Jupyter Notebooks for Data Retrieval and Analysis via CIROH-2i2c JupyterHub Notebooks","permalink":"/staging/main/blog/aorc-data-access"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\nimport { Carousel } from \\"react-responsive-carousel\\"\\n\\n<Carousel\\n  showThumbs={false}\\n  autoPlay={true}\\n  stopOnHover={false}\\n  useKeyboardArrows={true}\\n  emulateTouch={true}\\n  interval={2500}\\n  infiniteLoop\\n  showStatus={false}\\n  showIndicators={true}\\n  >\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-08-tethys-summit/tethys-summit-7.jpg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"A group photo from Tethys Summit 2025\\"\\n      />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-08-tethys-summit/tethys-summit-2.jpg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"A workshop at Tethys Summit 2025\\"\\n      />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-08-tethys-summit/tethys-summit-3.jpg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"A workshop at Tethys Summit 2025\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-08-tethys-summit/tethys-summit-4.jpg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\'A workshop at Tethys Summit 2025\'\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-08-tethys-summit/tethys-summit-5.jpg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\'A workshop at Tethys Summit 2025\'\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-08-tethys-summit/tethys-summit-6.jpg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"Musicians at Tethys Summit 2025\\"\\n    />\\n  </div>\\n</Carousel>\\n\\n## My Experience at Tethys Summit 2025\\n\\nEarlier this month, I had the opportunity to attend Tethys Summit 2025 in Tampa, FL. It was a rewarding experience to learn about the Tethys Platform and how researchers, hydrologists, and geospatial scientists are applying it in their work. Through workshops and technical demonstrations, I gained insights into how this open-source Earth science platform is advancing environmental problem-solving.\\n\\n{/* truncate */}\\n\\nOn Day 1, I participated in the **Tethys Dash** workshop led by Corey Krewson, where I learned to build a Tethys dashboard without writing any code. During the hands-on session, I was surprised by how easily I was able to build dashboards using a drag-and-drop interface, as much of the technical implementation was abstracted for simplicity. I also attended the **Tethys Component Apps (ReactPy)** workshop by Shawn Crawley. Unlike the no-code approach of the first session, this workshop focused on building a basic interactive Tethys web app in under 50 lines of Python code.\\n\\nOn Day 2, I also took part in the **Contributing to Tethys Core** workshop led by Nathan Swain. This workshop outlined the steps for first-time contributors to get involved and submit pull requests to the Tethys Core repository. Aside from the workshops, I took part in Tethys App Competition where I presented the Tethys app I developed. It was a great learning experience to understand more about web app developments using Tethys. I ended up winning second place and got a bonsai tree LEGO set!  \\n\\nOverall, it was a very engaging and informative summit. For anyone who missed the session, the workshop materials are available here: [**Talks and Workshop Materials**](https://drive.google.com/drive/folders/18sSPsMkjSRtBZLAClEUV4AetKx9dPS6B)\\n\\n*\u2014 Manjila*\\n\\n---\\n\\n## What is Tethys?\\n\\n[**Tethys Platform**](https://www.tethysplatform.org) is an open-source, Python-powered framework that lets geoscientists and developers turn complex environmental data and models into browser-based, interactive web GIS apps\u2014without having to become web gurus. Built on [Django](https://www.djangoproject.com), it bundles a full spatial stack ([PostGIS](https://postgis.net), [GeoServer](http://geoserver.org), [OpenLayers](https://openlayers.org)/[Cesium](https://cesium.com)) plus handy \\"Gizmos\\" for maps, charts, and dashboards, and it integrates seamlessly with scientific libraries like NumPy, Pandas, Plotly, and Bokeh. A built-in job manager runs heavy climate or hydrologic models\u2014locally or in the cloud\u2014while APIs make it easy to pull data from THREDDS servers or PostGIS databases. The result is a low-barrier path to custom interfaces, 2D/3D visualizations, and scalable computing that\'s already powering water-resource tools, climate-scenario explorers, and disaster-monitoring apps worldwide. Backed by the [Tethys Geoscience Foundation](https://www.tethysgeoscience.org), the platform\'s active open-source community keeps it evolving to meet new Earth-science challenges.\\n\\n\\n## Community Impact\\n\\nThanks to these capabilities, Tethys Platform is widely adopted in the geoscience community. Scientists around the world use it for a range of applications\u2014water resource management, climate change analysis, natural disaster monitoring, environmental planning, and more. In each case, Tethys helps turn complex datasets and model outputs into accessible tools for decision-makers. As an open-source project under the [**Tethys Geoscience Foundation**](https://www.tethysgeoscience.org), it benefits from an active user community that continually contributes improvements and new features. This collaborative growth ensures the platform keeps pace with emerging needs in Earth science, effectively lowering the barrier for geoscientists to share data and models as powerful web applications.\\n\\n\\n## Tethys Platform Resources\\n\\nTethys Platform offers several resources to help you get started, including comprehensive official documentation, step-by-step tutorials, and a live demo portal. [The official documentation](https://docs.tethysplatform.org) covers everything from installation and \\"Hello World\\" examples to advanced topics and architecture (explaining how the Django backend and various services fit together). For hands-on learning, the [tutorials](https://docs.tethysplatform.org/en/stable/tutorials.html) guide you through setting up your first app, incorporating spatial data with built-in map layouts, connecting to GeoServer or THREDDS data servers, and even running cloud computations. And if you want to see Tethys in action without installing anything, the [**Tethys Demo Portal**](https://tethys.byu.edu/apps/) showcases a gallery of live example apps, such as a Gizmo Showcase of interactive widgets and a Wildfire Visualizer that displays wildfire data on a map, giving you a clear idea of the platform\'s capabilities and inspiring ideas for your own geoscientific web applications.\\n\\nEach of these resources will help you dive deeper into the Tethys Platform. Whether you\'re looking to develop a water resources tool, a climate data viewer, or any geoscientific web application, the combination of documentation, tutorials, and live demos will support you on your journey with Tethys. **Happy app building!**\\n\\n*\u2014 Gio*"},{"id":"aorc-data-access","metadata":{"permalink":"/staging/main/blog/aorc-data-access","source":"@site/blog/2025-07-01-Aorc-Data-Access.mdx","title":"AORC Data in Your Hands: User-Friendly Jupyter Notebooks for Data Retrieval and Analysis via CIROH-2i2c JupyterHub Notebooks","description":"Accessing AORC data has never been easier with our new Jupyter Notebooks, designed for both point and zone retrieval from the AORC datasets hosted on AWS.","date":"2025-07-01T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Community Spotlight","permalink":"/staging/main/blog/tags/community-spotlight"},{"inline":true,"label":"Utah State University","permalink":"/staging/main/blog/tags/utah-state-university"},{"inline":true,"label":"HydroShare","permalink":"/staging/main/blog/tags/hydro-share"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Data Preparation","permalink":"/staging/main/blog/tags/data-preparation"},{"inline":true,"label":"JupyterHub","permalink":"/staging/main/blog/tags/jupyter-hub"},{"inline":true,"label":"2i2c","permalink":"/staging/main/blog/tags/2-i-2-c"},{"inline":true,"label":"Cloud Services","permalink":"/staging/main/blog/tags/cloud-services"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"NOAA","permalink":"/staging/main/blog/tags/noaa"}],"readingTime":2.68,"hasTruncateMarker":true,"authors":[{"name":"Homa Salehabadi","title":"Postdoctoral Researcher","title2":"Utah State University","url":"https://www.linkedin.com/in/homasalehabadi/","imageURL":"https://scholar.googleusercontent.com/citations?view_op=medium_photo&user=LsGbadwAAAAJ&citpid=5","key":"homa","page":null},{"name":"David Tarboton","title":"Professor","title2":"Utah Water Research Laboratory","url":"https://www.linkedin.com/in/dtarb/","imageURL":"/staging/main/img/blog/authors/david_tarboton.jpg","key":"david","page":null},{"name":"Ayman Nassar","title":"Postdoctoral Researcher","title2":"Utah State University","url":"https://www.linkedin.com/in/ayman-nassar-24a92723/","imageURL":"/staging/main/img/blog/authors/ayman_nassar.png","key":"ayman","page":null}],"frontMatter":{"title":"AORC Data in Your Hands: User-Friendly Jupyter Notebooks for Data Retrieval and Analysis via CIROH-2i2c JupyterHub Notebooks","description":"Accessing AORC data has never been easier with our new Jupyter Notebooks, designed for both point and zone retrieval from the AORC datasets hosted on AWS.","slug":"aorc-data-access","authors":["homa","david","ayman"],"tags":["Blog","Community Spotlight","Utah State University","HydroShare","CIROH","Data Preparation","JupyterHub","2i2c","Cloud Services","National Water Model","NOAA"],"image":"img/blog/2025-07-aorc-data-access/aorc-data-retrieval-hydroshare.png"},"unlisted":false,"prevItem":{"title":"Tethys Summit 2025: Advancing Geoscience with Open-Source Web Apps","permalink":"/staging/main/blog/tethys-summit-2025"},"nextItem":{"title":"Assessing Streamflow Forecast Over the Hackensack River Watershed Using NGIAB","permalink":"/staging/main/blog/ismart-ngiab-application"}},"content":"![Screenshot of Hydroshare Resource](/img/blog/2025-07-aorc-data-access/aorc-data-retrieval-hydroshare.png)\\n> *A screenshot of the HydroShare resource page for [Jupyter Notebooks for the Retrieval of AORC Data for Hydrologic Analysis](https://www.hydroshare.org/resource/72ea9726187e43d7b50a624f2acf591f/).*\\n\\nThe Analysis of Record for Calibration (AORC) dataset is recognized as a high-value resource for the CUAHSI and CIROH community.\\nThis dataset is hosted by NOAA via Amazon Web Services (AWS) and is available in two primary formats:\\na [latitude-longitude gridded dataset](https://registry.opendata.aws/noaa-nws-aorc/)\\nand the [National Water Model (NWM) projected dataset, part of the NWM Retrospective archive](https://registry.opendata.aws/nwm-archive/).\\nTo enhance accessibility and illustrate analysis capabilities, we developed four user-friendly Jupyter Notebooks that enable data retrieval for both specific points of interest and spatial domains defined by shapefiles:\\n\\n{/* truncate */}\\n\\n-\\t**AORC_LL_PointRetrieval.ipynb**: For retrieving and aggregating data from the latitude-longitude gridded dataset for a specific point using geographic coordinates.\\n-\\t**AORC_LL_ZoneRetrieval.ipynb**: For retrieving and aggregating data from the latitude-longitude gridded dataset for an area defined by a polygon shapefile.\\n-\\t**AORC_NWMProj_PointRetrieval.ipynb**: For retrieving and aggregating data from the NWM projected dataset for a specific point using geographic coordinates.\\n-\\t**AORC_NWMProj_ZoneRetrieval.ipynb**: For retrieving and aggregating data from the NWM projected dataset for an area defined by a polygon shapefile.\\n\\nThese Jupyter Notebooks, containing instructions and Python code to access the data, enable researchers to retrieve AORC data from AWS.\\nFrom there, the notebooks offer options to subset and aggregate the data over user-defined time intervals (beyond the original hourly resolution) and spatial area.\\nThese serve as examples for how you could write or modify code to access AORC data in your work.\\nThe notebooks are publicly [available on HydroShare](https://www.hydroshare.org/resource/72ea9726187e43d7b50a624f2acf591f/)\\nand are compatible with JupyterHub computing platforms such as [CIROH 2i2c JupyterHub linked to HydroShare](https://www.hydroshare.org/resource/2dd1ac86e8854d4fb9fe5fbafaec2b98/).\\n\\nTo use these notebooks, go to the [HydroShare resource](https://www.hydroshare.org/resource/72ea9726187e43d7b50a624f2acf591f/),\\nselect \\"Open With\\" at the top right, and choose \\"CIROH 2i2c JupyterHub\\".\\nThis will copy the resource contents (notebooks and data) into the CIROH-2i2c JupyterHub environment,\\nwhere you can open and work through them to access the data.\\nNote that you will need a [CUAHSI HydroShare account](https://www.hydroshare.org) to access \\"Open With\\" in HydroShare,\\nand you will also need to [request CIROH-2i2c JupyterHub access](/docs/services/access/#jupyterhub) using a GitHub account. \\n\\nOur work also includes a comparative analysis of the two AORC datasets with a summary of findings.\\nWhile we mostly observed small differences, mainly due to projections, users should be aware of potential discrepancies between the datasets.\\n\\nBy providing these user-friendly tools and highlighting the characteristics of both AORC datasets,\\nour work aims to support and facilitate more efficient hydrological and climate-related research within the CUAHSI and CIROH community.\\n\\n### References:\\n- Salehabadi, H., D. Tarboton, A. Nassar, A. M. Castronova, P. Dash (2025). Jupyter Notebooks for the Retrieval of AORC Data for Hydrologic Analysis, HydroShare, http://www.hydroshare.org/resource/72ea9726187e43d7b50a624f2acf591f\\n- The development versions of these notebooks are available on GitHub: https://github.com/CUAHSI/notebooks in the Data Access Examples / AORC - Retrieval of AORC Data for Hydrologic Analysis folder.\\n- Patel, A., A. Castronova (2025). CIROH 2i2c JupyterHub, HydroShare, http://www.hydroshare.org/resource/2dd1ac86e8854d4fb9fe5fbafaec2b98"},{"id":"ismart-ngiab-application","metadata":{"permalink":"/staging/main/blog/ismart-ngiab-application","source":"@site/blog/2025-06-27-ISMART-NGIAB-Application.mdx","title":"Assessing Streamflow Forecast Over the Hackensack River Watershed Using NGIAB","description":"A summary of the research presented at the 2025 CIROH DevCon, focusing on streamflow forecasting in the Hackensack River Watershed using NGIAB.","date":"2025-06-27T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Community Spotlight","permalink":"/staging/main/blog/tags/community-spotlight"},{"inline":true,"label":"Stevens Institute of Technology","permalink":"/staging/main/blog/tags/stevens-institute-of-technology"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"CIROH DevCon","permalink":"/staging/main/blog/tags/ciroh-dev-con"},{"inline":true,"label":"AI and Machine Learning","permalink":"/staging/main/blog/tags/ai-and-machine-learning"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"}],"readingTime":2.6,"hasTruncateMarker":true,"authors":[{"name":"Jorge Bravo","title":"Graduate Research Assistant","title2":"I-SMART, Stevens Institute of Technology","url":"https://www.linkedin.com/in/jhbravo/","imageURL":"https://web.stevens.edu/ismart/images/s3.jpg","key":"jorge","page":null},{"name":"Marouane Temini","title":"Associate Professor","title2":"I-SMART, Stevens Insitute of Technology","url":"https://scholar.google.com/citations?user=5v7tTVgAAAAJ&hl=en","imageURL":"https://web.stevens.edu/ismart/images/s4.jpg","key":"marouane","page":null}],"frontMatter":{"title":"Assessing Streamflow Forecast Over the Hackensack River Watershed Using NGIAB","description":"A summary of the research presented at the 2025 CIROH DevCon, focusing on streamflow forecasting in the Hackensack River Watershed using NGIAB.","slug":"ismart-ngiab-application","authors":["jorge","marouane"],"tags":["Blog","Community Spotlight","Stevens Institute of Technology","NGIAB","NextGen","CIROH DevCon","AI and Machine Learning","National Water Model"],"image":"img/blog/2025-06-27-ngiab-based-research/blog_CIROH_DevCon.png"},"unlisted":false,"prevItem":{"title":"AORC Data in Your Hands: User-Friendly Jupyter Notebooks for Data Retrieval and Analysis via CIROH-2i2c JupyterHub Notebooks","permalink":"/staging/main/blog/aorc-data-access"},"nextItem":{"title":"DevCon 2025: A DevOps and Cyberinfrastructure Success Story","permalink":"/staging/main/blog/devcon25-infra"}},"content":"<div style={{ textAlign: \'center\' }}>\\n  ![A poster, titled \\"Assessing streamflow forecast over the Hackensack River Watershed using physics- and AI-driven weather prediction models\\".](/img/blog/2025-06-27-ngiab-based-research/blog_CIROH_DevCon.png)\\n</div>\\n> *A poster presented by the I-SMART team at the CIROH Developers Conference, held at the University of Vermont in Burlington from May 28 to 30, 2025.*\\n\\nThe densely populated Hackensack River watershed lies within the New York City Metropolitan Area, which spans northern New Jersey and southern New York.\\nAccurate streamflow forecasting within this region is therefore essential to enable effective water resource management, flood prediction, and disaster preparedness.\\n\\nPrecipitation data is critical for effective hydrological modeling, making the identification of reliable data sources a key priority.\\nThis is why the Integrated Spatial Modeling and Remote Sensing Technologies Laboratory (I-SMART),\\nan interdisciplinary research unit within the Davidson Laboratory at Stevens Institute of Technology in Hoboken, New Jersey,\\nuses the latest developments in both atmospheric and hydrological modeling to address flood risks in the Hackensack Watershed\\nwith solutions that could be expanded to the entire New York City Metropolitan Area.\\n\\n{/* truncate */}\\n\\nIn the past, this work has included key early applications of the Next Generation Water Resources Modeling Framework (NextGen).\\nNotably, the I-SMART group was among the first to force the NextGen framework with multiple atmospheric models for comparative analysis during a real-world event:\\nthe passage of Superstorm Ida over the New York metropolitan area in September 2021.\\nThe recent advent of NextGen In a Box (NGIAB) has provided an opportunity to accelerate these applications even further\\nby taking full advantage of NGIAB\'s containerized, user-friendly, and easily deployed environment.\\n\\nRecently, the I-SMART team has been testing various regional atmospheric models grounded in physical equations,\\nincluding traditional models like WRF and next-generation atmospheric models such as MPAS.\\nAdditionally, given the increasing popularity and adoption of AI/ML-based approaches,\\nthe team has also begun exploring their potential.\\nThe goal of this work is to assess the performance of these approaches in the Hackensack Watershed,\\nalong with investigating the sensitivity of the model to various meteorological forcings, including forcings based on the National Water Model.\\n*(The initial and/or boundary conditions for all the models were determined using the Global Forecast System.)*\\n\\nThis investigation required handling a large volume of precipitation data from various models,\\neach with different spatial resolutions and in some cases, such as MPAS, using unstructured grids.\\nAs such, one of the key challenges was finding a hydrological modeling framework flexible enough to accommodate such diversity.\\nThis made the NextGen framework a natural choice, allowing them to integrate precipitation forcings from various sources\\nwith the appropriate pre-processing to align them with the model requirements in terms of spatial and temporal scales.\\n\\nThe complex implementation and execution of these models was faciliated by NextGen In A Box (NGIAB),\\nwhich successfully enabled the integration of diverse precipitation sources.\\nBy simplifying local deployment and providing full control over model inputs, configurations, and runtime operations,\\nNGIAB has given the I-SMART team the tools to conduct their groundbreaking research with even greater efficiency."},{"id":"devcon25-infra","metadata":{"permalink":"/staging/main/blog/devcon25-infra","source":"@site/blog/2025-06-04-DevCon25-Infra.mdx","title":"DevCon 2025: A DevOps and Cyberinfrastructure Success Story","description":"Our team demonstrated how modern DevOps principles and cloud infrastructure can seamlessly support large-scale technical workshops for over 200 attendees.","date":"2025-06-04T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"},{"inline":true,"label":"CIROH DevCon","permalink":"/staging/main/blog/tags/ciroh-dev-con"},{"inline":true,"label":"Services","permalink":"/staging/main/blog/tags/services"},{"inline":true,"label":"NSF","permalink":"/staging/main/blog/tags/nsf"},{"inline":true,"label":"NSF Access","permalink":"/staging/main/blog/tags/nsf-access"},{"inline":true,"label":"2i2c","permalink":"/staging/main/blog/tags/2-i-2-c"},{"inline":true,"label":"JetStream2","permalink":"/staging/main/blog/tags/jet-stream-2"},{"inline":true,"label":"AWS","permalink":"/staging/main/blog/tags/aws"},{"inline":true,"label":"Google Cloud","permalink":"/staging/main/blog/tags/google-cloud"},{"inline":true,"label":"HPC","permalink":"/staging/main/blog/tags/hpc"},{"inline":true,"label":"Wukong","permalink":"/staging/main/blog/tags/wukong"},{"inline":true,"label":"Pantarhei","permalink":"/staging/main/blog/tags/pantarhei"},{"inline":true,"label":"On-Premises Services","permalink":"/staging/main/blog/tags/on-premises-services"}],"readingTime":2.59,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"DevCon 2025: A DevOps and Cyberinfrastructure Success Story","description":"Our team demonstrated how modern DevOps principles and cloud infrastructure can seamlessly support large-scale technical workshops for over 200 attendees.","slug":"devcon25-infra","authors":"arpita-2023","tags":["Blog","CIROH","Conference","CIROH DevCon","Services","NSF","NSF Access","2i2c","JetStream2","AWS","Google Cloud","HPC","Wukong","Pantarhei","On-Premises Services"],"hide_table_of_contents":false,"image":"img/blog/2025-06-devcon25/it_team.png"},"unlisted":false,"prevItem":{"title":"Assessing Streamflow Forecast Over the Hackensack River Watershed Using NGIAB","permalink":"/staging/main/blog/ismart-ngiab-application"},"nextItem":{"title":"DevCon 2025: Hydroinformatics and Research CyberInfrastructure Keynote","permalink":"/staging/main/blog/devcon25-keynote"}},"content":"The recent DevCon 2025 event showcased not just cutting-edge development practices, but also demonstrated how modern DevOps principles and cloud infrastructure can seamlessly support large-scale technical workshops. Our team had the privilege of providing IT infrastructure and support for over 200 attendees, creating a robust learning environment through an exemplary public-private partnership.\\n\\n![Image of CIROH\'s Research Cyberinfrastructure and DevOps team. On the left, two graphs are shown depicting usage for the Google Cloud-2i2c and Jetstream2 environments.](/img/blog/2025-06-devcon25/it_team.png)\\n> *CIROH\'s Research Cyberinfrastructure and DevOps team.* <br/>\\n> *Left to right, top to bottom:<br/>Manjila Singh, Arpita Patel, Nia Minor, Trupesh Patel, James Halgren; Benjamin Lee.*\\n{/* truncate */}\\n## The Power of Collaboration\\n\\nDevCon 2025 represented an outstanding example of what\'s possible when public institutions and private enterprises work together:\\n- **Corporate Sponsors**: AWS and Google Cloud provided funding and infrastructure for the event.\\n- **Infrastructure Partners**: NSF JetStream and 2i2c JupyterHub delivered the computational backbone.\\n- **Technical Implementation**: The CIROH Research Cyberinfrastructure and DevOps Team managed IT access and software packaging.\\n\\n\\n![Image of CIROH\'s Research Cyberinfrastructure DevCon support](/img/blog/2025-06-devcon25/workshops.svg)\\n\\n## Our Technical Approach\\n\\nSupporting 200+ workshop attendees required careful planning and execution. Our DevOps team and partners implemented:\\n\\n### Infrastructure as Code\\n- Automated deployment of workshop environments\\n- Scalable JupyterHub instances configured for concurrent users\\n- Pre-packaged software environments ensuring consistency across all workstations\\n\\n### Cloud-Native Solutions\\n- Leveraged AWS S3 bucket and Google Cloud BigQuery \\n- Implemented auto-scaling to handle peak workshop loads\\n- Ensured high availability across multiple availability zones\\n\\n### Seamless User Experience\\n- Single sign-on authentication for 100+ participants using CIROH 2i2c JupyterHub\'s new WORKSHOP Hub!!\\n- Pre-configured JetStream2 environments with all necessary tools\\n- Real-time support slack channels for immediate issue resolution\\n\\n### Key Achievements\\n- **Zero Downtime**: Maintained 100% uptime throughout the entire event\\n- **Rapid Onboarding**: All 200 attendees were able to access their environments within minutes\\n- **Consistent Experience**: Every participant had identical, fully-functional development environments\\n- **Real-time Support**: Our team resolved technical issues with average response time under 5 minutes\\n\\n## Lessons Learned\\n\\nThis event perfectly demonstrated how DevOps principles\u2014bridging development and operations\u2014combined with cloud computing can transform organizational capabilities. Key takeaways include:\\n1. **Automation is Essential**: Pre-event automation allowed us to focus on attendee support rather than infrastructure management.\\n2. **Public-Private Partnerships Work**: Combining Google Cloud services, AWS services, 2i2c services and NSF\'s research infrastructure created a best-of-class research workshops solution.\\n3. **Preparation Prevents Problems**: Our extensive pre-event testing and redundancy planning paid dividends during the live event.\\n\\n## Looking Forward\\n\\nThe success of DevCon 2025\'s IT infrastructure demonstrates that large-scale technical events no longer need to be limited by traditional IT constraints. By embracing DevOps practices and leveraging cloud partnerships, we can create learning environments that scale effortlessly while maintaining reliability and performance.\\n\\nWe\'re proud to have supported the DevCon 2025 community and look forward to applying these lessons to future events. The combination of public research infrastructure, private cloud resources, and dedicated DevOps expertise created an environment where 200+ developers could focus on learning and innovation without worrying about technical barriers."},{"id":"devcon25-keynote","metadata":{"permalink":"/staging/main/blog/devcon25-keynote","source":"@site/blog/2025-06-04-DevCon25-Keynote.mdx","title":"DevCon 2025: Hydroinformatics and Research CyberInfrastructure Keynote","description":"Keynote Recap - CIROH Developers Conference 2025","date":"2025-06-04T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"},{"inline":true,"label":"CIROH DevCon","permalink":"/staging/main/blog/tags/ciroh-dev-con"},{"inline":true,"label":"Flood Inundation Mapping","permalink":"/staging/main/blog/tags/flood-inundation-mapping"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"Services","permalink":"/staging/main/blog/tags/services"},{"inline":true,"label":"NSF","permalink":"/staging/main/blog/tags/nsf"},{"inline":true,"label":"NSF Access","permalink":"/staging/main/blog/tags/nsf-access"},{"inline":true,"label":"2i2c","permalink":"/staging/main/blog/tags/2-i-2-c"},{"inline":true,"label":"JetStream2","permalink":"/staging/main/blog/tags/jet-stream-2"},{"inline":true,"label":"AWS","permalink":"/staging/main/blog/tags/aws"},{"inline":true,"label":"Google Cloud","permalink":"/staging/main/blog/tags/google-cloud"},{"inline":true,"label":"NextGen Datastream","permalink":"/staging/main/blog/tags/next-gen-datastream"},{"inline":true,"label":"Tethys Platform","permalink":"/staging/main/blog/tags/tethys-platform"},{"inline":true,"label":"On-Premises Services","permalink":"/staging/main/blog/tags/on-premises-services"},{"inline":true,"label":"DocuHub","permalink":"/staging/main/blog/tags/docu-hub"},{"inline":true,"label":"CIROH Portal","permalink":"/staging/main/blog/tags/ciroh-portal"}],"readingTime":4.93,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"DevCon 2025: Hydroinformatics and Research CyberInfrastructure Keynote","description":"Keynote Recap - CIROH Developers Conference 2025","slug":"devcon25-keynote","authors":"arpita-2023","tags":["Blog","CIROH","Conference","CIROH DevCon","Flood Inundation Mapping","National Water Model","NGIAB","NextGen","Services","NSF","NSF Access","2i2c","JetStream2","AWS","Google Cloud","NextGen Datastream","Tethys Platform","On-Premises Services","DocuHub","CIROH Portal"],"hide_table_of_contents":false,"image":"img/blog/2025-06-devcon25/keynote_0.jpeg"},"unlisted":false,"prevItem":{"title":"DevCon 2025: A DevOps and Cyberinfrastructure Success Story","permalink":"/staging/main/blog/devcon25-infra"},"nextItem":{"title":"Application of NOAA-OWP\'s NextGen Framework: DevCon 2025 and EWRI Congress 2025 Highlights","permalink":"/staging/main/blog/ewri-devcon25-ngiab"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\nimport { Carousel } from \\"react-responsive-carousel\\"\\nimport VideoPlayer from \'/src/components/VideoPlayer.js\';\\n\\nLast week, I had the incredible opportunity to co-present a keynote at the CIROH\\nDevelopers Conference (DevCon 2025), which attracted over 200 attendees. This\\npresentation, which I presented alongside Dan Ames, focused on \\"CIROH HydroInformatics\\nand Research Cyberinfrastructure.\\" It was a fantastic experience to share insights\\ninto the powerful tools and technologies that CIROH engineers, students, researchers\\nhave been developing to advance hydrological research and operations.\\n\\n<Carousel\\n  showThumbs={false}\\n  autoPlay={true}\\n  stopOnHover={false}\\n  useKeyboardArrows={true}\\n  emulateTouch={true}\\n  interval={3500}\\n  infiniteLoop\\n  showStatus={false}\\n  showIndicators={true}\\n  >\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-06-devcon25/keynote_0.jpeg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Arpita Patel and Dan Ames presenting their plenary keynote at CIROH DevCon 2025.\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-06-devcon25/keynote_1.jpeg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Arpita Patel and Dan Ames presenting their plenary keynote at CIROH DevCon 2025.\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-06-devcon25/keynote_2.jpeg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Arpita Patel and Dan Ames presenting their plenary keynote at CIROH DevCon 2025.\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-06-devcon25/keynote_3.jpeg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Arpita Patel and Dan Ames presenting their plenary keynote at CIROH DevCon 2025.\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-06-devcon25/keynote_4.jpeg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Arpita Patel and Dan Ames presenting their plenary keynote at CIROH DevCon 2025.\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-06-devcon25/keynote_5.jpeg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Arpita Patel and Dan Ames presenting their plenary keynote at CIROH DevCon 2025.\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-06-devcon25/keynote_6.jpeg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Arpita Patel and Dan Ames presenting their plenary keynote at CIROH DevCon 2025.\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-06-devcon25/keynote_7.jpeg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Arpita Patel and Dan Ames presenting their plenary keynote at CIROH DevCon 2025.\\"\\n    />\\n  </div>\\n</Carousel>\\n<br/>\\n{/* truncate */}\\nOur keynote aimed to showcase the comprehensive ecosystem that CIROH offers. We highlighted four key pillars:\\n\\n- **Computing Resources**: CIROH offers accress to public cloud infrastructure, on-premises HPC, and NSF ACCESS resources.\\n- **Data Management**: CIROH members handle and share vast datasets crucial for hydrological modeling. We\'ve provided platforms to do so through [HydroShare](https://hydroshare.org) and CIROH AWS S3 buckets, as well as streamlining access and analysis of this data through tools like Google BigQuery API and Tethys Platform.\\n- **Model Development**: CIROH develops tools and frameworks for developing and refining hydrological models, including the [NGIAB ecosystem](https://ngiab.ciroh.org).\\n- **Knowledge Sharing**: CIROH disseminates findings and best practices through the [DocuHub and Portal](https://hub.ciroh.org) platforms.\\n\\n<div>\\n  <VideoPlayer url=\\"https://youtu.be/dPuCSRYjjW8\\" />\\n  <div className=\\"centered-caption\\">\\n    *Slides are available here: [View slideshow](/files/DevCon25-PlenaryKeyNote-Arpita-Dan.pdf)*\\n  </div>\\n</div>\\n\\n## Value and Impact\\nDuring the keynote, we emphasized the value that CIROH brings to new students and researchers. This includes access to:\\n- Computational resources (free for researchers) that would normally cost thousands of dollars.\\n- Datasets that would take months to compile.\\n- Tools that streamline research and increase its impact.\\n- Publications - https://hub.ciroh.org/publications\\n\\n\\n\\n# CIROH Ecosystem Tools\\n\\nWe also showcased several transformative tools within the CIROH ecosystem that are advancing the field of hydrology:\\n\\n- **NGIAB (NextGen In A Box) ecosystem** ([ngiab.ciroh.org](https://ngiab.ciroh.org)): Revolutionizes water modeling by making the NextGen framework portable and accessible through containerized, open-source solutions.\\n- **CIROH DocuHub** ([hub.ciroh.org](https://hub.ciroh.org)): Your comprehensive knowledge center featuring technical documentation, monthly insights, and the latest developments in water science.\\n- **CIROH Portal** ([hub.ciroh.org](https://hub.ciroh.org)): A unified gateway connecting researchers to essential data, cutting-edge tools, and collaborative research opportunities.\\n- **Google BigQuery NWM API** ([Documentation](/docs/products/data-management/bigquery-api/)): Streamlines National Water Model data access with powerful cloud-based querying capabilities for efficient analysis.\\n- **Tethys Platform**: Transforms complex hydrological data and models into intuitive web applications, making advanced water science accessible to all stakeholders.\\n- **AWS, Google Cloud, 2i2c JupyterHub and NSF Access**: CIROH\'s AWS, Google Cloud accounts, CIROH 2i2c JupyuterHub and NSF Allocations for cloud computing in hydrology.\\n- **Pantarhei and Wukong HPC**: CIROH\'s state-of-the-art high-performance computing infrastructure, powering computationally intensive research and simulations.\\n- And many more innovative solutions driving water science forward!\\n\\n\\nOur overall message was that CIROH\u2019s hydroinformatics and research cyberinfrastructure\\necosystem is designed to support and amplify research efforts. We encouraged attendees\\nto explore these resources and consider how they could be applied to their own work.\\nWhether it\'s streamlining data workflows, tackling computationally intensive tasks,\\nor sharing findings, CIROH provides the tools and infrastructure to push the boundaries\\nof hydrological science.\\n \\nWe want to thank everyone who attended our keynote and engaged in the Mentimeter quiz.\\nIt\u2019s an exciting time for CIROH, and we\u2019re thrilled to be a part of this dynamic community!\\n\\n<VideoPlayer url=\\"https://youtu.be/zE3uFvDCSs4\\" />\\n> *Video voiced by Quinn Lee and prepared by Manjila Singh, Nia Minor, and Arpita Patel.*"},{"id":"ewri-devcon25-ngiab","metadata":{"permalink":"/staging/main/blog/ewri-devcon25-ngiab","source":"@site/blog/2025-06-04-EWRI-DevCon25-NGIAB.mdx","title":"Application of NOAA-OWP\'s NextGen Framework: DevCon 2025 and EWRI Congress 2025 Highlights","description":"A recap of presentations and workshops from the 2025 EWRI Congress and CIROH Developers Conference, focusing on the practical application of the NOAA-OWP NextGen Framework.","date":"2025-06-04T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"NOAA","permalink":"/staging/main/blog/tags/noaa"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"},{"inline":true,"label":"EWRI","permalink":"/staging/main/blog/tags/ewri"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"CIROH DevCon","permalink":"/staging/main/blog/tags/ciroh-dev-con"},{"inline":true,"label":"Calibration","permalink":"/staging/main/blog/tags/calibration"}],"readingTime":4.57,"hasTruncateMarker":true,"authors":[{"name":"Sifan A. Koriche","title":"Research [Hydrologic] Scientist","title2":"Alabama Water Institute","url":"https://github.com/skoriche","imageURL":"https://avatars.githubusercontent.com/u/71176390?s=400&u=7972b6bf562150237c77ba739972cf436a5b45c3&v=4","key":"sifan","page":null}],"frontMatter":{"title":"Application of NOAA-OWP\'s NextGen Framework: DevCon 2025 and EWRI Congress 2025 Highlights","description":"A recap of presentations and workshops from the 2025 EWRI Congress and CIROH Developers Conference, focusing on the practical application of the NOAA-OWP NextGen Framework.","slug":"ewri-devcon25-ngiab","authors":["sifan"],"tags":["Blog","CIROH","NOAA","Conference","EWRI","National Water Model","NGIAB","NextGen","CIROH DevCon","Calibration"],"hide_table_of_contents":false,"image":"img/blog/2025-06-ewri-devcon/DevCon_AWI_Team.png"},"unlisted":false,"prevItem":{"title":"DevCon 2025: Hydroinformatics and Research CyberInfrastructure Keynote","permalink":"/staging/main/blog/devcon25-keynote"},"nextItem":{"title":"\u03B4HBV2.0: How NGIAB and Wukong HPC Streamlined Advanced Hydrologic Modeling","permalink":"/staging/main/blog/may-2025-update"}},"content":"<div style={{ textAlign: \'center\' }}>\\n  ![AWI Science and Technology Team @ CIROH DevCon2025](/img/blog/2025-06-ewri-devcon/DevCon_AWI_Team.png)\\n</div>\\n> *CIROH-AWI Science and Technology Team.* <br/>\\n> *Left to right: Sagy Cohen, Steven Burian, Manjila Singh, Saide Zand, Savalan N. Neisary, Arpita Patel, Nia Minor, Trupesh Patel, Sifan A. Koriche, Jonathan Frame, Reza S. Alipour, Hari T. Jajula, Chad Perry; Josh Cunningham.*\\n\\n\\nMay was a pivotal month for representing the [Cooperative Institute for Research to Operations in Hydrology (CIROH)](https://ciroh.ua.edu/) and our collective work in advancing water science. As one of CIROH\'s Ambassadors, I had the privilege of connecting with the broader scientific community at two key events: the [Environmental and Water Resources Institute (EWRI) Congress](https://www.ewricongress.org/) in Anchorage, Alaska, and the [2025 CIROH Developers Conference](https://ciroh.ua.edu/devconference/2025-ciroh-developers-conference/) in Burlington, Vermont.\\n\\n{/* truncate */}\\n\\n### Empowering the Community at the [2025 CIROH Developers Conference](https://ciroh.ua.edu/devconference/2025-ciroh-developers-conference/)\\n\\nThe annual [**CIROH Developers Conference**](https://ciroh.ua.edu/devconference/2025-ciroh-developers-conference/) is a premier three-day event that convenes hundreds of scientists, engineers, and software developers from across the consortium and its partner institutions. It serves as a vital hub for innovation and collaboration, where attendees engage with the latest research findings, project highlights, and hands-on workshops on cutting-edge tools, workflows, and methodologies.\\n\\nFor me, this year\'s conference in the beautiful city of [Burlington, Vermont](https://www.google.com/maps/place/Burlington,+VT/), felt like coming full circle, as it marked my one-year anniversary since joining the consortium through [The University of Alabama](https://www.ua.edu/).\\n\\nI had the privilege of leading a [hands-on training workshop on hydrological model calibration](https://github.com/skoriche/NGIAB-Calibration-DevCon25). It was a fantastic experience engaging with the talented developers, researchers, and scientists who are all dedicated to the advancement and acceleration of Community Water Resources Modeling. Our session provided comprehensive, hands-on guidance for calibrating one of core components of the NextGen National Water Model model-confifuration\u2014specifically the [Conceptial Functional Equivalent (CFE)](https://github.com/NOAA-OWP/cfe) coupled with [Noah-OWP-Modular](https://github.com/NOAA-OWP/noah-owp-modular)\u2014within the [**NextGen In A Box (NGIAB) ecosystem**](https://ngiab.ciroh.org).\\n\\nThe [NGIAB ecosystem](https://ngiab.ciroh.org) is a comprehensive platform that revolutionizes how we approach hydrological research with integrated capabilities for:\\n\\n* \u2728 **1. Data preprocessing**\\n* \u2699\uFE0F **2. Hydrology model simulations and calibration**\\n* \u{1F4CA} **3. Advanced evaluation tools**\\n* \u{1F4C8} **4. Rich visualization capabilities**\\n\\nA huge thank you to [CIROH](https://ciroh.ua.edu/) for organizing such an insightful conference, and to the [University of Vermont](https://www.uvm.edu/) for being an excellent host!\\n{}\\nFor everyone who attended or is interested in learning more, all training materials, codes, and data from the workshop are openly available in our GitHub repository:\\n\\n\u27A1\uFE0F **[NGIAB-Calibration-DevCon25 Workshop Materials](https://github.com/skoriche/NGIAB-Calibration-DevCon25)**  \\n\u27A1\uFE0F **More NextGen Workshops**: [DocuHub News](/news); May 2025 Updates\\n\\nI\'m inspired by the passion for innovation shown and look forward to seeing how the community leverages these tools to advance water modeling.\\n\\n![A speaker presents at a conference, with a large screen displaying presentation slides and organization logos.](/img/blog/2025-06-ewri-devcon/Photo-DevCon2025.png)\\n\\n\\n### Disseminating Research at the [EWRI Congress](https://www.ewricongress.org/)\\n\\nThe EWRI Congress was a valuable opportunity to disseminate our research and connect with hundreds of engineers and scientists. I had the privilege of delivering three oral presentations that showcase the use-inspired science outcomes emerging from the CIROH Science and Technology Team and our partners.\\n\\n#### [1. Advancing Hydrologic Modeling through Community-Driven Development: The NextGen Framework](https://github.com/CIROH-UA)\\n\\nThis [presentation](https://alaska2025.eventscribe.net/fsPopup.asp?efp=SUlaTkJWTUEyNDE5NA&PresentationID=1583570&rnd=0.1763265&mode=presInfo) introduced the Community NextGen initiative, a collaborative effort aimed at fostering open innovation and accelerating the framework\'s development. These efforts aim to facilitate efficient research-to-operations (R2O) and operations-to-research (O2R) transitions, ultimately enhancing our ability to model and predict water resources at various scales.\\n\\n#### [2. Enhancing Catchment Based Hydrological Model Performance through Dynamic Sub-Discretization Using Land Surface Attributes](https://alaska2025.eventscribe.net/fsPopup.asp?PresentationID=1583638&mode=presInfo)\\n\\nThis talk addressed how the simplifications in lumped models can lead to reduced accuracy when applied uniformly in catchments with significant land-surface heterogeneity. The study explores the potential to enhance lumped model performance by introducing dynamic discretization based on key land-surface heterogeneities such as land use, soil type and soil layering, slope aspect, and elevation.\\n\\n#### [3. Multi-model Predictions of Design Low Flow Conditions in the Great Salt Lake Basin Using NextGen Water Resources Modeling Framework](https://alaska2025.eventscribe.net/fsPopup.asp?efp=SUlaTkJWTUEyNDE5NA&PresentationID=1603025&rnd=0.5338731&mode=presInfo)\\n\\nThis research focused on the challenge of accurately estimating low flow conditions in ungauged basins, such as those in the Great Salt Lake (GSL) region. The study paves the way to investigate how different models perform in predicting design low flow, a critical standard for water supply planning, management, and ensuring water quality in the GSL basin at both gauged and ungauged locations.\\n\\nThese works directly reflects the ongoing efforts and use-inspired science outcomes of the\xa0[CIROH\xa0Science and Technology Team and Partners across the consortium](https://ngiab.ciroh.org/#:~:text=Alabama-,Water,-Institute). The congress served as a successful platform for showcasing these advancements and CIROH\'s leadership in community-driven, next-generation water resource prediction.\\n\\n![A speaker presents at the World Environmental & Water Resources Congress, with a large screen displaying presentation details and a \'Say Cheese\' graphic with a QR code.](/img/blog/2025-06-ewri-devcon/EWRI-Koriche_MD.png)"},{"id":"may-2025-update","metadata":{"permalink":"/staging/main/blog/may-2025-update","source":"@site/blog/2025-05-16-HBV2.0.mdx","title":"\u03B4HBV2.0: How NGIAB and Wukong HPC Streamlined Advanced Hydrologic Modeling","description":"Here\'s how NGIAB and Wukong HPC enabled researchers at Pennsylvania State University to create advanced models!","date":"2025-05-16T00:00:00.000Z","tags":[{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Community Spotlight","permalink":"/staging/main/blog/tags/community-spotlight"},{"inline":true,"label":"Pennsylvania State University","permalink":"/staging/main/blog/tags/pennsylvania-state-university"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"},{"inline":true,"label":"Wukong","permalink":"/staging/main/blog/tags/wukong"},{"inline":true,"label":"HPC","permalink":"/staging/main/blog/tags/hpc"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"On-Premises Services","permalink":"/staging/main/blog/tags/on-premises-services"},{"inline":true,"label":"Cloud Services","permalink":"/staging/main/blog/tags/cloud-services"},{"inline":true,"label":"AI and Machine Learning","permalink":"/staging/main/blog/tags/ai-and-machine-learning"}],"readingTime":1.4,"hasTruncateMarker":true,"authors":[{"name":"Yalan Song","title":"Research Assistant Professor","title2":"Pennsylvania State University","url":"https://www.linkedin.com/in/yalan-song-psu/","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U0583PXP58U-02e6df150857-192","key":"yalan","page":null},{"name":"Leo Lonzarich","title":"Graduate Researcher","title2":"Pennsylvania State University","url":"https://www.linkedin.com/in/leoglonz","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U075PFL5NUE-150fbf871a79-512","key":"leo","page":null},{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null},{"name":"James Halgren","title":"Assistant Director of Science","title2":"Alabama Water Institute","url":"https://github.com/jameshalgren","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U03UDT3AMST-4a6c980b793d-512","key":"james-halgren","page":null}],"frontMatter":{"title":"\u03B4HBV2.0: How NGIAB and Wukong HPC Streamlined Advanced Hydrologic Modeling","description":"Here\'s how NGIAB and Wukong HPC enabled researchers at Pennsylvania State University to create advanced models!","slug":"may-2025-update","authors":["yalan","leo","arpita-2023","james-halgren"],"tags":["CIROH","Blog","Community Spotlight","Pennsylvania State University","Monthly Update","Wukong","HPC","NGIAB","NextGen","National Water Model","On-Premises Services","Cloud Services","AI and Machine Learning"],"hide_table_of_contents":false,"image":"img/blog/2025-05-hbv/img.jpg"},"unlisted":false,"prevItem":{"title":"Application of NOAA-OWP\'s NextGen Framework: DevCon 2025 and EWRI Congress 2025 Highlights","permalink":"/staging/main/blog/ewri-devcon25-ngiab"},"nextItem":{"title":"Google Cloud Next 2025: Innovation at Scale \u2728","permalink":"/staging/main/blog/april-2025-update"}},"content":"![Image of graphical outputs from the \u03B4HBV2.0 model](/img/blog/2025-05-hbv/img.jpg)\\n\\nPredicting water flow with precision across the vast U.S. landscape is a complex challenge. That\'s why Song et al. 2024 developed \u03B4HBV2.0, a cutting-edge hydrologic model. It\u2019s built with high-resolution modeling of physics to deliver seamless, highly accurate streamflow simulations, even down to individual sub-basins. It\'s already proven to be a major improvement, performing better than older tools at about 4,000 measurement sites. We also provide a comprehensive 40-year water dataset for ~180,000 river reaches to support this.\\n\\nPenn State research group pushed \u03B4HBV2.0 further, training it with even more detailed river data and integrating other trusted models, aiming to make it a key part of the NextGen national water modeling system (as a potential NWM3.0 successor). But here\u2019s a common hurdle: making powerful scientific tools like this easy and reliable for everyone to use within a larger framework can be tough. Setup issues, runtime errors, and inconsistent results can frustrate users.\\n\\nNGIAB stepped in to solve exactly this problem. Team has taken the complexity out of using the operations-ready models within NextGen by creating one unified, reliable package. Thanks to NGIAB, users don\'t have to worry about tricky setups or whether the model will run correctly. NGIAB ensures that our models are compatible everywhere and, most importantly, that they run exactly as designed, consistently and faithfully, every single time, no babysitting required. This means users get the full power of our advanced modeling, without the headaches.\\n\\n{/* truncate */}\\n\\n## \u{1F517} Learn more\\n\\n\u03B4HBV2.0: https://doi.org/10.5281/zenodo.14827983\\n\\nSong et al. 2024: https://agupubs.onlinelibrary.wiley.com/doi/10.1029/2024WR038928\\n\\nDataset: https://doi.org/10.5281/zenodo.13774373"},{"id":"april-2025-update","metadata":{"permalink":"/staging/main/blog/april-2025-update","source":"@site/blog/2025-04-15-GoogleCloudNext.mdx","title":"Google Cloud Next 2025: Innovation at Scale \u2728","description":"Google Cloud Next 2025","date":"2025-04-15T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"},{"inline":true,"label":"Google Cloud","permalink":"/staging/main/blog/tags/google-cloud"},{"inline":true,"label":"Google Cloud Next","permalink":"/staging/main/blog/tags/google-cloud-next"},{"inline":true,"label":"AI and Machine Learning","permalink":"/staging/main/blog/tags/ai-and-machine-learning"}],"readingTime":4.97,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"Google Cloud Next 2025: Innovation at Scale \u2728","description":"Google Cloud Next 2025","slug":"april-2025-update","authors":["arpita-2023"],"tags":["Blog","Conference","Google Cloud","Google Cloud Next","AI and Machine Learning"],"hide_table_of_contents":false,"image":"img/blog/2025-04-gcp/gcp-1.jpg"},"unlisted":false,"prevItem":{"title":"\u03B4HBV2.0: How NGIAB and Wukong HPC Streamlined Advanced Hydrologic Modeling","permalink":"/staging/main/blog/may-2025-update"},"nextItem":{"title":"\u{1F31F} UA\'s Alabama Water Institute Showcases 30-Minute Hydrological Modeling Revolution\u{1F31F}","permalink":"/staging/main/blog/march-2025-update"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\nimport { Carousel } from \\"react-responsive-carousel\\"\\n\\n\\nLast week at Google Cloud Next representing our CIROH cloud-based computing efforts! With more than 30,000 participants, Google Next always amazes me! It\'s huge, engaging on so many levels! Engaging booths, networking opportunities, great presentations, workshops, AI coach for basketball, incredible keynote from an amazing team! Event was not just a conference, but a celebration of innovation and a glimpse into the future of cloud computing! \\nGreat to see how Gemini is transforming data manipulation in BigQuery. The ability to use natural language to query, transform, and visualize data is revolutionizing how we interact with massive datasets. Gabe Weiss\'s demo particularly showcased the potential for non-specialists to derive insights from complex data.\\n\\nIf you missed the keynote, I highly recommend watching the recording here: [GCN25 Keynote Video](https://www.youtube.com/live/VABwMpL3JCo?t=3564s)\\n\\n<Carousel\\n  showThumbs={false}\\n  autoPlay={true}\\n  stopOnHover={false}\\n  useKeyboardArrows={true}\\n  emulateTouch={true}\\n  interval={3500}\\n  infiniteLoop\\n  showStatus={false}\\n  showIndicators={true}\\n  >\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-04-gcp/gcp-1.jpg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Arpita Patel at the Google Cloud Next conference\\"\\n      />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2025-04-gcp/gcp-2.jpg\\")}\\n      style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n      alt=\\"Title slide from the Google Cloud Next conference\\"\\n      />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-04-gcp/gcp-3.jpg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"Slide depicting Google\'s AI stack\\"\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-04-gcp/gcp-4.jpg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\'Slide announcing Gemini for Google Distributed Cloud\'\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-04-gcp/gcp-5.jpg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\'Slide announcing Google Agentspace\'\\n    />\\n  </div>\\n  <div style= {{ display: \'flex\', justifyContent: \'center\', alignItems: \'center\' }}>\\n  <img src={useBaseUrl(\\"/img/blog/2025-04-gcp/gcp-6.jpg\\")}\\n    style={{ width: \'auto\', maxHeight: \'500px\', borderRadius: \'8px\', boxShadow: \'0 4px 8px rgba(0, 0, 0, 0.1)\' }}\\n    alt=\\"BigQuery and Earth Engine demo at Google Cloud Next conference\\"\\n    />\\n  </div>\\n</Carousel>\\n\\n{/* truncate */}\\n\\n## \u{1F4E2} Google Distributed Cloud: Bringing Gemini On-Premises  \\n\\nPerhaps the most exciting announcement was that Gemini is now available on-premises via Google Distributed Cloud. This is a game-changer for organizations with strict data sovereignty requirements or specialized computing needs. Running on NVIDIA Confidential Computing and NVIDIA Blackwell infrastructure, this solution brings together:\\n\\n* Cutting-edge AI innovation\\n* Robust data sovereignty controls\\n* Enterprise-grade security\\n\\nThis addresses the most significant barriers many organizations face when adopting advanced AI capabilities. Learn more about this integration here: [NVIDIA and Google Cloud Partnership](https://blogs.nvidia.com/blog/google-cloud-next-agentic-ai-reasoning/?ncid=so-link-994345)\\n\\n## \u{1F4E2} Infrastructure Advances: Power to Transform  \\n\\nThe infrastructure announcements were equally impressive, with serious power upgrades including:\\n\\n* Ironwood TPUs offering massive acceleration for machine learning workloads\\n* NVIDIA Blackwell GPUs providing unprecedented computing power\\n* Rubin GPUs extending capabilities for specialized workloads\\n\\nThese hardware innovations will enable entirely new classes of applications and make existing workloads significantly more efficient.\\n\\n---\\nCheck out all the online content that\'s now available, including:\\n\\n* A 10-minute recap of the **[opening keynote](https://www.youtube.com/watch?v=dwgmfSOZNoQ)**\\n\\n* A replay of the **[developer keynote](https://cloud.withgoogle.com/next/25/session-library?session=DEVKEY&utm_source=cloud_sfdc&utm_medium=email&utm_campaign=FY25-Q2-global-EXP106-physicalevent-er-next25-mc&utm_content=global_next25_15a_Op_TY_Gen_Physical_P0&utm_term=-&pref=K&mkt_tok=ODA4LUdKVy0zMTQAAAGZ0-XTI1zyO8s06QZoyvgraE3UtbUUHR0uePcaqzFX_xqCAKR4ho4Qwooku00DFireAGAYlcr90vjFdOkYug_UvoFWtCCvWZQ2D0Bc0I3mEv-Pq4aQOho#all)**\\n\\n* **[All 200+ announcements at Next 25](https://cloud.google.com/blog/topics/google-cloud-next/google-cloud-next-2025-wrap-up?e=48754805&utm_source=cloud_sfdc&utm_medium=email&utm_campaign=FY25-Q2-global-EXP106-physicalevent-er-next25-mc&utm_content=global_next25_15a_Op_TY_Gen_Physical_P0&utm_term=-&pref=K&mkt_tok=ODA4LUdKVy0zMTQAAAGZ0-XTI69fG5pO1vzMqcs_tymd4-sQLUtRJH6j9g_F6FnNE3GwFkGx5qaC_d7bpF6BtvFK849zOz5VS6dCHtDlYAj-Pu4us2FvFnOic887xHl2eU-7N7U)**\\n\\n* **[More than 150 sessions, demos, and workshops](https://cloud.withgoogle.com/next/25/session-library?mkt_tok=ODA4LUdKVy0zMTQAAAGZ0-XTI3kqz4RKnkWcKk0PQCYROhFCDELXMik1KDwmzDWf41vgL_ELHIf_FBVQXs_dqY4WynUDvgOkY-uWPcTqY1LFvQ5_ZTu-4G3DF3Kiw3jjD2WoUlc#all)**\\n\\n* **[A recap of the event\'s biggest announcements](https://blog.google/products/google-cloud/next-2025/?utm_source=cloud_sfdc&utm_medium=email&utm_campaign=FY25-Q2-global-EXP106-physicalevent-er-next25-mc&utm_content=global_next25_15a_Op_TY_Gen_Physical_P0&utm_term=-&pref=K&mkt_tok=ODA4LUdKVy0zMTQAAAGZ0-XTI_yfyMB7QGUk4YFUIc7l-BY4tQW4ngSexZ5T54GQiwNwRk29ld_8wAYWVv39I8lBbtKokyjv8Wrdht9YFpHFVhMj8QeYF5Npd2zgjzvC_iX5wnQ)**, all in one place\\n\\n\\n---\\n\\n## \u{1F4E2} Agent Development: The Next Frontier  \\n\\nWhat particularly caught my attention was Google\'s focus on agent development technologies:\\n\\n* **google-adk**: The Agent Development Kit makes building multi-agent applications accessible to developers without deep AI expertise. [Learn more](https://developers.googleblog.com/en/agent-development-kit-easy-to-build-multi-agent-applications/)\\n* **A2A (Agent-to-Agent Communication)**: The frameworks for agent-to-agent interaction open up possibilities for complex automated workflows that were previously impossible. [Explore A2A](https://developers.googleblog.com/en/a2a-a-new-era-of-agent-interoperability/) or jump straight to the [quickstart code samples](https://a2a-protocol.org/latest/)\\n* **Agentspace**: This collaboration environment for multiple agents feels like the beginning of something truly transformative. [Check it out](https://cloud.google.com/blog/products/ai-machine-learning/google-agentspace-enables-the-agent-driven-enterprise)\\n\\n\\n## Final Thoughts\\n\\nAs I reflect on my time at Google Cloud Next 2025, I\'m struck by how the landscape of cloud computing and AI is evolving faster than ever. The convergence of powerful infrastructure, sophisticated AI models like Gemini, and new paradigms for agent-based computing signals a fundamental shift in how we\'ll architect and manage enterprise systems in the coming years.\\n\\nI left the conference not just with new knowledge but with a renewed sense of excitement about the possibilities ahead. The future of cloud computing isn\'t just about faster or cheaper computing resources\u2014it\'s about fundamentally new ways of solving problems and creating value.\\n\\n#GoogleCloudNext25 #CloudAdvocate #AI #A2A #VertexAI #GoogleDistributedCloud #DevOps #EnterpriseArchitecture"},{"id":"march-2025-update","metadata":{"permalink":"/staging/main/blog/march-2025-update","source":"@site/blog/2025-03-28-AWI-news.mdx","title":"\u{1F31F} UA\'s Alabama Water Institute Showcases 30-Minute Hydrological Modeling Revolution\u{1F31F}","description":"AWI News talks about NGIAB","date":"2025-03-28T00:00:00.000Z","tags":[{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Alabama Water Institute","permalink":"/staging/main/blog/tags/alabama-water-institute"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"}],"readingTime":0.51,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"\u{1F31F} UA\'s Alabama Water Institute Showcases 30-Minute Hydrological Modeling Revolution\u{1F31F}","description":"AWI News talks about NGIAB","slug":"march-2025-update","authors":["arpita-2023"],"tags":["CIROH","Alabama Water Institute","NGIAB","Blog","National Water Model","NextGen"],"hide_table_of_contents":false,"image":"img/logos/ngiab.png"},"unlisted":false,"prevItem":{"title":"Google Cloud Next 2025: Innovation at Scale \u2728","permalink":"/staging/main/blog/april-2025-update"},"nextItem":{"title":"Pennsylvania State University Researchers Leverage CIROH Cyberinfrastructure for Advanced Hydrological Modeling ","permalink":"/staging/main/blog/monthly-update-february-2025"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\n## \u{1F30D} AWI News\\n\\nThe Alabama Water Institute (AWI) at the University of Alabama (UA) recently published an article highlighting how NextGen In A Box (NGIAB) could transform hydrological modeling. This article provides great insight into NGIAB\'s real-world impact:\\n\\n- \u{1F680}**30-minute setup** vs days/weeks of configuration\\n- \u{1F4D6} **Provo River Basin Case Study** demonstrating rapid deployment\\n\\n<span className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/logos/ngiab.png\\")} alt=\\"ngiab image\\" style={{ width: \'30%\' }} />\\n</span>\\n\\n[\u27A1\uFE0F Read the full press release here!](https://awi.ua.edu/news/nextgen-in-a-box-ngiab-revolutionizing-hydrological-modeling-with-a-30-minute-setup/)\\n\\n{/* truncate */}\\n\\n---"},{"id":"monthly-update-february-2025","metadata":{"permalink":"/staging/main/blog/monthly-update-february-2025","source":"@site/blog/2025-02-28-PSU.mdx","title":"Pennsylvania State University Researchers Leverage CIROH Cyberinfrastructure for Advanced Hydrological Modeling ","description":"February Monthly Blog Update","date":"2025-02-28T00:00:00.000Z","tags":[{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Community Spotlight","permalink":"/staging/main/blog/tags/community-spotlight"},{"inline":true,"label":"Pennsylvania State University","permalink":"/staging/main/blog/tags/pennsylvania-state-university"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"},{"inline":true,"label":"Wukong","permalink":"/staging/main/blog/tags/wukong"},{"inline":true,"label":"AWS","permalink":"/staging/main/blog/tags/aws"},{"inline":true,"label":"HPC","permalink":"/staging/main/blog/tags/hpc"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"On-Premises Services","permalink":"/staging/main/blog/tags/on-premises-services"},{"inline":true,"label":"Cloud Services","permalink":"/staging/main/blog/tags/cloud-services"},{"inline":true,"label":"AI and Machine Learning","permalink":"/staging/main/blog/tags/ai-and-machine-learning"}],"readingTime":2.08,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null},{"name":"Yalan Song","title":"Research Assistant Professor","title2":"Pennsylvania State University","url":"https://www.linkedin.com/in/yalan-song-psu/","imageURL":"https://ca.slack-edge.com/T03UUB7CE83-U0583PXP58U-02e6df150857-192","key":"yalan","page":null},{"name":"Tadd Bindas","title":"Graduate Researcher","title2":"Pennsylvania State University","url":"https://www.linkedin.com/in/taddbindas/","imageURL":"https://avatars.githubusercontent.com/u/16233925?v=4","key":"tadd","page":null}],"frontMatter":{"title":"Pennsylvania State University Researchers Leverage CIROH Cyberinfrastructure for Advanced Hydrological Modeling ","description":"February Monthly Blog Update","slug":"monthly-update-february-2025","authors":["arpita-2023","yalan","tadd"],"tags":["CIROH","Blog","Community Spotlight","Pennsylvania State University","Monthly Update","Wukong","AWS","HPC","National Water Model","On-Premises Services","Cloud Services","AI and Machine Learning"],"hide_table_of_contents":false,"image":"https://brand.psu.edu/images/shared-images/PSU-mark-navy.jpg"},"unlisted":false,"prevItem":{"title":"\u{1F31F} UA\'s Alabama Water Institute Showcases 30-Minute Hydrological Modeling Revolution\u{1F31F}","permalink":"/staging/main/blog/march-2025-update"},"nextItem":{"title":"CIROH at AGU 2024","permalink":"/staging/main/blog/monthly-update-december-2024"}},"content":"Pennsylvania State University (PSU) researchers have been leveraging CIROH Cyberinfrastructure to tackle complex hydrological modeling challenges. This post highlights their innovative approach using the [Wukong computing platform](https://hub.ciroh.org/docs/services/on-prem/Wukong/) in conjunction with Amazon S3 bucket storage to efficiently process and analyze large-scale environmental datasets. \u{1F680}\\n\\n{/* truncate */}\\n---\\n\\n## \u{1F4BB} The Computing and Storage Infrastructure\\n\\n### **Wukong Computing Platform**\\nThe PSU team has been utilizing Wukong, a high-performance computing (HPC) cluster specifically designed for data-intensive scientific applications, such as the high-resolution physics-informed machine learning for national water modeling (Song et al. 2024[YS1] ). Wukong provides the computational power necessary for running complex simulations and processing large environmental datasets that traditional computing resources would struggle with. \u{1F50D}\\n\\n\\n\\n#### Key advantages of Wukong include:\\n- \u{1F3AF} **Large GPU capacity** for high-resolution ML/differentiable process-based models\\n- \u2699\uFE0F **Scalable parallel processing** capabilities\\n- \u{1F680} **Optimized performance** for data-intensive workloads\\n- \u23F3 **Reduced processing time** for big data\\n- \u{1F310} **Support for multi-node computation** to handle larger geographical areas\\n\\n#### **S3 Bucket Integration**: \\nTo complement Wukong\u2019s computational power, the PSU researchers and AWI DevOps staff implemented **Amazon S3 (Simple Storage Service)** buckets as their secondary data storage solution. This integration offers several benefits:\\n- \u{1F5C4}\uFE0F **Virtually unlimited storage capacity** for growing datasets\\n- \u{1F512} **Data durability and redundancy**\\n- \u{1F4B0} **Cost-effective long-term storage**, with the use of S3 intelligent tiering to automate the storage cost savings by moving data when access patterns change\\n- \u{1F504} **Seamless data transfer** between computing nodes\\n- \u{1F4DD} **Version control** for dataset iterations\\n- \u{1F91D} **Easy data sharing** with users not on Wukong\\n\\n---\\n\\n## \u{1F52C} Research Applications\\n\\nThe PSU team has applied this powerful computing infrastructure to several critical research areas:\\n\\n1. **National Streamflow Modeling** \u{1F30A}  \\n   Training differentiable hydrologic models with high-resolution forcing and static attribute data across extensive geographical regions using observations from thousands of gauges, followed by whole-domain forwarding.\\n\\n2. **National River Routing** \u{1F5FA}\uFE0F  \\n   Conducting river routing on MERIT/HydroFabric river networks, combined with neural network-supported routing parameter learning.\\n\\n3. **NextGen Candidate Models & Data Assimilation** \u{1F504}  \\n   Applying multiple NextGen candidate models and data assimilation algorithms within the differentiable modeling framework, which supports compliance with [BMI](https://doi.org/10.5281/zenodo.14827983).\\n\\n4. **Foundation Model Development** \u{1F3DE}\uFE0F  \\n   Developing a foundation model to explore co-evolution between landscapes.\\n\\n---\\n\\n### Thank you to all those who contributed towards this effort.\\n\\n## \u{1F517} Learn More\\nFor more details on the Wukong computing platform, check out the official documentation:  \\n\u{1F449} [Wukong Documentation](https://hub.ciroh.org/docs/services/on-prem/Wukong/)\\n\\nFor the full research paper by Song et al. (2024), visit:  \\n\u{1F449} [DOI: 10.22541/essoar.172736277.74497104/v1](https://doi.org/10.22541/essoar.172736277.74497104/v1)\\n\\n---"},{"id":"monthly-update-december-2024","metadata":{"permalink":"/staging/main/blog/monthly-update-december-2024","source":"@site/blog/2024-12-19-AGU2024.mdx","title":"CIROH at AGU 2024","description":"December Monthly Blog Update","date":"2024-12-19T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"}],"readingTime":1.22,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"CIROH at AGU 2024","description":"December Monthly Blog Update","slug":"monthly-update-december-2024","authors":["arpita-2023"],"tags":["Blog","Conference","CIROH","Monthly Update"],"hide_table_of_contents":false,"image":"img/blog/2024-12-agu24/AGU24_02.gif"},"unlisted":false,"prevItem":{"title":"Pennsylvania State University Researchers Leverage CIROH Cyberinfrastructure for Advanced Hydrological Modeling ","permalink":"/staging/main/blog/monthly-update-february-2025"},"nextItem":{"title":"Community NextGen Updates","permalink":"/staging/main/blog/monthly-update-november-2024"}},"content":"AGU24 brought together the world\u2019s leading minds in Earth and space sciences. CIROH participated actively, showcasing advances in water prediction, modeling techniques and many more technologies.\\n\\n## **Presentations and Posters** \u{1F4CA}\\nThe conference provided an excellent platform for CIROH researchers to present their groundbreaking work. Our team delivered impactful presentations and poster sessions highlighting CIROH\u2019s innovative work, including advancements in water prediction systems \\nand community water modeling.\\n\\nThese sessions sparked thought-provoking discussions and fostered collaborations with other researchers. For those who missed it, **posters and presentation slides are now available** [here](https://github.com/CIROH-UA/Conferences/tree/main/AGU24). Feel free to explore these materials and share your thoughts. \u{1F4DD}\\n\\n{/* truncate */}\\n\\n### Contribute Your Posters or Presentations!\\nIf any CIROH researchers would like to add their own posters or presentations to this repository, please feel free to send a [pull request (PR)](https://github.com/CIROH-UA/Conferences/pulls). We welcome contributions and encourage collaboration!\\n\\n\\n\\n\\n## Photo Gallery \u{1F4F8}\\n\\nWe captured some unforgettable moments from AGU 2024. From vibrant sessions to meaningful conversations at our booth, here\u2019s a glimpse:\\n\\n![AGU24_02](/img/blog/2024-12-agu24/AGU24_02.gif  \\"AGU24 Images\\")\\n![AGU24_01](/img/blog/2024-12-agu24/AGU24_01.jpg  \\"AGU24 Images\\")\\n![AGU24_05](/img/blog/2024-12-agu24/AGU24_05.gif  \\"AGU24 Images\\")\\n![AGU24_06](/img/blog/2024-12-agu24/AGU24_06.jpeg  \\"AGU24 Images\\")\\n![AGU24_07](/img/blog/2024-12-agu24/AGU24_07.jpg  \\"AGU24 Images\\")\\n![AGU24_03](/img/blog/2024-12-agu24/AGU24_03.gif  \\"AGU24 Images\\")\\n![AGU24_04](/img/blog/2024-12-agu24/AGU24_04.gif  \\"AGU24 Images\\")"},{"id":"monthly-update-november-2024","metadata":{"permalink":"/staging/main/blog/monthly-update-november-2024","source":"@site/blog/2024-11-29-CommunityNextGen.mdx","title":"Community NextGen Updates","description":"November Monthly Blog Update","date":"2024-11-29T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"NextGen Datastream","permalink":"/staging/main/blog/tags/next-gen-datastream"},{"inline":true,"label":"Singularity","permalink":"/staging/main/blog/tags/singularity"},{"inline":true,"label":"HPC","permalink":"/staging/main/blog/tags/hpc"},{"inline":true,"label":"TEEHR","permalink":"/staging/main/blog/tags/teehr"},{"inline":true,"label":"Hydrofabric","permalink":"/staging/main/blog/tags/hydrofabric"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"},{"inline":true,"label":"Data Preparation","permalink":"/staging/main/blog/tags/data-preparation"}],"readingTime":2.18,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"Community NextGen Updates","description":"November Monthly Blog Update","slug":"monthly-update-november-2024","authors":"arpita-2023","tags":["Blog","Monthly Update","CIROH","National Water Model","NextGen Datastream","Singularity","HPC","TEEHR","Hydrofabric","NGIAB","NextGen","Data Preparation"],"hide_table_of_contents":false,"image":"img/logos/ngiab.png"},"unlisted":false,"prevItem":{"title":"CIROH at AGU 2024","permalink":"/staging/main/blog/monthly-update-december-2024"},"nextItem":{"title":"CIROH Science Meeting 2024","permalink":"/staging/main/blog/monthly-update-october-2024"}},"content":"The Community NextGen framework has seen significant advancements in November 2024, with major updates across multiple components and exciting new resources for users. Let\'s dive into the key developments that are making hydrologic modeling more accessible and powerful than ever.\\n\\n{/* truncate */}\\n## \u{1F389} NGIAB-CloudInfra v1.3.0: A Major Milestone\\n\\nThe release of NGIAB-CloudInfra v1.3.0 marks a significant evolution in our Docker-based solution. This version introduces several groundbreaking improvements:\\n\\n- Integration with CIROH-UA\'s forked repositories of `ngen` and `t-route`\\n- Full compatibility with the latest hydrofabric v2.2\\n- New sample input data AWI-007\\n- Enhanced visualization capabilities through the NGIAB Visualizer\\n- Streamlined CI/CD pipeline with a unified Dockerfile\\n- TEEHR integration for improved evaluation capabilities\\n\\n## \u{1F4DD} New End-to-End Workflow Guide\\n\\nWe\'re excited to announce a comprehensive new end-to-end workflow video tutorial for NGIAB! This resource walks users through the entire process, making it easier than ever to get started with NextGen modeling. The tutorial is available in our [documentation](https://docs.ciroh.org/training-NGIAB-101) and provides step-by-step guidance for both new and experienced users.\\n\\n## \u{1F504} Infrastructure Updates\\n\\n### NGIAB-HPCInfra\\nThe Singularity-based solution for high-performance computing has been updated to maintain parity with the Docker implementation, including:\\n- Updated repositories alignment\\n- New sample data compatibility\\n- Enhanced documentation\\n\\n### Data Processing Tools\\n- **NGIAB-data-preprocess v3.1.2**: Major update ensuring seamless compatibility with hydrofabric v2.2\\n- **ngen-datastream**: Significant improvements with 22 new commits enhancing data handling capabilities\\n\\n## \u{1F31F} New Features\\n\\n### Hydrofabric v2.2\\nThe latest hydrofabric data model brings improved spatial representation and data organization. This update enhances the framework\'s ability to represent complex hydrologic systems accurately.\\n\\n### Repository Updates\\n- The NextGen Model Framework now operates from CIROH-UA\'s main branch\\n- T-route implementation has been updated to use the specialized datastream branch\\n- Both updates provide better integration and enhanced functionality within the NGIAB ecosystem\\n\\n## What\'s Next?\\n\\nThese November updates represent our ongoing commitment to improving the NextGen framework\'s accessibility and capabilities. With the new workflow video and documentation in place, we\'re making it easier than ever for the hydrologic modeling community to leverage these powerful tools.\\n\\nWe encourage users to:\\n1. Explore the new v1.3.0 release\\n2. Watch the end-to-end workflow video\\n3. Test out the updated data preprocess and NGIAB tools\\n4. Provide feedback on your experience\\n\\nStay tuned for more updates as we continue to enhance and expand the NextGen In A Box ecosystem!\\n\\n---\\n\\nFor detailed information about these updates, visit our repositories:\\n- [NGIAB-CloudInfra](https://github.com/CIROH-UA/NGIAB-CloudInfra)\\n- [NGIAB-HPCInfra](https://github.com/CIROH-UA/NGIAB-HPCInfra)\\n- [ngen-datastream](https://github.com/CIROH-UA/ngen-datastream)\\n- [NGIAB-data-preprocess](https://github.com/CIROH-UA/NGIAB_data_preprocess)"},{"id":"monthly-update-october-2024","metadata":{"permalink":"/staging/main/blog/monthly-update-october-2024","source":"@site/blog/2024-10-29-ScienceMeeting.mdx","title":"CIROH Science Meeting 2024","description":"October Monthly Blog Update","date":"2024-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"}],"readingTime":3.1,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"CIROH Science Meeting 2024","description":"October Monthly Blog Update","slug":"monthly-update-october-2024","authors":"arpita-2023","tags":["Blog","Monthly Update","CIROH","Conference"],"hide_table_of_contents":false,"image":"img/blog/2024-10-sci-meet/2024CSM_WomenOfCIROH.png"},"unlisted":false,"prevItem":{"title":"Community NextGen Updates","permalink":"/staging/main/blog/monthly-update-november-2024"},"nextItem":{"title":"Accessing National Water Model (NWM) Data via Google Cloud BigQuery API","permalink":"/staging/main/blog/monthly-update-september-2024"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\nThe 2024 CIROH Science Meeting was a huge success, bringing together researchers, federal partners, and consortium members both in person and virtually. We\'re excited to share the valuable resources from this year\'s meeting with the wider CIROH community.\\n\\n\\nSlides and pictures from the various sessions, keynotes, and the Federal Town Hall have all been uploaded to a shared drive for easy access. You can find links to these materials here: [Access the Shared Drive with Presentation Slides](https://drive.google.com/drive/folders/1NsJEWHQBD92ndc3FD_bFEKgqTUqTxVM3)\\n\\n{/* truncate */}\\n\\nThank you to everyone who participated in making the 2024 CIROH Science Meeting a resounding success. We look forward to continuing our collaborative research efforts across the consortium.\\n\\n\\n\\n## CIROH 2024 Science Meeting: Fostering Innovation in Hydrology\\n\\n \\n\\nThe third annual CIROH Science Meeting, held at The University of Alabama from October 14-17, 2024, brought together our vibrant community of researchers, practitioners, and stakeholders. This four-day event showcased the remarkable progress in our mission to advance national water prediction capabilities.\\n\\n \\n\\n## Meeting Highlights\\n\\n- Over 300 participants gathered to share knowledge and forge new collaborations\\n\\n- Engaging discussions spanning critical topics in hydrology\\n\\n- Special focus on CIROH\'s four key research themes:\\n\\n  - Next Generation Water Prediction\\n\\n  - Community Modeling\\n\\n  - Hydroinformatics\\n\\n  - Social Science in Water Resources\\n\\n \\n\\n## Community Engagement\\n\\nThe meeting featured presentations from our consortium members, research partners, and key stakeholders including NOAA/NWS. The diverse agenda included keynotes, project presentations, roundtable discussions, poster sessions, and HIF tour that fostered meaningful discussions about the future of water prediction.\\n\\n \\n\\nRepresentatives from our member institutions and various partnering organizations contributed to rich dialogues about advancing the National Water Model and related technologies. The collaborative atmosphere exemplified CIROH\'s commitment to building a stronger hydroinformatics community.\\n\\n \\n\\n## Key Outcomes\\n\\n- Strengthened partnerships across the consortium\\n\\n- Shared progress on ongoing research initiatives\\n\\n- Identified new opportunities for cross-institutional collaboration\\n\\n- Advanced discussions on improving national water prediction capabilities\\n\\n- Enhanced understanding of community needs and priorities\\n\\n \\n\\n## Looking Forward\\n\\nThe success of the 2024 Science Meeting reinforces CIROH\'s role in shaping the future of water prediction. The connections made and ideas shared during these four days will continue to influence our work throughout the year as we strive to improve water prediction capabilities for the nation.\\n\\n \\n\\n## Photo Gallery\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2024-10-sci-meet/2024CSM_GroupPano.png\\")} alt=\\"CIROH 2024 Science Meeting\\" style={{ width: \'100%\', marginBottom: \'2rem\' }} />\\n</div>\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2024-10-sci-meet/2024CSM_WomenOfCIROH.png\\")} alt=\\"CIROH 2024 Science Meeting\\" style={{ width: \'100%\', marginBottom: \'2rem\' }} />\\n</div>\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2024-10-sci-meet/science-meeting2024-2.jpeg\\")} alt=\\"CIROH 2024 Science Meeting\\" style={{ width: \'100%\', marginBottom: \'2rem\' }} />\\n</div>\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2024-10-sci-meet/science-meeting2024-3.jpeg\\" )}alt=\\"CIROH 2024 Science Meeting\\" style={{ width: \'100%\', marginBottom: \'2rem\' }} />\\n</div>\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2024-10-sci-meet/science-meeting2024-1.jpeg\\")}alt=\\"CIROH 2024 Science Meeting\\" style={{ width: \'100%\', marginBottom: \'2rem\' }} />\\n</div>\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2024-10-sci-meet/science-meeting2024-4.jpeg\\" )}alt=\\"CIROH 2024 Science Meeting\\" style={{ width: \'100%\', marginBottom: \'2rem\' }} />\\n</div>\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n    <img src={useBaseUrl(\\"/img/blog/2024-10-sci-meet/science-meeting2024-5.jpeg\\" )}alt=\\"CIROH 2024 Science Meeting\\" style={{ width: \'100%\'}} />\\n</div>\\n\\n\\n\\n \\n\\n## Conclusion\\n\\nThe 2024 CIROH Science Meeting demonstrated the power of collaboration in advancing hydrology. As we move forward, the energy and insights from this gathering will fuel our continued efforts to enhance water prediction capabilities and serve our communities better."},{"id":"monthly-update-september-2024","metadata":{"permalink":"/staging/main/blog/monthly-update-september-2024","source":"@site/blog/2024-09-30-BigQuery.mdx","title":"Accessing National Water Model (NWM) Data via Google Cloud BigQuery API","description":"September Monthly Blog Update","date":"2024-09-30T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"BYU","permalink":"/staging/main/blog/tags/byu"},{"inline":true,"label":"BigQuery","permalink":"/staging/main/blog/tags/big-query"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"Google Cloud","permalink":"/staging/main/blog/tags/google-cloud"},{"inline":true,"label":"Cloud Services","permalink":"/staging/main/blog/tags/cloud-services"}],"readingTime":3.01,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"Accessing National Water Model (NWM) Data via Google Cloud BigQuery API","description":"September Monthly Blog Update","slug":"monthly-update-september-2024","authors":"arpita-2023","tags":["Blog","Monthly Update","CIROH","BYU","BigQuery","National Water Model","Google Cloud","Cloud Services"],"hide_table_of_contents":false,"image":"img/blog/2024-09-bigquery/gcp_architecture_diagram.png"},"unlisted":false,"prevItem":{"title":"CIROH Science Meeting 2024","permalink":"/staging/main/blog/monthly-update-october-2024"},"nextItem":{"title":"CIROH Cloud User Success Story","permalink":"/staging/main/blog/monthly-update-august-2024"}},"content":"import Link from \'@docusaurus/Link\'\\nimport useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\n<img src={useBaseUrl(\\"/img/blog/2024-09-bigquery/gcp_architecture_diagram.png\\")} alt=\\"gcp architectrure diagram\\"/>\\n*Image Source: [https://github.com/BYU-Hydroinformatics/api-nwm-gcp](https://github.com/BYU-Hydroinformatics/api-nwm-gcp)*\\n \\n<br />\\n<br />\\n\\n# Accessing National Water Model (NWM) Data via Google Cloud BigQuery API\\nSeveral important historical and ongoing National Water Model (NWM) datasets are now available on Google Cloud BigQuery, which makes them queryable through SQL using Google Cloud console. Some of these data sets are also accessible through an API (e.g. using Python). These datasets and their current status are as follows:\\n\\n<table style={{ width: \'100%\', display: \'inline-table\' }}>\\n<tr>\\n    <td>Product</td>\\n    <td>Cloud Console SQL</td>\\n    <td>CIROH API</td>\\n    <td>Historical</td>\\n    <td>Daily Updates</td>\\n</tr>\\n<tr>\\n    <td>Medium-range forecasts</td>\\n    <td>X</td>\\n    <td>X</td>\\n    <td>X</td>\\n    <td>X</td>\\n</tr>\\n<tr>\\n    <td>Long-range forecasts</td>\\n    <td>X</td>\\n    <td>X</td>\\n    <td>X</td>\\n    <td>X</td>\\n</tr>\\n<tr>\\n    <td>Analysis and Assimilation</td>\\n    <td>X</td>\\n    <td>X</td>\\n    <td>X</td>\\n    <td>X</td>\\n</tr>\\n<tr>\\n    <td>Retrospective Data (NWM v3)</td>\\n    <td>X</td>\\n    <td></td>\\n    <td>X</td>\\n    <td></td>\\n</tr>\\n<tr>\\n    <td>Return Periods</td>\\n    <td>X</td>\\n    <td></td>\\n    <td>X</td>\\n    <td></td>\\n</tr>\\n</table>\\n{/* truncate */}\\nTo gain access and run queries on BigQuery:\\n\\n- Submit the NWM BigQuery API Data Access Form, available [here.](https://hub.ciroh.org/docs/products/data-management/bigquery-api/)\\n- Once approved, the CIROH IT team will cover the costs associated with your queries.\\n- Initially, each organization or project may request a usage limit of up to $500 per month for accessing the data through BigQuery.\\n \\n\\nThis service offers a convenient and efficient way to interact with NWM data for your research and analysis needs.\\n\\n \\n\\n## Public-Private Partnership: Advancing Water Resource Management\\n\\n \\n\\nThe National Water Model (NWM) BigQuery project exemplifies a successful collaboration between public and private sectors, uniting government-generated data with modern, cutting-edge cloud technology. This collaboration addresses several key aspects:\\n\\n \\n\\n- **Improved Data Access**: By leveraging Google Cloud BigQuery, a private sector platform, the project dramatically improves access to public NWM data. This partnership makes valuable water resource information more readily available to researchers, policymakers, and the public.\\n- **Technological Innovation**: The integration of NWM data with BigQuery showcases how private sector technology can enhance the utility of public sector data. This synergy promotes innovation in data analysis and visualization techniques.\\n- **Cost-Effective Solutions**: The CIROH DevOps team\'s commitment to covering query costs demonstrates how public funding can be strategically used to make private sector tools accessible to a wider audience, particularly in the academic and research communities.\\n- **Capacity Building**: This initiative helps build capacity across sectors by providing researchers and organizations with powerful tools to analyze water resource data, potentially leading to better-informed decision-making in water management.\\n- **Scalability and Efficiency**: By utilizing Google\'s cloud infrastructure, the project ensures that the growing volume of NWM data can be efficiently stored, accessed, and analyzed, addressing the scalability challenges often faced by public sector IT resources.\\n- **Cross-Sector Collaboration**: This project fosters collaboration between government agencies, academic institutions, and private technology companies, creating a model for future partnerships in environmental and resource management.\\n- **Open Science Promotion**: By making NWM data more accessible, this partnership supports the principles of open science, encouraging transparency and reproducibility in water resource research.\\n \\n\\nThis public-private partnership not only enhances the value of the National Water Model but also sets a precedent for future collaborations that can drive innovation in environmental data management and analysis."},{"id":"monthly-update-august-2024","metadata":{"permalink":"/staging/main/blog/monthly-update-august-2024","source":"@site/blog/2024-08-28-Case-Studies.mdx","title":"CIROH Cloud User Success Story","description":"August Monthly Blog Update","date":"2024-08-28T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"},{"inline":true,"label":"AWS","permalink":"/staging/main/blog/tags/aws"},{"inline":true,"label":"Google Cloud","permalink":"/staging/main/blog/tags/google-cloud"},{"inline":true,"label":"JupyterHub","permalink":"/staging/main/blog/tags/jupyter-hub"},{"inline":true,"label":"HPC","permalink":"/staging/main/blog/tags/hpc"},{"inline":true,"label":"NextGen Datastream","permalink":"/staging/main/blog/tags/next-gen-datastream"},{"inline":true,"label":"Cloud Services","permalink":"/staging/main/blog/tags/cloud-services"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"TEEHR. NGIAB","permalink":"/staging/main/blog/tags/teehr-ngiab"}],"readingTime":2.9,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"CIROH Cloud User Success Story","description":"August Monthly Blog Update","slug":"monthly-update-august-2024","authors":"arpita-2023","tags":["Blog","CIROH","Monthly Update","AWS","Google Cloud","JupyterHub","HPC","NextGen Datastream","Cloud Services","National Water Model","TEEHR. NGIAB"],"hide_table_of_contents":false,"image":"img/blog/2024-08-case-studies/ngen-datastream-august-blog.jpg"},"unlisted":false,"prevItem":{"title":"Accessing National Water Model (NWM) Data via Google Cloud BigQuery API","permalink":"/staging/main/blog/monthly-update-september-2024"},"nextItem":{"title":"CIROH Research CyberInfrastructure Update","permalink":"/staging/main/blog/it-update-july-2023"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\nThis month, we are excited to showcase two case studies that utilized our cyberinfrastructure tools and services. These case studies demonstrate how CIROH\'s cyberinfrastructure is being utilized to support hydrological research and operational advancements.\\n\\n\\n\\n## 1. ngen-datastream and NGIAB\\n<span className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-08-case-studies/ngen-datastream-august-blog.jpg\\")} alt=\\"ngen-datastream image\\" style={{ width: \'80%\' }} />\\n</span>\\n{/* truncate */}\\n### Overview:\\n\\nCIROH\u2019s cloud computing resources have allowed for the development of ngen-datastream, which automates the process of collecting and formatting input data for NextGen, orchestrating the NextGen run through NextGen In a Box (NGIAB), and handling outputs. This software allows users to run NextGen in an efficient, relatively painless, and reproducible fashion, increasing community access to the NextGen framework. ngen-datastream is already community accessible (https://github.com/CIROH-UA/ngen-datastream/tree/main) and making an impact on research.  A major component of this software is the Amazon Web Services (AWS) cloud-based research datastream (https://github.com/CIROH-UA/ngen-datastream). The research datastream is a CONUS-wide recurring NextGen simulation configured by the community. The terraform to build the AWS infrastructure exists in the ngen-datastream repository and current development focuses on CI/CD and enabling community contribution to the research datastream via edits to the NextGen configuration. Ultimately, these tools help distribute access throughout the community to cutting edge hydrologic research, maximizing the pace of progress of research to operations in hydrology.\\n\\n### Contribution to CIROH: \\n\\n- **Automation**: It automates the process of collecting, formatting, and validating input data for NextGen, streamlining model preparation.\\n- **Flexibility**: It allows users to provide their own input files to run NextGen.\\n- **Scalable Infrastructure**: It utilizes AWS state machine to provide access to high-performance computing (HPC) resources.\\n\\n\\n### Infrastructure Utilized: \\n\\n- **Elastic Compute Cloud (EC2)**\\n- **Simple Storage Service (S3)** \\n- **AWS Lamda and Step Functions**\\n\\n\\n## 2. TEEHR\\n\\n- **PI** : Katie van Wekhoven\\n- **Co-PI** : Matt Denno (Development Lead)\\n- **Developer** : Sam Lamont\\n\\n### Project Overview:\\n\\nThe goal of this project is to investigate, design, and build a prototype hydrologic model/forecast evaluation system (TEEHR) that will significantly improve our ability to evaluate continental-scale datasets and will provide a robust and consistent evaluation tool for CIROH and OWP research. Design priorities include easy integration into common research workflows, rapid execution of large-scale evaluations, simplified exploration of performance trends and drivers, inclusion of common and emergent evaluation methods, efficient data structures, open-source and community development, and easy extensibility.\\n\\n\\n<span className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-08-case-studies/teehr-image.png\\")} alt=\\"teehr image\\" style={{ width: \'40%\' }} />\\n</span>\\n\\n### Contribution to CIROH: \\n\\n- **TEEHR-HUB**: It is a JupyterHub environment, running the TEEHR image, with AWS services (EFS and S3) to provide a scalable platform for hydrologic research.\\n- **Data Processing**: TEEHR-HUB has successfully processed the AORC (v3.0 retrospective) gridded precipitation data to the MERIT basins, as well as the CONUS 40-year retrospective (v3.0 and USGS).\\n- **Testbed Integration**: TEEHR-HUB\u2019s compatibility with various testbeds allows researchers to experiment with different hydrologic models and datasets.\\n- **Evaluation** - TEEHR is being used (or is planned for use) by several CIROH research teams to evaluate large scale model results.\\n\\n### Infrastructure Utilized: \\n\\n- **Elastic Kubernetes Service (EKS)** (including supporting AWS services) - Scalable computing resources to host JupyterHub Dask and Spark\\n- **Elastic File System (EFS)** - Shared data drive for cached data and shared documents (notebooks, etc.)\\n- **Simple Storage Service (S3)** - Bucket storage for large public and private datasets"},{"id":"it-update-july-2023","metadata":{"permalink":"/staging/main/blog/it-update-july-2023","source":"@site/blog/2024-07-31-IT-Update.mdx","title":"CIROH Research CyberInfrastructure Update","description":"July Monthly IT Update","date":"2024-07-31T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"2i2c","permalink":"/staging/main/blog/tags/2-i-2-c"},{"inline":true,"label":"Google Cloud","permalink":"/staging/main/blog/tags/google-cloud"},{"inline":true,"label":"AWS","permalink":"/staging/main/blog/tags/aws"},{"inline":true,"label":"BigQuery","permalink":"/staging/main/blog/tags/big-query"},{"inline":true,"label":"BYU","permalink":"/staging/main/blog/tags/byu"},{"inline":true,"label":"JupyterHub","permalink":"/staging/main/blog/tags/jupyter-hub"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"}],"readingTime":1.86,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"CIROH Research CyberInfrastructure Update","description":"July Monthly IT Update","slug":"it-update-july-2023","authors":"arpita-2023","tags":["Blog","Monthly Update","CIROH","2i2c","Google Cloud","AWS","BigQuery","BYU","JupyterHub","National Water Model"],"hide_table_of_contents":false,"image":"img/blog/2024-07-it/summer-institute.jpg"},"unlisted":false,"prevItem":{"title":"CIROH Cloud User Success Story","permalink":"/staging/main/blog/monthly-update-august-2024"},"nextItem":{"title":"CIROH Developers Conference 2024","permalink":"/staging/main/blog/devcon24-retrospective"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\nWe\'re excited to share some recent developments and updates from CIROH\'s Research CyberInfrastructure team:\\n\\n### Cloud Infrastructure\\n\\n- CIROH\'s Google Cloud Account is now fully operational and managed by our team. You can find more information [here.](https://hub.ciroh.org/docs/services/cloudservices/google-cloud/)\\n- We\'re in the process of migrating our 2i2c JupyterHub to CIROH\'s Google Cloud account.\\n- We\'ve successfully deployed the Google BigQuery API (developed by BYU and Google) for NWM data in our cloud. To access this API, please contact us at ciroh-it-support@ua.edu. Please refer to [NWM BigQuery API](https://hub.ciroh.org/docs/products/data-management/bigquery-api/) to learn more.\\n{/* truncate */}\\n### Support and Services\\n- Monthly AWS office hours are ongoing. For more details on how to join, email us at ciroh-it-support@ua.edu.\\n- We provided IT support for the Summer Institute 2024, REU students, and team leads this summer.\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-07-it/summer-institute.jpg\\" )}alt=\\"summer-institute-students\\" style={{ width: \'80%\' }} />\\n</div>\\n\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-07-it/reu.jpg\\")} alt=\\"reu-institute-students\\" style={{ width: \'80%\' }} />\\n</div>\\n\\n### Security Enhancements\\n- New security features have been added to our CIROH-UA GitHub repository to prevent commits containing sensitive information.\\n- We\'ve updated our AWS best practices, particularly regarding key management. If your project uses CIROH AWS resources, please review these updates at [AWS Best Practices](https://hub.ciroh.org/docs/services/cloudservices/aws/documentation/aws-best-practice/).\\n\\n### Resources and Access\\n- For external IT resources needed for your projects, check out NSF Access Allocations [here.](https://hub.ciroh.org/docs/services/external-resources/nsf-access/)\\n- GPU allocation is now available on CIROH\'s 2i2c JupyterHub. To request access, please fill out [this form.](https://forms.office.com/pages/responsepage.aspx?id=jnIAKtDwtECk6M5DPz-8p4IIpHdEnmhNgjOa9FjrwGtUNlpMNTIwT0ZHUjg5VzdTNzNOSVk5OEFNMC4u)\\n\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-07-it/si.jpg\\")} alt=\\"summer-institute-students\\" style={{ width: \'80%\' }} />\\n</div>\\n\\nFor more information on our services, please refer to our [services page](https://hub.ciroh.org/docs/services/intro).\\n\\nWe\'re continually working to improve our IT infrastructure and support. If you have any questions or need assistance, don\'t hesitate to reach out to us at ciroh-it-support@ua.edu."},{"id":"devcon24-retrospective","metadata":{"permalink":"/staging/main/blog/devcon24-retrospective","source":"@site/blog/2024-5-02-DevCon24.mdx","title":"CIROH Developers Conference 2024","description":"CIROH Developers Conference 2024","date":"2024-05-02T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"},{"inline":true,"label":"CIROH DevCon","permalink":"/staging/main/blog/tags/ciroh-dev-con"},{"inline":true,"label":"Flood Inundation Mapping","permalink":"/staging/main/blog/tags/flood-inundation-mapping"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"AI and Machine Learning","permalink":"/staging/main/blog/tags/ai-and-machine-learning"}],"readingTime":1.59,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"CIROH Developers Conference 2024","description":"CIROH Developers Conference 2024","slug":"devcon24-retrospective","authors":"arpita-2023","tags":["Blog","CIROH","Conference","CIROH DevCon","Flood Inundation Mapping","National Water Model","AI and Machine Learning"],"hide_table_of_contents":false,"image":"img/blog/2024-05-devcon24/devcon24_02.jpeg"},"unlisted":false,"prevItem":{"title":"CIROH Research CyberInfrastructure Update","permalink":"/staging/main/blog/it-update-july-2023"},"nextItem":{"title":"AWRA 2024 Spring Conference","permalink":"/staging/main/blog/awra-2024-spring"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\n**CIROH Developers Conference 2024**\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-05-devcon24/devcon24_01.jpeg\\")} alt=\\"DevCon2024\\" style={{ width: \'80%\' }} />\\n</div>\\n\\nThe CIROH team recently participated in the **2nd Annual CIROH Developers Conference (DevCon24)**, held from May 29th to June 1st,2024. The conference brought together a diverse group of water professionals to exchange knowledge and explore cutting-edge research in the field of hydrological forecasting.\\n{/* truncate */}\\nReflecting CIROH\'s current research focus, the conference explored topics including hydrological modeling (NextGen), flood inundation mapping, hydroinformatics, social science, and community engagement. Attendees got the opportunity to delve deeper into specific areas through its well-structured training track. This year the tracks were:\\n* **NextGen**\\n* **Flood Inundation Mapping (FIM)**\\n* **Hydrological Applications of Machine Learning (ML)**\\n* **Hydroinformatics**\\n* **Cross-cutting**\\n\\nThis year, various workshops leveraged cloud technologies. Notably, we provided access to the 2i2c JupyterHub environment, a cloud-based platform for interactive computing, for ten workshops. This facilitated seamless access to powerful computing resources for participants. Additionally, we provided AWS instances to support four workshops.\\n\\n \\n\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-05-devcon24/devcon24_04.JPG\\")} alt=\\"DevCon2024\\" style={{ width: \'80%\' }} />\\n</div>\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-05-devcon24/devcon24_06.png\\")} alt=\\"DevCon2024\\" style={{ width: \'80%\' }} />\\n</div>\\n<br/>\\n\\n**Presentation Slides:**\\n\\nYou can find the presentation slides [here](https://github.com/CIROH-UA/Conferences/tree/main/CIROHDevCon2024/NextGenTrack). To learn more about CIROH\'s work or connect with the team, visit our website at [CIROH-website](https://ciroh.ua.edu/). \\n\\n**Conference Website:**\\n\\n[Learn More](https://ciroh.ua.edu/devconference/)\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-05-devcon24/devcon24_02.jpeg\\" )}alt=\\"DevCon2024\\" style={{ width: \'80%\' }} />\\n</div>\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-05-devcon24/devcon24_05.jpg\\")} alt=\\"DevCon2024\\" style={{ width: \'80%\' }} />\\n</div>"},{"id":"awra-2024-spring","metadata":{"permalink":"/staging/main/blog/awra-2024-spring","source":"@site/blog/2024-4-16-AWRATuscaloosa.mdx","title":"AWRA 2024 Spring Conference","description":"AWRA 2024 Spring Conference","date":"2024-04-16T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"},{"inline":true,"label":"Alabama Water Institute","permalink":"/staging/main/blog/tags/alabama-water-institute"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"NextGen Datastream","permalink":"/staging/main/blog/tags/next-gen-datastream"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"}],"readingTime":1.86,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"AWRA 2024 Spring Conference","description":"AWRA 2024 Spring Conference","slug":"awra-2024-spring","authors":"arpita-2023","tags":["Blog","Conference","Alabama Water Institute","CIROH","NextGen Datastream","National Water Model","NGIAB","NextGen"],"hide_table_of_contents":false,"image":"img/blog/2024-04-AWRA/awra2024.jpeg"},"unlisted":false,"prevItem":{"title":"CIROH Developers Conference 2024","permalink":"/staging/main/blog/devcon24-retrospective"},"nextItem":{"title":"Google Cloud Next \'24: A Flood of Innovation and Inspiration","permalink":"/staging/main/blog/google-cloud-next-2024"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\n**AWRA 2024 Spring Conference**\\n\\nThe **CIROH CyberInfrastructure team** recently participated in the **AWRA 2024 Spring Conference**, co-hosted by **the Alabama Water Institute at the University of Alabama.**\\n\\nThemed \\"Water Risk and Resilience: Research and Sustainable Solutions,\\" the conference brought together a diverse group of water professionals to exchange knowledge and explore cutting-edge research in the field.\\n{/* truncate */}\\nCIROH CyberInfrastructure team presented on these topics:\\n* **Accelerating Community Contribution to the Next Generation Water Resources Modeling Framework**\\n* **Creating a community dataset for high-speed national water model data access**\\n* **Model structure selection for the flood and drought predictions using the NextGen Framework based on the extreme event simulations**\\n\\nCIROH team member **James Halgren** presented the work on **\\"Accelerating Community Contribution to the Next Generation Water Resources Modeling Framework.\\" The presentation focused on building and sharing a continuous research data stream using the NextGen Water Resources Modeling Framework with NextGen IN A Box (NGIAB).** This project, a collaboration with Lynker members, showcases the potential for open-source tools and community-driven efforts to advance water resources modeling and research.\\n\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-04-AWRA/awra2024.jpeg\\")} alt=\\"AWRA2024Spring\\" style={{ width: \'80%\' }} />\\n</div>\\n\\nCIROH team member **Sepehr Karimi** presented the work on **\\"Creating a community dataset for high-speed national water model data access\\"**\\n\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-04-AWRA/AWRA2024-2.png\\")}alt=\\"AWRA2024Spring-2\\" style={{ width: \'80%\' }} />\\n</div>\\n\\nCIROH team member **Shahab Alam** presented the work on **\\"Model structure selection for the flood and drought predictions using the NextGen Framework based on the extreme event simulations\\"**\\n\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-04-AWRA/AWRA2024-3.png\\")} alt=\\"AWRA2024Spring-3\\" style={{ width: \'80%\' }} />\\n</div>\\n\\nThese presentations showcased CIROH\'s expertise in open-source tools, community-driven efforts, and water resources modeling. The team\'s contributions sparked insightful discussions and potential collaborations for future projects.\\n\\n**Call to Action:**\\n\\nTo learn more about CIROH\'s work or connect with the team, visit our website at [CIROH-website](https://ciroh.ua.edu/).\\n\\n**Conference Website:**\\n\\n[AWRA 2024 Spring Conference website link](https://www.awra.org/Members/Events_and_Education/Events/2024-Spring-Conference/2024_Spring_Conference.aspx)"},{"id":"google-cloud-next-2024","metadata":{"permalink":"/staging/main/blog/google-cloud-next-2024","source":"@site/blog/2024-4-16-GoogleCloudNext2024.mdx","title":"Google Cloud Next \'24: A Flood of Innovation and Inspiration","description":"Google Cloud Next \'24: Las Vegas","date":"2024-04-16T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"},{"inline":true,"label":"Google Cloud","permalink":"/staging/main/blog/tags/google-cloud"},{"inline":true,"label":"Google Cloud Next","permalink":"/staging/main/blog/tags/google-cloud-next"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"BYU","permalink":"/staging/main/blog/tags/byu"}],"readingTime":4.01,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"Google Cloud Next \'24: A Flood of Innovation and Inspiration","description":"Google Cloud Next \'24: Las Vegas","slug":"google-cloud-next-2024","authors":"arpita-2023","tags":["Blog","Conference","Google Cloud","Google Cloud Next","CIROH","National Water Model","BYU"],"hide_table_of_contents":false,"image":"img/blog/2024-04-gcn/googlenext-1.jpeg"},"unlisted":false,"prevItem":{"title":"AWRA 2024 Spring Conference","permalink":"/staging/main/blog/awra-2024-spring"},"nextItem":{"title":"Monthly News Update - March 2024","permalink":"/staging/main/blog/ngiab-release-notes-03-2024"}},"content":"import useBaseUrl from \\"@docusaurus/useBaseUrl\\"\\n\\n**Google Cloud Next \'24**\\n\\nHello everyone, and thanks for stopping by!\\n\\nI recently had the incredible opportunity to attend Google Cloud Next 2024 in person for the first time, and it was truly an **amazing experience**. From **insightful keynote presentations and workshops to vibrant booths** buzzing with connections, the event was a whirlwind of innovation and inspiration.\\n{/* truncate */}\\nOne of the highlights was undoubtedly the abundance of AI announcements and advancements. Google continues to push the boundaries of what\'s possible, and it was exciting to witness the future of technology unfold.\\n\\nAmong the many highlights, **CIROH** achieved a significant milestone with its **first-ever session at Google Cloud Next**. The presentation, titled **\\"Channel the Flood Data Deluge: Unlocking the American National Water Model,\\"** [link](https://cloud.withgoogle.com/next/session-library?session=DEV209&utm_source=copylink&utm_medium=unpaidsoc&utm_campaign=FY24-Q2-global-ENDM33-physicalevent-er-next-2024-mc&utm_content=next-homepage-social-share&utm_term=-#all> ) led by **Kel Markert (Google), Dr. Dan Ames (BYU), and Michael Ames(SADA)** was a resounding success. The session [link](https://assets.swoogo.com/uploads/3771985-6615e3b5da2cf.pdf) shed light on the immense potential of the National Water Model and its ability to revolutionize water resource management.\\n <div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-04-gcn/GoogleCloudNext2024.png\\" )}alt=\\"GoogleCloudNext2024\\" style={{ width: \'80%\' }} />\\n</div>\\n\\n\\nThe conference was a truly enjoyable experience, especially collaborating with Dan, Kel, Michael and others. We had a great time  together and sharing our insights.\\n\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-04-gcn/googlenext-1.jpeg\\")} alt=\\"GoogleNext-1\\" style={{ width: \'80%\' }} />\\n</div>\\n\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-04-gcn/googlenext-2.jpeg\\")} alt=\\"GoogleNext-2\\" style={{ width: \'80%\' }} />\\n</div>\\n\\n<div className=\\"hero-image\\" style={{ textAlign: \'center\' }}>\\n        <img src={useBaseUrl(\\"/img/blog/2024-04-gcn/googlenext-3.jpeg\\")} alt=\\"GoogleNext-3\\" style={{ width: \'80%\' }} />\\n</div>\\n\\nThe **energy and enthusiasm** throughout the event were contagious, and I left feeling incredibly **motivated and inspired**. I connected with numerous individuals from diverse backgrounds, fostering **new collaborations** and sparking exciting ideas for the future of water research and technology.\\n\\nIf you\'re curious to see more about my Google Cloud Next experience, head over to **my LinkedIn post [link](https://www.linkedin.com/in/arpita0911patel/)** where I\'ve shared pictures from all three days.\\n\\nThank you for reading and stay tuned for more updates on the exciting advancements in water research and technology!\\n\\n**Want to delve deeper into the insights and announcements from Google Cloud Next?** Check out these valuable resources:\\n\\n**SADA Live:** Recap Key Cloud Technology Insights from Google Cloud Next \'24: [link](https://www.linkedin.com/events/sadalive-recapkeycloudtechnolog7181342146724073472/)\\nThis LinkedIn event offers a comprehensive overview of the key takeaways and technological advancements unveiled at the conference.\\n\\n**Day 2 Google Blog Recap:** Dive into the specifics of Day 2 at Google Cloud Next with this insightful blog post, covering topics ranging from AI and data analytics to infrastructure and security. [link](<https://cloud.google.com/blog/topics/google-cloud-next/next24-day-2-recap?utm_source=linkedin&utm_medium=unpaidsoc&utm_campaign=fy24q1-googlecloud-blog-ai-in_feed-no-brand-global&utm_content=-&utm_term=->)\\n\\n**AI Takes Center Stage:**\\n\\n-   **Gemini for Google Cloud:** The introduction of Gemini 1.5 Pro, integrated with various Google Cloud services, promises enhanced functionality, security, and AI performance across diverse applications.\\n-   **AI Infrastructure Advancements:** The AI Hypercomputer provides exceptional computational power for complex AI tasks, while Gemini API now offers models tailored for various scales, enriching the development environment.\\n-   **Vertex AI Enhancements:** New tools for low-latency applications and improved Gemini integration empower developers to build more efficient and sophisticated AI-driven applications.\\n-   **Secure AI Framework (SAIF):** Establishes rigorous security standards for AI implementations, ensuring secure and responsible AI integrations.\\n-   **AI Database Assistant:** Leverages Gemini to simplify complex queries and deepen AI integration into database management.\\n-   **Google Vids:** This innovative Workspace feature utilizes Gemini and Vertex AI to enhance digital storytelling and collaboration, revolutionizing workplace communication.\\n\\n**Infrastructure and Development:**\\n\\n-   **Google Axion Processor:** This cutting-edge processor boasts significant performance and energy efficiency improvements compared to traditional x86 instances, setting a new standard for computational efficiency.\\n[link](https://lnkd.in/g544-Tdt)\\n\\n-   **Google Distributed Cloud (GDC) Sandbox:** Enables developers to build and test services for GDC within a Google Cloud environment, simplifying the development process.\\n[link](https://lnkd.in/gcDBFt4t)\\n\\n-   **Migrate to Containers (M2C) CLI:** This new tool facilitates seamless migration of applications to containers, supporting deployment on GKE or Cloud Run.\\n[link](https://lnkd.in/gz_AmHCY)\\n\\n**Security and Data Analytics:**\\n\\n-   **AI Cyber Defense Initiative:** Revolutionizes cybersecurity by leveraging AI for innovative solutions against cyber threats.\\n-   **BigQuery as a Unified Platform:** Transforms BigQuery into a comprehensive platform for managing multimodal data and executing AI tasks, seamlessly integrated with Gemini.\\\\\\nCheck out all the announcements:  [link](https://lnkd.in/gNGYrg44)"},{"id":"ngiab-release-notes-03-2024","metadata":{"permalink":"/staging/main/blog/ngiab-release-notes-03-2024","source":"@site/blog/2024-3-31-NextGen-Update-Monthly.mdx","title":"Monthly News Update - March 2024","description":"News and release notes for Community NextGen","date":"2024-03-31T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"},{"inline":true,"label":"HPC","permalink":"/staging/main/blog/tags/hpc"},{"inline":true,"label":"Singularity","permalink":"/staging/main/blog/tags/singularity"},{"inline":true,"label":"On-Premises Services","permalink":"/staging/main/blog/tags/on-premises-services"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Conference","permalink":"/staging/main/blog/tags/conference"}],"readingTime":1.19,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"Monthly News Update - March 2024","description":"News and release notes for Community NextGen","slug":"ngiab-release-notes-03-2024","authors":"arpita-2023","tags":["Blog","Monthly Update","HPC","Singularity","On-Premises Services","National Water Model","CIROH","Conference"],"hide_table_of_contents":false,"image":"/img/logos/ngiab.png"},"unlisted":false,"prevItem":{"title":"Google Cloud Next \'24: A Flood of Innovation and Inspiration","permalink":"/staging/main/blog/google-cloud-next-2024"},"nextItem":{"title":"Monthly News Update - February 2024","permalink":"/staging/main/blog/ngiab-release-notes-02-2024"}},"content":"<strong>Accelerating Innovation: CIROH\'s March 2024 Update</strong>\\n\\n\\nThe CIROH team has been diligently accelerating research cyberinfrastructure capabilities this month. We\'re thrilled to share key milestones achieved in enhancing the Community NextGen project and our cloud/on-premises platforms.\\n{/* truncate */}\\nA significant highlight was the successful launch of our new fully operational on-premises infrastructure. Comprehensive documentation is now available [here](/docs/services/on-prem/), ensuring seamless access and utilization. Additionally, we\'ve fortified the NextGen in a Box (NGIAB) ecosystem with bug fixes, repository enhancements, and initiated work on automating the CI pipeline for the [Singularity Repo](https://github.com/CIROH-UA/Ngen-Singularity)\\n\\nEmpowering our community remains a top priority. We\'ve expanded the DocuHub knowledge base with dedicated sections on on-premises access guidelines, as well as policies and best practices for optimized infrastructure usage [here](/docs/policies/intro) . Furthermore, our team represented CIROH at the AWRA Geospatial Water Technology Conference in Orlando, sharing insights on leveraging geospatial data for water research. Refer [here](https://github.com/CIROH-UA/Conferences/tree/main/2024-03-26\\\\_AWRA\\\\_GeospatialWaterTechnology)\\n\\nAs we continue driving advancements, we extend our gratitude for your unwavering support of the Community NextGen project and CIROH\'s cyberinfrastructure endeavors. Be on the lookout for more exciting updates next month as we strive to unlock new frontiers in water science through robust computing capabilities.\\n\\n[Click Here to Visit Community NextGen and NGIAB News from March 2024](https://hub.ciroh.org/news)"},{"id":"ngiab-release-notes-02-2024","metadata":{"permalink":"/staging/main/blog/ngiab-release-notes-02-2024","source":"@site/blog/2024-2-29-NextGen-Update-Monthly.mdx","title":"Monthly News Update - February 2024","description":"News and release notes for Community NextGen","date":"2024-02-29T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"On-Premises Services","permalink":"/staging/main/blog/tags/on-premises-services"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"}],"readingTime":1.08,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"Monthly News Update - February 2024","description":"News and release notes for Community NextGen","slug":"ngiab-release-notes-02-2024","authors":"arpita-2023","tags":["Blog","Monthly Update","CIROH","On-Premises Services","National Water Model","NGIAB","NextGen"],"hide_table_of_contents":false,"image":"/img/logos/ngiab.png"},"unlisted":false,"prevItem":{"title":"Monthly News Update - March 2024","permalink":"/staging/main/blog/ngiab-release-notes-03-2024"},"nextItem":{"title":"NextGen Monthly News Update - January 2024","permalink":"/staging/main/blog/ngiab-release-notes-01-2024"}},"content":"Welcome to the February edition of the CIROH Hub blog, where we bring you the latest updates and news about the Community NextGen project and CIROH\'s Cloud and on-premise Infrastructure.\\n\\nOur team has been hard at work enhancing CIROH\'s Infrastructure and Community NextGen tools. Here are some highlights from February 2024:\\n\\n1. We successfully launched our new On-premises Infrastructure, which is now fully operational. You can find documentation for it [here](/docs/services/on-prem/).\\n{/* truncate */}\\n2. For NGIAB, we\'ve made improvements to the CI pipeline for pull requests submitted with forked repositories. Now, we automatically build and test these submissions using the CI pipeline.\\n\\n3. We\'ve added documentation for the NWMURL python package, which offers utility functions tailored for accessing National Water Model (NWM) data URLs. This library streamlines the process of accessing NWM data for various purposes, including analysis, modeling, and visualization. You can explore the documentation [here](/docs/products/data-management/dataaccess/).\\n\\n4. We\'re thrilled to announce the NextGen Track for DevCon24. The schedule is now available at: [DevCon24 Schedule](https://ciroh.ua.edu/devconference/).\\n\\nThank you for your ongoing interest and support in the Community NextGen project. Stay tuned for more exciting updates and developments next month. \u{1F60A}\\n\\n[Click Here to Visit Community NextGen and NGIAB News from Feb 2024](https://hub.ciroh.org/news/)"},{"id":"ngiab-release-notes-01-2024","metadata":{"permalink":"/staging/main/blog/ngiab-release-notes-01-2024","source":"@site/blog/2024-1-31-NextGen-Update-Monthly.mdx","title":"NextGen Monthly News Update - January 2024","description":"News and release notes for NextGen","date":"2024-01-31T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"},{"inline":true,"label":"HPC","permalink":"/staging/main/blog/tags/hpc"},{"inline":true,"label":"Singularity","permalink":"/staging/main/blog/tags/singularity"},{"inline":true,"label":"Cloud Services","permalink":"/staging/main/blog/tags/cloud-services"},{"inline":true,"label":"NextGen Datastream","permalink":"/staging/main/blog/tags/next-gen-datastream"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"}],"readingTime":1.83,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null}],"frontMatter":{"title":"NextGen Monthly News Update - January 2024","description":"News and release notes for NextGen","slug":"ngiab-release-notes-01-2024","authors":"arpita-2023","tags":["Blog","CIROH","Monthly Update","HPC","Singularity","Cloud Services","NextGen Datastream","National Water Model","NGIAB","NextGen"],"hide_table_of_contents":false,"image":"/img/logos/ngiab.png"},"unlisted":false,"prevItem":{"title":"Monthly News Update - February 2024","permalink":"/staging/main/blog/ngiab-release-notes-02-2024"},"nextItem":{"title":"NextGen Monthly News Update - December 2023","permalink":"/staging/main/blog/ngiab-release-notes-12-2023"}},"content":"Welcome to the January edition of the CIROH Hub blog, where we share the latest updates and news about the Community NextGen project monthly. NextGen is a cutting-edge hydrologic modeling framework that aims to advance the science and practice of hydrology and water resources management. In this month\'s blog, we will highlight some of the recent achievements and developments of the Community NextGen team.\\n{/* truncate */}\\nFirst, we are excited to announce that NextGen In A Box (NGIAB) is now available with Singularity support. This means that you can run NGIAB on any HPC system that does not support Docker, using Singularity containers. Singularity is a popular tool for creating and running portable and reproducible computational environments. To learn how to use NGIAB with Singularity, please visit our GitHub repository: [Ngen-Singularity](https://github.com/CIROH-UA/Ngen-Singularity).\\n\\nSecond, we have made several improvements and enhancements to NGIAB, such as updating the sample input data, upgrading the Boost library, adding auto mode run, and supporting geopackage format. You can find more details about these updates on our GitHub repository: [NGIAB-CloudInfra](https://github.com/CIROH-UA/NGIAB-CloudInfra).\\n\\nThird, we would like to share with you is the development of NextGen Datastream, a tool that automates the process of collecting and formatting input data for NextGen, orchestrating the NextGen run through NextGen In a Box (NGIAB), and handling outputs. The NextGen Datastream is a shell script that orchestrates each step in the process, using a configuration file that specifies the data sources, parameters, and options for the NextGen run. The NextGen Datastream can also generate its own internal configs and modify the configuration file as needed. You can find more details and instructions on how to use the NextGen Datastream on our GitHub repository: [ngen-datastream](https://github.com/CIROH-UA/ngen-datastream/blob/main/README.md).\\n\\nWe hope you enjoyed this blog and found it informative and useful. If you have any questions, comments, or feedback, please feel free to contact us at ciroh-it-support@ua.edu. Thank you for your interest and support in the Community NextGen project. Stay tuned for more exciting news and developments in the next month. \u{1F60A}\\n\\n[Visit NGIAB News](https://hub.ciroh.org/news)"},{"id":"ngiab-release-notes-12-2023","metadata":{"permalink":"/staging/main/blog/ngiab-release-notes-12-2023","source":"@site/blog/2023-12-30-NextGen-Update-Monthly.mdx","title":"NextGen Monthly News Update - December 2023","description":"News and release notes for NextGen","date":"2023-12-30T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"}],"readingTime":0.21,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null},{"name":"Zach Wills","title":"Software Engineer","title2":"Lynker","url":"https://github.com/orgs/CIROH-UA/people/ZacharyWills","imageURL":"https://avatars.githubusercontent.com/u/60660437?v=4","key":"zach","page":null}],"frontMatter":{"title":"NextGen Monthly News Update - December 2023","description":"News and release notes for NextGen","slug":"ngiab-release-notes-12-2023","authors":["arpita-2023","zach"],"tags":["Blog","Monthly Update"],"hide_table_of_contents":false,"image":"/img/logos/ngiab.png"},"unlisted":false,"prevItem":{"title":"NextGen Monthly News Update - January 2024","permalink":"/staging/main/blog/ngiab-release-notes-01-2024"},"nextItem":{"title":"NextGen In A Box v1.1.0 Release","permalink":"/staging/main/blog/ngiab-release-v110"}},"content":"Happy New Year!!! We are back from SFO after attending AGU last month. We are excited to share the latest updates for NGIAB, NextGen, T-route, Hydrofabric, NextGen forcings, and Community Support from December 2023.\\n\\n[Visit NGIAB News](https://hub.ciroh.org/news)\\n\\n{/* truncate */}"},{"id":"ngiab-release-v110","metadata":{"permalink":"/staging/main/blog/ngiab-release-v110","source":"@site/blog/2023-11-30-NGIAB-Updates-All.mdx","title":"NextGen In A Box v1.1.0 Release","description":"News and release notes for NGIAB","date":"2023-11-30T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"},{"inline":true,"label":"Cloud Services","permalink":"/staging/main/blog/tags/cloud-services"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"}],"readingTime":0.27,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null},{"name":"Zach Wills","title":"Software Engineer","title2":"Lynker","url":"https://github.com/orgs/CIROH-UA/people/ZacharyWills","imageURL":"https://avatars.githubusercontent.com/u/60660437?v=4","key":"zach","page":null}],"frontMatter":{"title":"NextGen In A Box v1.1.0 Release","description":"News and release notes for NGIAB","slug":"ngiab-release-v110","authors":["arpita-2023","zach"],"tags":["Blog","CIROH","Cloud Services","National Water Model","NGIAB","NextGen"],"hide_table_of_contents":false,"image":"/img/logos/ngiab.png"},"unlisted":false,"prevItem":{"title":"NextGen Monthly News Update - December 2023","permalink":"/staging/main/blog/ngiab-release-notes-12-2023"},"nextItem":{"title":"NextGen Monthly News Update - November 2023","permalink":"/staging/main/blog/ngiab-release-notes-11-2023"}},"content":"We\'ve released NGIAB v1.1.0! This release fixes issues:\\n\\n- [#21](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/21)\\n- [#67](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/67)\\n- [#44](https://github.com/CIROH-UA/NGIAB-CloudInfra/issues/44)\\n\\nMore info: https://github.com/CIROH-UA/NGIAB-CloudInfra/releases/tag/v1.1.0\\n\\n[Visit NGIAB News](https://hub.ciroh.org/news)\\n\\n{/* truncate */}"},{"id":"ngiab-release-notes-11-2023","metadata":{"permalink":"/staging/main/blog/ngiab-release-notes-11-2023","source":"@site/blog/2023-11-30-NextGen-Update-Monthly.mdx","title":"NextGen Monthly News Update - November 2023","description":"News and release notes for NextGen","date":"2023-11-30T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"Monthly Update","permalink":"/staging/main/blog/tags/monthly-update"}],"readingTime":0.13,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null},{"name":"Zach Wills","title":"Software Engineer","title2":"Lynker","url":"https://github.com/orgs/CIROH-UA/people/ZacharyWills","imageURL":"https://avatars.githubusercontent.com/u/60660437?v=4","key":"zach","page":null}],"frontMatter":{"title":"NextGen Monthly News Update - November 2023","description":"News and release notes for NextGen","slug":"ngiab-release-notes-11-2023","authors":["arpita-2023","zach"],"tags":["Blog","Monthly Update"],"hide_table_of_contents":false,"image":"/img/logos/ngiab.png"},"unlisted":false,"prevItem":{"title":"NextGen In A Box v1.1.0 Release","permalink":"/staging/main/blog/ngiab-release-v110"},"nextItem":{"title":"NextGen In A Box Updates","permalink":"/staging/main/blog/ngiab-release-notes-10-2023"}},"content":"We are excited to share the latest updates for NGIAB, NextGen, T-route, Hydrofabric, NextGen forcings and Community Support.\\n\\n[Visit NGIAB News](https://hub.ciroh.org/news)\\n\\n{/* truncate */}"},{"id":"ngiab-release-notes-10-2023","metadata":{"permalink":"/staging/main/blog/ngiab-release-notes-10-2023","source":"@site/blog/2023-10-30-NGIAB-Updates.mdx","title":"NextGen In A Box Updates","description":"News and release notes for NGIAB","date":"2023-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"DocuHub","permalink":"/staging/main/blog/tags/docu-hub"},{"inline":true,"label":"NGIAB","permalink":"/staging/main/blog/tags/ngiab"},{"inline":true,"label":"NextGen","permalink":"/staging/main/blog/tags/next-gen"}],"readingTime":0.14,"hasTruncateMarker":true,"authors":[{"name":"Arpita Patel","title":"DevOps Manager and Enterprise Architect","title2":"Alabama Water Institute","url":"https://github.com/arpita0911patel","imageURL":"https://avatars.githubusercontent.com/u/54657?v=4","key":"arpita-2023","page":null},{"name":"Zach Wills","title":"Software Engineer","title2":"Lynker","url":"https://github.com/orgs/CIROH-UA/people/ZacharyWills","imageURL":"https://avatars.githubusercontent.com/u/60660437?v=4","key":"zach","page":null}],"frontMatter":{"title":"NextGen In A Box Updates","description":"News and release notes for NGIAB","slug":"ngiab-release-notes-10-2023","authors":["arpita-2023","zach"],"tags":["Blog","DocuHub","NGIAB","NextGen"],"hide_table_of_contents":false,"image":"/img/logos/ngiab.png"},"unlisted":false,"prevItem":{"title":"NextGen Monthly News Update - November 2023","permalink":"/staging/main/blog/ngiab-release-notes-11-2023"},"nextItem":{"title":"NextGen Framework Forcings","permalink":"/staging/main/blog/nextgen-forcings-2023"}},"content":"We\'ve introduced a fresh addition within DocuHub, offering the most up-to-date insights on NGIAB and NextGen monthly updates.\\n\\n[Visit NGIAB Release Notes Page](https://hub.ciroh.org/news)\\n\\n{/* truncate */}"},{"id":"nextgen-forcings-2023","metadata":{"permalink":"/staging/main/blog/nextgen-forcings-2023","source":"@site/blog/2023-10-30-NextGen-Forcings.mdx","title":"NextGen Framework Forcings","description":"NextGen Framework Forcings","date":"2023-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"NextGen Datastream","permalink":"/staging/main/blog/tags/next-gen-datastream"},{"inline":true,"label":"National Water Model","permalink":"/staging/main/blog/tags/national-water-model"},{"inline":true,"label":"Blog","permalink":"/staging/main/blog/tags/blog"},{"inline":true,"label":"CIROH","permalink":"/staging/main/blog/tags/ciroh"}],"readingTime":0.34,"hasTruncateMarker":true,"authors":[{"name":"Jordan Laser","title":"Software Engineer","title2":"Lynker","url":"https://github.com/JordanLaserGit","imageURL":"https://avatars.githubusercontent.com/u/79336055?v=4","key":"jordan","page":null}],"frontMatter":{"title":"NextGen Framework Forcings","slug":"nextgen-forcings-2023","authors":"jordan","image":"img/blog/2023-10-forcings/T2D_2_TMP_2maboveground_cali.gif","tags":["NextGen Datastream","National Water Model","Blog","CIROH"],"hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"NextGen In A Box Updates","permalink":"/staging/main/blog/ngiab-release-notes-10-2023"}},"content":"## NextGen Framework Forcings\\n\\nA new [forcing processor](https://github.com/CIROH-UA/forcingprocessor) tool has been made public. This tool converts any National Water Model based forcing files into ngen forcing files. This process can be an intensive operation in compute, memory, and IO, so this tool facilitates generating ngen input and ultimately makes running ngen more accessible.\\n\\n{/* truncate */}\\n\\n### Read more\\n\\n[Visit Github](https://github.com/CIROH-UA/forcingprocessor)"}]}}')}}]);